t.guides["forever/40-50/shendralas"] = {
	["A Prowler gave up a {quest:93568}: {npc:255385}, north of the temple, knows whose it was."] = "Prowler vyplivl {quest:93568}: {npc:255385} severně od chrámu ví, čí byl.",
	["About a dozen quests on a short trip into Forever's new zone (about 45-46 for the Alliance, 47 for the Horde), then on to {zone:1444}."] = "Asi tucet questů na krátkém výletu do nové zóny Foreveru (asi 45–46 pro Alianci, 47 pro Hordu), pak dál do {zone:1444}.",
	["Back into the {area:2657}"] = "Zpět do {area:2657}",
	["Back to your route"] = "Zpět na tvou trasu",
	["Back west along the valley road and south to {npc:253471}. {quest:93016} asks you to hear him out: talk to him once more, then hand it in."] = "Zpět na západ po cestě údolím a na jih k {npc:253471}. {quest:93016} tě žádá, abys ho vyslechl: promluv s ním ještě jednou, pak ho odevzdej.",
	["East again along {area:405}'s southern edge: the {area:2657} opens into {area:16651}."] = "Znovu na východ podél jižního okraje {area:405}: {area:2657} se otevírá do {area:16651}.",
	["East along the valley road to the eastern pylon and repair it the same way, a {npc:252711} first, coming in from the west: {npc:253527} (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road."] = "Na východ po cestě údolím k východnímu pylonu a oprav ho stejně, nejdřív {npc:252711}, příchod ze západu: {npc:253527} (level 43, elitní) a jeho strážci drží jižní stranu tábora quilboarů a po cestě chodí Corpsefeeder (level 45, elitní).",
	["East along the valley road to the quilboar of {area:16677}: the second pylon stands at the eastern end of their camp. A Corpsefeeder (level 45, elite) walks this road: let it pass. The Bristlebacks (levels 42-43) attack on sight; {npc:253527} (level 43, elite) and his bodyguards hold the south side of the camp."] = "Na východ po cestě údolím ke quilboarům {area:16677}: druhý pylon stojí na východním konci jejich tábora. Po této cestě chodí Corpsefeeder (level 45, elitní): nech ho projít. Bristlebacks (level 42–43) útočí, jakmile tě uvidí; {npc:253527} (level 43, elitní) a jeho strážci drží jižní stranu tábora.",
	["East of the temple the {quest:93341} have run wild, and their plants attack on sight. Examine the pedestal at the gardens' southern end."] = "Východně od chrámu zplaněly {quest:93341} a jejich rostliny útočí, jakmile tě uvidí. Prozkoumej podstavec na jižním konci zahrad.",
	["East through the valley to the strange crystal on its pedestal: clicking it starts {quest:92914}. The Decrepit Pylon Protectors (levels 42-43) around it are the mana elementals that guard it. Corpsefeeders (level 45, elite) roam the valley east of here."] = "Na východ údolím k podivnému krystalu na podstavci: kliknutím začne {quest:92914}. Decrepit Pylon Protectors (level 42–43) kolem jsou elementálové many, kteří ho hlídají. Údolím východně odsud se toulají Corpsefeeders (level 45, elitní).",
	["Fly to {area:2408}"] = "Leť do {area:2408}",
	["Fly to {area:608}"] = "Leť do {area:608}",
	["Into the {area:2657}"] = "Do {area:2657}",
	["The {quest:93341}"] = "{quest:93341}",
	["{area:2408} flight master"] = "letový mistr {area:2408}",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
t.guides["forever/alliance/02-westfall"] = {
	["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "Zpět na sever kolem {area:918} do dolu: uvnitř pracují Kobold Diggers.",
	["Back to {zone:1453}"] = "Zpět do {zone:1453}",
	["Class trainer"] = "Trenér povolání",
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}. {object:1166} stands in the farmhouse at the {area:219}, among them: {npc:1646}' compass is inside.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Defias Pillagers a Looters drží farmy západně od {area:108}, mezi pobřežní cestou a {area:20}. {object:1166} stojí ve statku na {area:219} mezi nimi: kompas {npc:1646} je uvnitř.\nPozor: Jeskyně {area:113} je plná nahuštěných Defias, takže tam snadno natáhneš víc naráz.",
	["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Defias Rogue Wizards táboří na březích {area:86}; dropují i Red Linen Bandanas. {object:56} leží v murločí vesnici na severovýchodním břehu.",
	["Defias Trappers and Smugglers"] = "Defias Trappers a Smugglers",
	["East along the road past {area:18}: {npc:248242} and {npc:248248} stand at the foot of the tower."] = "Na východ po cestě kolem {area:18}: {npc:248242} a {npc:248248} stojí u paty věže.",
	["East along the road, then into the river south of the bridge: the {item:247813}, Axe and Toolbox lie in it. Prowlers and Young Forest Bears roam its banks."] = "Na východ po cestě, pak do řeky jižně od mostu: {item:247813}, Axe a Toolbox leží v ní. Po březích se toulají Prowlers a Young Forest Bears.",
	["Every Defias on this loop can drop a {item:829}: the Trappers and Smugglers, and the guards at {object:290}."] = "{item:829} může dropnout každý Defias na tomto okruhu: Trappers a Smugglers i stráže u {object:290}.",
	["Fill the vial at the farm's well"] = "Naplň lahvičku u studny na farmě",
	["Fill the vial at the well"] = "Naplň lahvičku u studny",
	["Finish the Goretusk Livers"] = "Dokonči Goretusk Livers",
	["Finish the {item:729}"] = "Dokonči {item:729}",
	["Finish the {quest:153}"] = "Dokonči {quest:153}",
	["Fleshrippers circle the fields along this loop: kill the ones you pass for the stew's meat."] = "Fleshrippers krouží nad poli podél tohohle okruhu: zabíjej ty, kolem kterých jdeš, kvůli masu do dušeného.",
	["The {area:113}"] = "{area:113}",
	["The {area:88}"] = "{area:88}",
	["The {area:91}"] = "{area:91}",
	["{area:20}: kill these as you meet them"] = "{area:20}: zabíjej je, jak na ně narazíš",
	["{item:2998}, from {object:1166}"] = "{item:2998}, od {object:1166}",
	["{item:6529}, from {npc:5494}"] = "{item:6529}, od {npc:5494}",
