t.guides["forever/alliance/03-darkshore"] = {
	["After using the {item:12347}, kill Xabraxxis, then click his Demon Bag on the ground to collect the talisman. If Xabraxxis despawns before you get it, retake the quest for a new bowl."] = "Po použití {item:12347} zabij Xabraxxise a pak klikni na jeho Demon Bag na zemi a seber talisman. Když Xabraxxis zmizí dřív, než ho získáš, vezmi quest znovu kvůli nové míse.",
	["At the {area:2362}"] = "U {area:2362}",
	["Back north-east into the mountains to the crystal."] = "Zpět na severovýchod do hor ke krystalu.",
	["Bears and the Blackwood camp"] = "Medvědi a tábor Blackwood",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Blackwood Pathfinders a Windtalkers drží tábor jihovýchodně od {area:442}.",
	["Blackwood furbolgs"] = "Furbolgové Blackwood",
	["By the bonfire closest to the river: summons Xabraxxis"] = "U ohně nejblíž k řece: vyvolá Xabraxxise",
	["Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time."] = "Pozor: Když zaútočíš na jedno mládě, přidají se ostatní mláďata a často i matka, takže počítej s víc protivníky naráz.",
	["Cast {spell:18960}"] = "Sešli {spell:18960}",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Vyšplhej do východních hor východně od {area:447}; {object:175524} sedí na římse.",
	["Crawler Legs"] = "Crawler Legs",
	["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and {npc:3660} (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower."] = "Východně od Buzzbox 323 se {npc:3661} skrývá u paty věže mezi Dark Strand Fanatics. Jeho dopis si nech pro Delgrena v {zone:1440}.\nPozor: V samotné věži stojí Dark Strand Voidcallers (28–29) se svými voidwalkery a {npc:3660} (31): pergameny ber od Fanatics jižně od ní a od věže se drž dál.",
	["Fill the tube at the moonwell in the village"] = "Naplň zkumavku u měsíční studny ve vesnici",
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Jen pro rybáře: {npc:10216} stojí na molu. Jeho {item:12238} se chytá přímo z mola.",
	["The {object:16393}"] = "{object:16393}",
	["{item:12191}; underwater"] = "{item:12191}; pod vodou",
	["{item:12192}; underwater"] = "{item:12192}; pod vodou",
	["{item:5270}; below ground"] = "{item:5270}; pod zemí",
	["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: pro {npc:1646} v {zone:1453}",
	["{npc:6788}, below ground"] = "{npc:6788}, pod zemí",
	["{zone:1439}: kill these as you meet them"] = "{zone:1439}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/alliance/03-darkshore-return"] = {
	["Back south"] = "Zpět na jih",
	["Back to {npc:11802}"] = "Zpět do {npc:11802}",
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Zpět k {npc:11802} v {area:2361}, pak tam {npc:11800} přepraví druidy rovnou do {area:702}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Both half pendants in your bags (the {zone:1436} half from your last {zone:1436} visit, the {zone:1439} half from the north coast): stand by the {area:2362} on the north-west shore of the lake and use a half to join them, then take the pendant to {npc:11802} with the {spell:499} hand-in. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Obě poloviny přívěsku v taškách (polovina z {zone:1436} z poslední návštěvy {zone:1436}, polovina z {zone:1439} ze severního pobřeží): stoupni si k {area:2362} na severozápadním břehu jezera a jednou polovinou je spoj, pak přívěsek odnes k {npc:11802} spolu s odevzdáním {spell:499}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}"] = "Sešli {spell:18960}",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší. Ještě nemáš letovou trasu {area:493}? Nauč se ji od {npc:10897} jižně od jezera: letová mistryně v {area:2361} vozí jen druidy z rozhovoru a žádnou trasu k naučení nemá.",
	["Cure {npc:12298}"] = "Vyléč {npc:12298}",
	["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Eskortuj ji ven z glaivy; odevzdání vezme Therysil v {zone:1440}",
	["Fine Moonstalker Pelts"] = "Fine Moonstalker Pelts",
	["The {area:443}"] = "{area:443}",
	["The {object:10076}"] = "{object:10076}",
	["The {object:12666}"] = "{object:12666}",
	["The {quest:952}"] = "{quest:952}",
	["{area:442} flight master"] = "letový mistr {area:442}",
	["{area:452}: kill these as you meet them"] = "{area:452}: zabíjej je, jak na ně narazíš",
	["{item:15851} and {item:2449}"] = "{item:15851} a {item:2449}",
	["{npc:3692}, inside {area:455}"] = "{npc:3692}, uvnitř {area:455}",
}
t.guides["forever/alliance/03-loch-modan"] = {
	["12 minutes"] = "12 minut",
	["Back down into town: {npc:415} by the smithy, {npc:341} at the north end of the bridge, {npc:381} on the docks."] = "Zpět dolů do města: {npc:415} u kovárny, {npc:341} na severním konci mostu, {npc:381} v docích.",
	["Back down to the east shore below the boars' hills: {npc:270693}, a crocolisk, patrols it among the Loch Crocolisks."] = "Zpět dolů na východní břeh pod kopci kanců: hlídkuje tam {npc:270693}, krokodýl mezi Loch Crocolisks.",
	["Back north to {npc:234} and the gryphons."] = "Zpět na sever k {npc:234} a gryfům.",
	["Back north to {npc:234}. For your {area:1581} run he then sends you after {npc:639}, and {npc:820}, beside him at the top of the tower, wants {quest:214}. Look for a group now if you have none yet."] = "Zpět na sever k {npc:234}. Na tvůj běh {area:1581} tě pak pošle za {npc:639} a {npc:820} vedle něj na vrcholu věže chce {quest:214}. Pokud ještě nemáš skupinu, hledej ji teď.",
	["Back north up the road to {area:108}. {npc:467} waits at the foot of the tower ramp; if he is missing, someone is escorting him and he is back within minutes."] = "Zpět na sever po cestě do {area:108}. {npc:467} čeká u paty rampy věže; pokud tam není, někdo ho eskortuje a za pár minut je zpátky.",
	["Back to the {area:925}"] = "Zpět do {area:925}",
	["Back to {area:442} for {zone:1439}'s southern loops: the gryphon to {zone:1453}, then the boat from the harbour. Hearthstone ready (bound in {area:442} since the first {zone:1439} visit)? Use it instead: these steps drop once you are in {zone:1439}."] = "Zpět do {area:442} na jižní kola {zone:1439}: gryfem do {zone:1453}, pak loď z přístavu. Hearthstone připravený (navázaný v {area:442} od první návštěvy {zone:1439})? Použij ho místo toho: tyhle kroky odpadnou, jakmile jsi v {zone:1439}.",
	["Back toward town, swim east from the bridge into {area:68}; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a {item:1467}.\nCareful: Lake Threshers, level 25 elites, swim in the lake: keep your distance from them while you dive for the chest."] = "Zpět směrem k městu, plav od mostu na východ do {area:68}; truhla leží na dně jezera vedle potopené lodi. Jižní břeh kolem ní lemují Murloc Flesheaters a Tidecallers: {item:1467} může nést kterýkoli z nich.\nPozor: V jezeře plavou Lake Threshers, elity levelu 25: při potápění pro truhlu se od nich drž dál.",
	["Back west along the south shore to {area:144}: {npc:1105} by the inn, then {npc:1572} with the gryphons on the west side of town, on the way south."] = "Zpět na západ po jižním břehu do {area:144}: {npc:1105} u hostince, pak {npc:1572} s gryfy na západní straně města, cestou na jih.",
	["Boat to {area:150}"] = "Loď do {area:150}",
	["Cathedral of Light"] = "Cathedral of Light",
	["Chief Engineer Hinderweir stands on top of the dam, up the ramp at its west end."] = "Chief Engineer Hinderweir stojí na vrcholu hráze, nahoru po rampě na jejím západním konci.",
	["Class trainer"] = "Trenér povolání",
	["Cross the long bridge north into town: {npc:8965} and {npc:8962} play by the shore at its north end, {npc:341} stands there too, {npc:415} by the smithy, {npc:344} in the town hall, {npc:381} on the docks, {npc:266} upstairs in the inn and {npc:379} and {npc:343} inside it."] = "Přejdi dlouhý most na sever do města: {npc:8965} a {npc:8962} si hrají u břehu na jeho severním konci, {npc:341} tam stojí taky, {npc:415} u kovárny, {npc:344} na radnici, {npc:381} v docích, {npc:266} nahoře v hostinci a {npc:379} a {npc:343} v něm.",
	["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "Defias Pathstalkers a Knuckledusters chodí po {area:20}; Highwaymen (level 17) hlídkují ve dvojicích v kopcích jižně a východně od něj: roztrhni je. Vchod do {area:1581} v kovárně je skupinový dungeon.\nPozor: Tábory v kopcích drží smíšené skupiny Defias, takže s nízkým levelem snadno natáhneš víc naráz.",
	["Down the road to {area:108}. {npc:234} stands at the top of the stone tower."] = "Dolů po cestě do {area:108}. {npc:234} stojí na vrcholu kamenné věže.",
	["Druids on Trial of the Sea Lion: from the {area:113}, west to the shore and north along it. The {object:177790} lies on the sea floor off the coast (about 18,33); then back south along the coast to the lighthouse."] = "Druidi na Trial of the Sea Lion: z {area:113} na západ k pobřeží a po něm na sever. {object:177790} leží na mořském dně u pobřeží (asi 18,33); pak zpět na jih po pobřeží k majáku.",
	["East along the hills to the mine: the Miners' League crates sit in its tunnels among the Tunnel Rat kobolds."] = "Na východ podél kopců k dolu: bedny Miners' League jsou v jeho tunelech mezi koboldy Tunnel Rat.",
	["East along the road to the gryphon master; {npc:1070} stands beside her."] = "Na východ po cestě k mistrovi gryfů; {npc:1070} stojí vedle ní.",
	["Elder Mountain Boars"] = "Elder Mountain Boars",
	["Fly to {area:1537}"] = "Leť do {area:1537}",
	["Fly to {area:69}"] = "Leť do {area:69}",
	["Fly to {zone:1453}"] = "Leť do {zone:1453}",
