t.guides["forever/alliance/04-redridge-mountains"] = {
	["Already carrying six? Hand them in now"] = "Už jich neseš šest? Odevzdej je teď",
	["Back east through town from {npc:342}'s garden: two Wanted posters hang on the town hall doorway."] = "Zpět na východ přes město z {npc:342} zahrady: na dveřích radnice visí dva plakáty Wanted.",
	["Back north along the road from {area:42} to {area:1002}."] = "Zpět na sever po cestě z {area:42} do {area:1002}.",
	["Back to {area:69}"] = "Zpět do {area:69}",
	["Blackrock camps"] = "Tábory Blackrock",
	["Continue west to {quest:163}. The {object:673515} glows by the ruined house south of the road; {npc:288} hides in the house at the west end of the village."] = "Pokračuj na západ k {quest:163}. {object:673515} září u zničeného domu jižně od cesty; {npc:288} se skrývá v domě na západním konci vesnice.",
	["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, {npc:342} in her garden at the west end. {npc:382} and {npc:341} stand at the north end of the bridge: the Blackrock camps' quests and {quest:98386} are worked on this visit's loop east of the lake."] = "Přejdi dlouhý most na sever do města: {npc:381} v docích, {npc:900} na radnici, {npc:342} ve své zahradě na západním konci. {npc:382} a {npc:341} stojí na severním konci mostu: questy táborů Blackrock a {quest:98386} se plní v okruhu této návštěvy východně od jezera.",
