t.guides["forever/alliance/05-duskwood"] = {
	["/lay down beside {npc:7207}"] = "/lay vedle {npc:7207}",
	["Back to the {area:69} gryphon master: fly to {area:42} for {zone:1431}'s second loop."] = "Zpět k mistrovi gryfů v {area:69}: leť do {area:42} na druhé kolo {zone:1431}.",
	["Back to {area:42}"] = "Zpět do {area:42}",
	["Carrion Recluses lurk in the woods on the way west, and Venom Web Spiders, Pygmy Venom Web Spiders and Green Recluses crawl just south of {npc:311}'s camp: each can drop a leg."] = "Carrion Recluses číhají v lesích cestou na západ a Venom Web Spiders, Pygmy Venom Web Spiders a Green Recluses lezou kousek jižně od tábora {npc:311}: nohu může dropnout každý.",
	["Cathedral of Light"] = "Cathedral of Light",
	["Class trainer"] = "Trenér povolání",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters and Bone Chewers (24-27) are the easier kills; Plague Spreaders and Brain Eaters (27-29) drop them too. {npc:522}, an elite, wanders the graves: keep away from him.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "Žebro může dropnout každý ghúl v severní polovině {area:492}: Flesh Eaters a Bone Chewers (24–27) se zabíjejí snáz; dropují je i Plague Spreaders a Brain Eaters (27–29). Mezi hroby se toulá {npc:522}, elita: drž se od něj dál.\nPozor: {npc:948} při smrti sesílá {spell:3428}, který přivede další posily.",
	["Fly to {area:42}"] = "Leť do {area:42}",
	["{area:492}: kill these as you meet them"] = "{area:492}: zabíjej je, jak na ně narazíš",
