	["{npc:267}, in the town hall"] = "{npc:267}, na radnici",
}
t.guides["forever/alliance/06-ashenvale"] = {
	["Back north from the glaive (Druids: south along the road from {area:442}) to the {area:448}, where {npc:11218} sleeps beside Arbal. Take his quest: it gives you the {item:13536}. Use the horn to wake him and lead him south along the road to his bag at the southern edge of {zone:1439}; blow it again whenever he falls asleep. Then go on to {npc:11219} at {area:413}.\nCareful: Scripted ambushes of three mobs each attack along the road."] = "Zpět na sever od glaivy (druidi: na jih po cestě z {area:442}) do {area:448}, kde vedle Arbala spí {npc:11218}. Vezmi jeho quest: dá ti {item:13536}. Zatrub, ať ho probudíš, a veď ho na jih po cestě k jeho vaku na jižním okraji {zone:1439}; kdykoli usne, zatrub znovu. Pak pokračuj k {npc:11219} v {area:413}.\nPozor: Po cestě útočí naplánované přepady po třech mobech.",
	["Back north through the {area:1276}: west of {area:421}, the stardust bushes grow among the ruins."] = "Zpět na sever přes {area:1276}: západně od {area:421} rostou keře stardust mezi ruinami.",
	["Back west along the road from {npc:3916}, {area:415} is on the way to {npc:3664}: {npc:3894} is inside the building beyond the inn."] = "Zpět na západ po cestě od {npc:3916}, {area:415} je cestou k {npc:3664}: {npc:3894} je v budově za hostincem.",
	["Below ground"] = "Pod zemí",
	["Boat to {area:150}"] = "Loď do {area:150}",
	["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site. Careful: Highland Lurkers and Horrors, level 28 elites, walk the same cave among them: pull the stalkers one at a time and keep clear of the elites."] = "{area:1021}, jeskyni jihovýchodně od vykopávek, plní Cave Stalkers a Leech Stalkers. Pozor: Stejnou jeskyní mezi nimi chodí Highland Lurkers a Horrors, elity levelu 28: tahej stalkery po jednom a drž se od elit dál.",
	["Escort {npc:11218} south along the road to his bag at the southern edge of {zone:1439}, then go on to {npc:11219} at {area:413}."] = "Eskortuj {npc:11218} na jih po cestě k jeho vaku na jižním okraji {zone:1439}, pak pokračuj k {npc:11219} v {area:413}.",
