	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground. Their hearts drop from level 32 elites on the {area:205} visit"] = "Nový {item:279996} pro čtyři titánské strážce kolem {zone:1437}; pod zemí. Jejich srdce padají z elitů levelu 32 při návštěvě {area:205}",
	["Alexston's reply, if you still carry it (the route hands it in on 03-darkshore-return's first {area:442} stop)"] = "Alexstonova odpověď, pokud ji pořád neseš (trasa ji odevzdá na první zastávce v {area:442} návodu 03-darkshore-return)",
