	["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "Zpět dolů po cestě do {area:205}: {npc:1075} chce zničit výbušniny {object:147516} pod vzdáleným koncem mostu.",
