t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = {
	["Back east to Nesingwary's camp on the way north to the {area:99}."] = "Zpět na východ do Nesingwaryho tábora cestou na sever k {area:99}.",
	["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "Zpět na jih kolem Nesingwaryho: Panthers a Stranglethorn Raptors běhají na mýtinách západně od tábora směrem k pobřeží; starší tygři drží kopce na jihozápadě.",
	["Both roam the grass around the camp and along the road north."] = "Oba se toulají v trávě kolem tábora a podél cesty na sever.",
	["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Pozor: Trollí tábory jsou blízko oblasti tygrů a trollové se můžou přidat do boje, když taháš neopatrně.\nPozor: V hnízdě raptorů jsou mláďata, která se přidají, když zaútočíš na dospělé.",
