t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "\"Sea Wolf\" MacKinley, v nejvyšším patře",
	["East from the ruins to the hilltop south-west of Nesingwary's camp: the Lashtail Raptors run in the jungle around it. Leave {npc:729}, the great tiger (37) on the hilltop, to the 40-50 Stranglethorn guide: you're about 35 here. Then on to the hunters' tents."] = "Na východ od ruin na vrchol kopce jihozápadně od Nesingwaryho tábora: Lashtail Raptors běhají v džungli kolem. {npc:729}, velkého tygra (37) na vrcholu kopce, nech návodu Stranglethorn 40–50: tady máš asi 35. Pak dál ke stanům lovců.",
	["East to {area:101}: Herod's records lie in a hut on its west side."] = "Na východ do {area:101}: Herodovy záznamy leží v chýši na jeho západní straně.",
