t.guides["forever/alliance/30-40/05-arathi-highlands"] = {
	["A group stop: two level 40 water elementals ambush {npc:2768}'s escort, and the Daggerspine naga in the reef are 38-40, with Sorceresses among them. Grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nSouth along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Skupinová zastávka: dva vodní elementálové levelu 40 přepadnou eskortu {npc:2768} a nagy Daggerspine na útesu mají 38–40, mezi nimi Sorceresses. Doporučuje se skupina, hledej lidi, se kterými to udělat. Když jsi sám, přeskoč to.\nNa jih po západním pobřeží do goblinské zátoky; Lolo hlídá na skalách nad ní.",
	["A {npc:2434} (37-38) lurks stealthed on the edge of {area:271}, and few players find him. Careful: he is a level or two over you; fight him only at full health, or leave him. His contract goes to {npc:2276}. Don't wait for him: the rest of this step doesn't need him."] = "Na okraji {area:271} číhá ve stealthu {npc:2434} (37–38) a málokdo ho najde. Pozor: je o level nebo dva nad tebou; bojuj s ním jen s plným zdravím, nebo ho nech být. Jeho smlouva jde k {npc:2276}. Nečekej na něj: zbytek kroku ho nepotřebuje.",
	["Back out of the grate to Modera's camp on the lake shore."] = "Zpět ven z mříže do Moderina tábora na břehu jezera.",
	["Back west through {zone:1430} to {area:42}."] = "Zpět na západ přes {zone:1430} do {area:42}.",
	["Below ground"] = "Pod zemí",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps north of the village. Leave him be."] = "Pozor: Syndicate Spies a Assassins můžou být ve stealthu. Assassins tě navíc otráví.\nPozor: {npc:2306} (40) se objevuje vždy na jednom místě: ve sklepě hostince v {area:280}, nebo v jednom ze stanových táborů Syndicate severně od vesnice. Nech ho být.",
	["City of Dalaran"] = "City of Dalaran",
	["Crushridge ogres"] = "Zlobři Crushridge",
	["East along the road to the {area:76}. The {quest:1389} are the glowing blue crystals among the Lost Ones' tents: click them. Any {npc:254797} counts for {npc:254775}, and the Lost One Fishermen on the sanctuary's west side carry {npc:254770}'s {item:258530}. {quest:1392} walks a long path through the ruins; his cudgel starts a quest for {npc:1776}. Don't wait for him.\nCareful: Noboru is level 39, two over you here: fight him only with a friend or from level 38; otherwise let him pass."] = "Na východ po cestě do {area:76}. {quest:1389} jsou zářící modré krystaly mezi stany Lost Ones: klikni na ně. Pro {npc:254775} se počítá kterýkoli {npc:254797} a Lost One Fishermen na západní straně svatyně nesou {item:258530} pro {npc:254770}. {quest:1392} chodí dlouhou trasu ruinami; jeho kyj začíná quest pro {npc:1776}. Nečekej na něj.\nPozor: Noboru má level 39, tady o dva nad tebou: bojuj s ním jen s kamarádem nebo od levelu 38; jinak ho nech projít.",
	["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Na východ od {quest:681} přes sever Highlands; úlomky se třpytí na kopci u {area:333}, severně od {area:314}.",
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Eskortuj profesora na kopec do jeskyně nad zátokou a hlídej ho, zatímco pracuje. Přepadnou ho tam dva vodní elementálové levelu 40, imunní vůči mrazu. Drž je u ústí jeskyně, daleko od něj: když se boj odehraje v jeskyni, přidá se místo práce a přicházejí další elementálové.",
	["Fly to {area:144}"] = "Leť do {area:144}",
	["Fly to {area:271}"] = "Leť do {area:271}",
	["Fly to {area:42}"] = "Leť do {area:42}",
