t.guides["forever/alliance/30-40/06-badlands"] = {
	["Buzzards circle the plain to the east. Careful: the Dustbelcher Maulers, Shamans and Wyrmhunters (40-43) camp far to the south-west: leave them.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: the Stonevault Bonesnappers are 39-40 and the Shamans 40-41, a level or two over you here: pull them from the camp's edge, one at a time.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Na pláni na východě krouží supi. Pozor: Dustbelcher Maulers, Shamans a Wyrmhunters (40–43) táboří daleko na jihozápadě: nech je být.\nPotlučená kostra leží na okraji tábora troggů Stonevault; {quest:739}, Agmondův vrah, chodí mezi Bonesnappers.\nPozor: Stonevault Bonesnappers mají 39–40 a Shamans 40–41, tady o level nebo dva nad tebou: tahej je z okraje tábora po jednom.\nPozor: Dustbelcher Lords mají level 44–45. Používají {spell:5242} a {spell:1160} a pod 50 % zdraví volají o pomoc spojence do 15 yd. Sedm jich stojí asi 750 yd jižně od {area:340}.",
	["East from the {area:1877} to {area:346}: {npc:2860} takes the scrap metal."] = "Na východ od {area:1877} do {area:346}: {npc:2860} vezme kovový šrot.",
	["Into {zone:1418}"] = "Do {zone:1418}",
	["The {object:126260}"] = "{object:126260}",
	["To {area:2101}"] = "Do {area:2101}",
	["{area:345}: kill these as you meet them"] = "{area:345}: zabíjej je, jak na ně narazíš",
	["{area:346}: kill these as you meet them"] = "{area:346}: zabíjej je, jak na ně narazíš",
	["{item:4631}; below ground"] = "{item:4631}; pod zemí",
}
t.guides["forever/alliance/30-40/06b-desolace"] = {
	["A long trip out to Kalimdor"] = "Dlouhá cesta do Kalimdoru",
	["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s {item:213565}."] = "Po {area:596} leze {npc:217590}: chyť ho nástrojem z {item:213565} od {npc:217412}.",
	["Back at the coven on the way west: the Mana Eaters (37-38) on its north edge and the Mage Hunters (38-39) further in drop the brains. {npc:5760} (40, elite) walks among the Mage Hunters: pull them out to you."] = "Zpět u covenu cestou na západ: Mana Eaters (37–38) na jeho severním okraji a Mage Hunters (38–39) dál uvnitř dropují mozky. {npc:5760} (40, elitní) chodí mezi Mage Hunters: odlákej je k sobě.",
	["Fly to {area:150}"] = "Leť do {area:150}",
	["The {area:2657}"] = "{area:2657}",
	["{area:144} flight master"] = "letový mistr {area:144}",
	["{area:598}: kill these as you meet them"] = "{area:598}: zabíjej je, jak na ně narazíš",
}
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "\"Sea Wolf\" MacKinley, v nejvyšším patře",
	["\"Sea Wolf\" MacKinley: keep it, for the level-48 {area:35} stop, with Zanzil's village"] = "\"Sea Wolf\" MacKinley: nech si ho na zastávku v {area:35} na levelu 48, se Zanzilovou vesnicí",
	["\"Stinky\" Ignatz"] = "\"Stinky\" Ignatz",
	["An {npc:217588} crawls in the jungle south-east of Nesingwary's camp, on the way to the {area:99}: catch one with the tool from {npc:217412}'s {item:213565}."] = "{npc:217588} leze v džungli jihovýchodně od Nesingwaryho tábora, cestou k {area:99}: chyť ho nástrojem z {item:213565} od {npc:217412}.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "Na 40 se se 100 zlatými můžeš naučit jezdit a naučení ti dá mounta. Skyborne se to učí u {npc:265756}, stájníka a trenéra jízdy u {area:17684} v {area:16638} na Zephras Isle, který prodává i Galestridery: vzducholoď na ostrov odlétá ze severní strany {area:279} zhruba každých pět minut. Sběratelské, Mounti · Level 40 vypisuje Galestridery.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Na 40 se se 100 zlatými můžeš naučit jezdit a naučení ti dá mounta. Lidi učí {npc:4732} v {area:88} ve východním {zone:1429}, vedle koní {npc:384}. Forever možná dovolí kterékoli rase učit se u kteréhokoli trenéra jízdy (nepotvrzeno). Sběratelské, Mounti · Level 40 vypisuje všechny barvy.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "Na 40 se se 100 zlatými můžeš naučit jezdit a naučení ti dá mounta. Noční elfy učí {npc:4753} v {zone:1457}, vedle šavlozubých koček {npc:4730}: loď z {area:17203} do {area:442}, pak let do {area:702}. Forever možná dovolí kterékoli rase učit se u kteréhokoli trenéra jízdy (nepotvrzeno), třeba u {npc:4732} v {area:88} v {zone:1429}. Sběratelské, Mounti · Level 40 vypisuje všechny barvy.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Na 40 se se 100 zlatými můžeš naučit jezdit a naučení ti dá mounta. Trpaslíky učí {npc:4772} v {area:803}, východně od {area:131} na cestě do {zone:1432}, vedle beranů {npc:1261}. Forever možná dovolí kterékoli rase učit se u kteréhokoli trenéra jízdy (nepotvrzeno). Sběratelské, Mounti · Level 40 vypisuje všechny barvy.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Na 40 se se 100 zlatými můžeš naučit jezdit a naučení ti dá mounta. Gnómy učí {npc:7954} v {area:189}, kousek východně od {area:131}, vedle mechanostriderů {npc:7955}. Forever možná dovolí kterékoli rase učit se u kteréhokoli trenéra jízdy (nepotvrzeno). Sběratelské, Mounti · Level 40 vypisuje všechny barvy.",
	["Bloodsail camp"] = "Tábor Bloodsail",
	["Bloodsail pirates: kill these as you meet them"] = "Piráti Bloodsail: zabíjej je, jak na ně narazíš",
	["Boat to {area:150}"] = "Loď do {area:150}",
	["Boat to {area:17203}"] = "Loď do {area:17203}",
	["Boat to {area:35}"] = "Loď do {area:35}",
	["Corrosive Swamp Oozes"] = "Corrosive Swamp Oozes",
	["Cortello's scroll"] = "Cortellův svitek",
	["Defeat the challengers and {npc:6238}"] = "Poraz vyzyvatele a {npc:6238}",
	["East from the stalkers' slopes to the ruins of Zul'Mamwe: the Skullsplitter Mystics (39-40) in its northern half carry {npc:739}'s fetishes. Careful: the Witch Doctors, Berserkers and Headhunters (41-44) hold the ruins' southern half: stay north. Then north-west toward the coast: the Shadowmaw Panthers (37-38) prowl the jungle west of the ruins, often stealthed."] = "Na východ od svahů stalkerů k ruinám Zul'Mamwe: Skullsplitter Mystics (39–40) v jejich severní polovině nesou fetiše pro {npc:739}. Pozor: Witch Doctors, Berserkers a Headhunters (41–44) drží jižní polovinu ruin: drž se na severu. Pak na severozápad k pobřeží: Shadowmaw Panthers (37–38) slídí v džungli západně od ruin, často ve stealthu.",
	["East from the {area:99} to {area:101}: {npc:218230} is caged at its western edge. The Kurzen Subchiefs (35-36) and Elites (36-37) carry his cage key; the fighter's uniform lies in a supply crate in the compound's eastern part.\nCareful: {npc:813}, an elite of 39-40, stands at the compound's north end beside three of the Subchiefs: take the key from the Subchiefs and Elites further south and leave him be."] = "Na východ od {area:99} do {area:101}: {npc:218230} je v kleci na jeho západním okraji. Klíč od jeho klece nesou Kurzen Subchiefs (35–36) a Elites (36–37); uniforma bojovníka leží v bedně se zásobami ve východní části areálu.\nPozor: {npc:813}, elita 39–40, stojí na severním konci areálu vedle tří Subchiefs: klíč ber od Subchiefs a Elites dál na jih a jeho nech být.",
	["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye: take them from the Raiders and Mages (39-41) at the Bloodsail camp on the beach just north of town, where you found the letter. Leave the {area:43} camp south of town (Warlocks and Swashbucklers 41-43) for the level-48 visit."] = "Každý Bloodsail dropuje Snuff a jeden z nich nese oko {npc:2493}: ber je od Raiders a Mages (39–41) v táboře Bloodsail na pláži kousek severně od města, kde jsi našel dopis. Tábor {area:43} jižně od města (Warlocks a Swashbucklers 41–43) nech na návštěvu na levelu 48.",
