t.guides["forever/alliance/40-50/01b-riverglades"] = {
	["About 90 quests in Forever's new zone, from {area:16724}: the level for its port and Western Front."] = "Asi 90 questů v nové zóně Foreveru, z {area:16724}: level pro její přístav a Western Front.",
	["Back east along the road to {area:16744}."] = "Zpět na východ po cestě do {area:16744}.",
	["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "Zpět na východ přes město na Elbrimovu farmu: panenka a medailonek jsou ve vyhořelém statku vedle ní.",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Zpět na sever po břehu: cestou k crawlerům odevzdej v docích murloky a kůži.",
	["Back past {area:16744} and south to the Holmsbys' farm by the river."] = "Zpět kolem {area:16744} a na jih na farmu Holmsbyových u řeky.",
	["Back south-west along the river: kill the Mudfin Warriors and Oracles on the banks for {npc:258317} (they drop {npc:256438}'s heads) and the {npc:258588} in the shallows for the shells. {npc:258935}, one of {npc:256438}'s lumberjacks, is stuck on the bank just north-west of the murlocs; {npc:259049}'s hat lies on the riverbank among them; the fresh manure is in the fields of {area:16735}, between the river and the farm. {npc:263380}, an elite (level 42), prowls the river: if he comes your way, back off and let him pass."] = "Zpět na jihozápad podél řeky: zabíjej Mudfin Warriors a Oracles na březích pro {npc:258317} (dropují hlavy {npc:256438}) a {npc:258588} na mělčině kvůli lasturám. {npc:258935}, jeden z dřevorubců {npc:256438}, uvízl na břehu kousek severozápadně od murloků; klobouk {npc:259049} leží na břehu mezi nimi; čerstvý hnůj je na polích {area:16735}, mezi řekou a farmou. {npc:263380}, elita (level 42), slídí po řece: když jde tvým směrem, ustup a nech ho projít.",
	["Back through the port"] = "Zpět přes přístav",
	["Back to the port, from the north pier west through the docks."] = "Zpět do přístavu, ze severního mola na západ přes doky.",
	["Back to the port."] = "Zpět do přístavu.",
	["Back to {area:16724}"] = "Zpět do {area:16724}",
	["Before the second wave: its raiders and bombardiers (43-45) and the pirates' ships after them are a level over you below 44.4. Top up on the first camp's buccaneers and musketeers (41-43) at its south-west end, away from the port. {npc:259758}, a rare elite of level 49, roams these cliffs: if you see him, keep well away. Or, with a group, run the {area:1517} dungeon instead."] = "Před druhou vlnou: její nájezdníci a bombardéři (43–45) a pak lodě pirátů jsou pod 44,4 o level nad tebou. Doplň zkušenosti na pirátech a mušketýrech prvního tábora (41–43) na jeho jihozápadním konci, daleko od přístavu. Po těchto útesech se toulá {npc:259758}, vzácná elita levelu 49: když ho uvidíš, drž se daleko. Nebo se skupinou proběhni místo toho dungeon {area:1517}.",
	["Coyote pelts"] = "Kožešiny kojotů",
	["Down to the port."] = "Dolů do přístavu.",
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Na východ podél útesů na vzdálený konec tábora pirátů: {npc:260390} čeká u vody, {npc:260391} vedle něj.",
	["East along the road towards {area:16724}: hand {npc:258317} his murlocs as you pass {area:16725}."] = "Na východ po cestě směrem k {area:16724}: cestou kolem {area:16725} předej {npc:258317} jeho murloky.",
	["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "Na východ dolů po cestě do {area:16727}, přístavu goblinů. {npc:255897} má stánek na západním konci doků; {npc:263120}, {npc:255894} a {npc:259962} jsou v hostinci a {npc:259961} pracuje na severním molu. Zizplinkův nápoj potřebuje tři věci, které prodávají obchodníci v přístavu: návnadu od {npc:260487}, odmašťovač a starý jed od {npc:260565} a {npc:260560} u stánku {npc:255897}.",
