t.guides["forever/alliance/50-60/03-winterspring"] = {
	["Any Winterfall furbolg can drop the totem, about one kill in thirty: if the top-up did not bring one, keep killing them here until it drops, then right-click it."] = "Totem může dropnout kterýkoli furbolg Winterfall, zhruba jedno zabití z třiceti: pokud ho doplnění nepřineslo, zabíjej je tady, dokud nepadne, a pak na něj klikni pravým.",
	["Any furbolg here can drop an {item:12771} (about one in ten: it comes within the kills these quests need) and a {quest:8471} (about one in thirty): right-click whichever drops. Keep the {item:14047} the furbolgs drop for Meilosh."] = "Kterýkoli furbolg tady může dropnout {item:12771} (zhruba jeden z deseti: padne během zabití, která tyhle questy potřebují) a {quest:8471} (zhruba jeden z třiceti): klikni pravým na to, co padne. {item:14047}, který furbolgové dropují, si nech pro Meilosh.",
	["Back to the hills: only the Ice Thistle Matriarchs (56-57) and Patriarchs (57-58) carry the horns.\nCareful: take the Matriarchs at the edge of the hills, one at a time, and leave the Patriarchs: their horns drop from both."] = "Zpět do kopců: rohy nesou jen Ice Thistle Matriarchs (56–57) a Patriarchs (57–58).\nPozor: Matriarchy ber na okraji kopců po jedné a Patriarchy nech být: rohy padají z obou.",
	["Back to {npc:11053} at {area:3197}."] = "Zpět k {npc:11053} v {area:3197}.",
