t.guides["forever/alliance/50-60/04-western-plaguelands"] = {
	["After the farm's keys: the {object:177289} stands just south-west of the farmhouse, and its Cauldron Lord beside it carries the key."] = "Po klíčích farmy: {object:177289} stojí kousek jihozápadně od statku a klíč nese Cauldron Lord vedle něj.",
	["Andorhal"] = "Andorhal",
	["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Zpět do tábora {npc:7775}, kousek jihovýchodně od {npc:7765}: {item:11242} koupí tři Videre Elixirs. Nech si je: {npc:9298} jeden vezme a {npc:9299} v {area:976} se ukáže jen tomu, kdo jeden vypil.",
	["Below ground"] = "Pod zemí",
	["Boat to {area:1108}"] = "Loď do {area:1108}",
	["Bones and equipment"] = "Kosti a výstroj",
	["Careful: the Frenzied Plaguehounds are 57-58: pull them one at a time."] = "Pozor: Frenzied Plaguehounds mají 57–58: tahej je po jednom.",
	["Coming in from {zone:1451}, {area:543} is just inside the crater: {npc:10302} the goblin sits by the water."] = "Když přicházíš ze {zone:1451}, {area:543} je hned v kráteru: goblin {npc:10302} sedí u vody.",
	["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Přejdi řeku na východ k {area:2261}, kryptě na jihozápadě zóny. {object:177667} leží uvnitř: jeho klíč má {npc:12248} na dalekém severovýchodě, dělá se v dalším návodu.\nPozor: S Mercutiem přijdou asi čtyři neelitní posily. Dojdou ke hrobu, místo aby se objevily na místě.",
	["Cross the river west to {npc:1855}'s hut."] = "Přejdi řeku na západ k chýši {npc:1855}.",
	["Cross the south of the crater to {npc:9619} by the ramp."] = "Přejdi jih kráteru k {npc:9619} u rampy.",
	["Diseased Grizzlies"] = "Diseased Grizzlies",
	["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Dredge Strikers kopou v dunách severozápadně od Hold; Stonelash Scorpids a Sand Skitterers se toulají všude kolem.",
	["Eastern Pylon and the crate"] = "Východní pylon a bedna",
