t.guides["forever/alliance/50-60/06-silithus"] = {
	["Andorhal"] = "Andorhal",
	["Angerclaw bears and Felpaw wolves"] = "Medvědi Angerclaw a vlci Felpaw",
	["Araj is elite: grouping up is advised."] = "Araj je elitní: doporučuje se skupina.",
	["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber. The succubus {npc:9518} waits on the way, with Trey Lightforge's remains beside her.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "Zpět do {area:1770}: {npc:9861} a {npc:9860} hlídají {npc:9517} v nejhlubší komoře. Po cestě čeká succubus {npc:9518} s ostatky Treye Lightforge vedle sebe.\nPozor: Tři bossové bojují jako skupina. Nejdřív zabij moby kolem, ať nenatáhneš další nepřátele.",
	["Below ground"] = "Pod zemí",
	["Boat to {area:150}"] = "Loď do {area:150}",
	["Bronzebeard's Encampment"] = "Bronzebeard's Encampment",
	["Careful: Ancient Irontree Walkers, level 59 elites, stand among the {quest:5086}: work the Horrors at the camp's north-east tip (about 50.6,22.4), one at a time, and look for a walker before each pull."] = "Pozor: Mezi {quest:5086} stojí Ancient Irontree Walkers, elity levelu 59: dělej Horrors na severovýchodním cípu tábora (asi 50.6,22.4) po jednom a před každým pullem se podívej po chodci.",
	["Careful: the Twilight Keepers are level 60, a level or two over you: clear the cultists around each one first and fight the keeper at full health.\n{npc:11803} holds the cultists' camp in the far south-west."] = "Pozor: Twilight Keepers mají level 60, o level nebo dva nad tebou: nejdřív vybij kultisty kolem každého a strážce ber s plným zdravím.\n{npc:11803} drží tábor kultistů na dalekém jihozápadě.",
	["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Vyšplhej na kopec západně od {area:190} a podívej se dolů na město.\nPozor: Hlídky u brány umí odhalit hráče ve stealthu. Další hlídky jsou ve městě a poblíž chodí elita.",
	["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Vyšplhej na {area:537} uprostřed kráteru a se dvěma Thorium Bars v taškách použij {item:14644} u lávového jezera nahoře. Empty Pure Sample Jars od {npc:9616} naplň na Primal Oozes v tůních kolem hřebene.",
	["Cross the river east of {npc:1855}'s hut into {area:2627}: {npc:11140} stands by Augustus' ruined hut."] = "Přejdi řeku východně od chýše {npc:1855} do {area:2627}: {npc:11140} stojí u Augustovy zničené chýše.",
	["Flint's next task goes to {zone:1453}: you are level 60 now, skip it."] = "Flintův další úkol vede do {zone:1453}: teď už máš level 60, přeskoč ho.",
