t.guides["forever/alliance/dwarf/01-dun-morogh"] = {
	["Back east through {area:131}: {npc:1252} by Eric's campfire takes the {quest:287} report, and {npc:1269} the cogs and gears. The Shaman quest here waits for level 10: a Shaman still short of it finishes on the Ice Claw Bears (7-8), Snow Leopards and Large Crag Boars in the fields just south of {area:131}."] = "Zpět na východ přes {area:131}: {npc:1252} u Ericova táboráku vezme hlášení {quest:287} a {npc:1269} ozubená kola. Šamanský quest tady čeká na level 10: šaman, kterému ještě chybí, ho dodělá na Ice Claw Bears (7–8), Snow Leopards a Large Crag Boars na polích kousek jižně od {area:131}.",
	["Back north to {area:77} on the way to the tunnel: {npc:2756} stands by {npc:8416} at its door. Gozwin's camp is in the hills just north-west; the {npc:269075} (level 6) prowls around it."] = "Zpět na sever do {area:77} cestou k tunelu: {npc:2756} stojí u {npc:8416} u jeho dveří. Gozwinův tábor je v kopcích kousek na severozápad; {npc:269075} (level 6) kolem něj slídí.",
	["Back north to {npc:257808}'s camp above the tunnel. {npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "Zpět na sever do tábora {npc:257808} nad tunelem. {npc:257808} ti dá {item:6636}. Vyšplhej na vrchol nad jeho táborem, vypij Saptu vedle Spirit Stone a poraz {npc:5893}, pak dej jeho {item:6655} do {object:61934} na vrcholu Shrine of Eternal Flame.",
	["Back through the tunnel to {npc:257597}' cave above the farm, then west along the road to {zone:1455}."] = "Zpět tunelem do jeskyně {npc:257597} nad farmou, pak na západ po cestě do {zone:1455}.",
	["Back to the tunnel post"] = "Zpět na stanoviště u tunelu",
	["Back to the {area:136}, the wendigo cave south-west of {area:131} where {npc:271546} camps. Flintfire's shipments lie on the cave floor, {npc:278166} is missing deep inside, and {quest:98326} (level 9) keeps the {item:280426} at the back.\nCareful: Wendigos, Elder Wendigos and Wendigo Shamans (up to level 8) stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks avoids this."] = "Zpět do {area:136}, wendigí jeskyně jihozápadně od {area:131}, kde táboří {npc:271546}. Flintfirovy zásilky leží na podlaze jeskyně, {npc:278166} se ztratil hluboko uvnitř a {quest:98326} (level 9) má {item:280426} vzadu.\nPozor: Wendigos, Elder Wendigos a Wendigo Shamans (až level 8) stojí v jeskyni blízko sebe, takže boje snadno natáhnou víc najednou; když je vytáhneš ven po jednom útoky z dálky, vyhneš se tomu.",
	["Back to the {area:925}"] = "Zpět do {area:925}",
	["Back to {area:77}"] = "Zpět do {area:77}",
	["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Zpět k {npc:257446} do {area:77}. Dá ti {item:6635}: vezmi stezku označenou sutí, která stoupá na západ z jihu údolí ke Spirit Stone na hřebeni, vypij vedle něj Saptu a promluv s {npc:5891}, pak přines jeho {item:6656} zpět Teovi.",
	["Back to {npc:257597}"] = "Zpět do {npc:257597}",
	["Below ground"] = "Pod zemí",
	["Brewnall: kill these as you meet them"] = "Brewnall: zabíjej je, jak na ně narazíš",
	["Catch {npc:13016}"] = "Chyť {npc:13016}",
	["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Crag Boars a Young Black Bears se toulají po polích od Rumbleshotova tábora na severovýchod do {area:131} a ke skladišti: zabíjej je cestou zpátky.",
	["Druid trainer"] = "Trenér druidů",
	["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Každý quest Grifa Wildhearta ti dá {item:15908}: použij ji na zvíře, které jmenuje, pak mu hůl přines zpět ke kovárně v {area:131}. Large Crag Boars, Snow Leopards i Ice Claw Bears se toulají po polích kousek jižně a východně od {area:131}.",
	["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats. Shamans: the Tunnel Rat Geomancers (level 12-13) here carry the {item:5026}.\nCareful: the Tunnel Rat Geomancers (12-13) cast from range in the narrow tunnels: pull them one at a time."] = "Na východ podél kopců k dolu na severním konci jezera: bedny Miners' League jsou v jeho tunelech mezi dalšími Tunnel Rats. Šamani: Tunnel Rat Geomancers (level 12–13) tady nesou {item:5026}.\nPozor: Tunnel Rat Geomancers (12–13) sesílají v úzkých tunelech z dálky: tahej je po jednom.",
	["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "Na východ zpět do {object:171524}: {area:2257} odjíždí z jeho východního konce. Jeď jí do {zone:1453}.",
	["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "Na východ od {object:32372} do {object:171524}: {object:660964} leží u jeho poštovní schránky. Odsud jde návod jednou kolem města: na sever do {object:32383}, na západ do {object:32362}, na jih přes Commons do {object:171709}, na východ přes {object:32359} a zpět do {object:171524} na tramvaj.",
	["East through the South Gate tunnel into {zone:1432}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "Na východ tunelem South Gate do {zone:1432}. {npc:1089} a {npc:1092} stojí na trpasličím stanovišti hned za ním.",
	["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "Na východ do {object:32359}: trenéři warriorů a {npc:11865} v {object:32390}, trenéři lovců vedle.",
	["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen táboří na hřebeni, ze kterého je ze západu vidět na {area:134}. Promluv si s ním kvůli jeho dalekozraku.",
	["Feather Charms, from the Frostmane Novices"] = "Feather Charms, od Frostmane Novices",
	["Firewood"] = "Dříví",
	["The {area:2257}"] = "{area:2257}",
	["The {item:6652}"] = "{item:6652}",
	["{area:132}: kill these as you meet them"] = "{area:132}: zabíjej je, jak na ně narazíš",
	["{area:138}: kill these as you meet them"] = "{area:138}: zabíjej je, jak na ně narazíš",
	["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
	["{item:2004}; below ground"] = "{item:2004}; pod zemí",
	["{npc:1123}, below ground"] = "{npc:1123}, pod zemí",
	["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: ochoč ho pomocí {item:15908}",
	["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: ochoč ho pomocí {item:15908}",
	["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: ochoč ho pomocí {item:15908}",
