	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Zpět k {npc:6122}. Použij {item:6928} ve vyvolávacím kruhu ve sklepě {object:2164} a poraz voidwalkera, kterého přivolá.",
