t.guides["forever/alliance/nightelf/01-teldrassil"] = {
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/sit u táboráku {npc:265811}, dokud nedostaneš {spell:1229451}",
	["Back at {area:256}"] = "Zpět v {area:256}",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Zpět z městské brány a na východ po cestě: {quest:1683} stojí jižně od ní, u {area:736}. Jeho roh přines zpět {quest:1684}.",
	["Back to the moonwell."] = "Zpět k moonwell.",
	["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Zpět na vrchol {area:256}. {object:654846} leží vedle něj.",
	["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "Zpět nahoru k {npc:3567} s hotovými webwoody a mechem {npc:272116}.",
	["Befouled Webwoods"] = "Befouled Webwoods",
	["Below ground"] = "Pod zemí",
	["Bloodfeather harpies"] = "Harpyje Bloodfeather",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn {area:493}'s flight path from {npc:10897}, south of the lake, for later trips. Then {npc:11800} in {area:2361} flies Druids straight to {area:702} from her gossip: hers is no flight path to learn. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} je v {area:2361}; {quest:5929} sedí v lesích na severozápadě. Na pozdější cesty se nauč letovou trasu {area:493} od {npc:10897} jižně od jezera. Pak tě {npc:11800} v {area:2361} z rozhovoru přepraví rovnou do {area:702}: její let není letová trasa k naučení. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Crawler Legs: the Tide Crawlers"] = "Crawler Legs: Tide Crawlers",
	["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Každý Dazalarův quest ti dá {item:15908}: použij ji na zvíře, které jmenuje, pak mu hůl přines zpět do {area:186}. Webwood Lurkers lezou kolem vesnice, Nightsaber Stalkers a Strigid Screechers se toulají v lesích jižně od ní.",
	["East along the road to {area:186}."] = "Na východ po cestě do {area:186}.",
	["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Eskortuj {npc:275744} ven z mohyly; hlášení vezme {npc:2081} v {area:186}.",
	["Fandral in {zone:1457} takes it"] = "Fandral v {zone:1457} ho vezme",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Fel Cones leží pod stromy všude kolem {area:186} a {npc:2150}: posbírej je cestou na východ a předej je {npc:2150} na cestě k {npc:7234}.",
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Jen pro rybáře: {npc:10216} stojí na molu. Jeho {item:12238} se chytá přímo z mola.",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Leť zpátky do {area:702} od {npc:3841}, předej {item:16263} {npc:10118} na molu, pak leť zpátky do {area:442}.",
