t.guides["forever/alliance/nightelf/02-darkshore"] = {
	["Back north to {area:447}: the flame burns in the south of the ruins."] = "Zpět na sever do {area:447}: plamen hoří na jihu ruin.",
	["Back north-east into the mountains to the crystal."] = "Zpět na severovýchod do hor ke krystalu.",
	["Bears and the Blackwood camp"] = "Medvědi a tábor Blackwood",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}.\nCareful: the Windtalkers (13-14) cast from range and the furbolgs stand in pairs: pull them one at a time."] = "Blackwood Pathfinders a Windtalkers drží tábor jihovýchodně od {area:442}.\nPozor: Windtalkers (13–14) sesílají z dálky a furbolgové stojí ve dvojicích: tahej je po jednom.",
	["Blackwood furbolgs"] = "Furbolgové Blackwood",
	["Boat to {area:17203}"] = "Loď do {area:17203}",
	["Class trainer"] = "Trenér povolání",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Vyšplhej do východních hor východně od {area:447}; {object:175524} sedí na římse.",
	["Crawler Legs: the Tide Crawlers"] = "Crawler Legs: Tide Crawlers",
	["Druid trainer"] = "Trenér druidů",
	["Fill the tube at the moonwell in the village"] = "Naplň zkumavku u měsíční studny ve vesnici",
