	["Druid trainer"] = "Trenér druidů",
	["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Probojuj se na sever k {area:16629}. Přístup drží Guardians, Spiritcallers a Blademasters; {npc:253576} čeká u dveří svatyně, {npc:253590} uvnitř vnitřní svatyně.",
	["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Fillionův tábor je severozápadně od něj a Shriekling Matriarchs hnízdí kousek západně od tábora.",
