t.guides["forever/class/druid/aquatic-form"] = {
	["At the {area:2362}"] = "U {area:2362}",
	["Back through {area:1637} to the zeppelin towers outside its main gate: the zeppelin to the {zone:1458} lands in {zone:1420}, and {zone:1421} is south of the {zone:1458}."] = "Zpět přes {area:1637} k věžím zeppelinů před hlavní branou: zeppelin do {zone:1458} přistává v {zone:1420} a {zone:1421} je jižně od {zone:1458}.",
	["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:28} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Sem se dostaneš přes {spell:18960}: {npc:11802} stojí nahoře v budově vedle místa přistání. {quest:28} běží na třicetiminutovém časovači: jakmile ho přijmeš, žádný teleport ani Hearthstone, dokud ho nemá {npc:11799}. Šest Bauble Containers (vázy) leží v úzkých prohlubních hluboko na dně {area:656} pod {area:2361}, často u bublajících trhlin ({object:177524} uprostřed jezera ti doplní dech); každá se vrátí tři minuty po otevření a berou je i jiní druidi. Než se vynoříš, zkontroluj, že máš {item:15877} v taškách: pět minut po lootnutí zmizí. Doplav s ní rovnou k {area:2362} na severozápadním břehu, použij ji v areálu svatyně a promluv s {npc:11799} u stromu.",
	["Cast {spell:18960} to get here: {npc:11802} stands upstairs in the building beside where you land. {quest:29} runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until {npc:11799} has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Sem se dostaneš přes {spell:18960}: {npc:11802} stojí nahoře v budově vedle místa přistání. {quest:29} běží na třicetiminutovém časovači: jakmile ho přijmeš, žádný teleport ani Hearthstone, dokud ho nemá {npc:11799}. Šest Bauble Containers (vázy) leží v úzkých prohlubních hluboko na dně {area:656} pod {area:2361}, často u bublajících trhlin ({object:177524} uprostřed jezera ti doplní dech); každá se vrátí tři minuty po otevření a berou je i jiní druidi. Než se vynoříš, zkontroluj, že máš {item:15877} v taškách: pět minut po lootnutí zmizí. Doplav s ní rovnou k {area:2362} na severozápadním břehu, použij ji v areálu svatyně a promluv s {npc:11799} u stromu.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "Sešli {spell:18960}. S oběma polovinami v taškách si stoupni k {area:2362} na severozápadním břehu a spoj je pomocí {item:15883}, pak znovu sešli {spell:18960} (funguje i uvnitř {zone:1450}) a přistaneš u {npc:11802}. Stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší. Potom {npc:11800} uprostřed {area:2361} přepraví druidy rovnou do {area:702}.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "Sešli {spell:18960}. S oběma polovinami v taškách si stoupni k {area:2362} na severozápadním břehu a spoj je pomocí {item:15883}, pak znovu sešli {spell:18960} (funguje i uvnitř {zone:1450}) a přistaneš u {npc:11802}. Stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší. {npc:11798} vozí druidy do {area:1638}.",
	["{item:15882}, from the {object:177790}"] = "{item:15882}, od {object:177790}",
	["{item:15882}, from the {object:177844}"] = "{item:15882}, od {object:177844}",
	["{item:15883}, from the {object:177792}"] = "{item:15883}, od {object:177792}",
	["{item:15883}, from the {object:177794}"] = "{item:15883}, od {object:177794}",
}
t.guides["forever/class/druid/bear-form"] = {
	["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Na 10 tě zastihne volání druidů: {npc:3064} v {area:222} nebo {npc:6746} v {zone:1456} (dopis {npc:6929} v {zone:1454} funguje taky). Kterýkoli z nich tě pošle k {npc:3033} na {area:1639} v {zone:1456}.",
	["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Na 10 tě zastihne volání druidů: {npc:3602} v {area:186}, Denatharion v {zone:1457} nebo Theridran v {zone:1453}. Kterýkoli z nich tě pošle k {npc:4217} v Cenarion Enclave v Darnassu.",
	["Back to {npc:255853} by the falls."] = "Zpět k {npc:255853} u vodopádů.",
	["Back to {npc:3033} on {area:1639}."] = "Zpět k {npc:3033} na {area:1639}.",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here ({npc:12740} for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}, v {area:2361}. Když už jsi tady, nauč se letovou trasu {area:493} ({npc:12740} pro Hordu, jihozápadně od jezera; {npc:10897} pro Alianci, jižně od něj).",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}, za obchodníkem se zbrojí. {quest:5929} sedí v lesích na severozápadě. Promluv s ním a projdi všechna jeho slova (co představuje, síla těla, síla srdce, pak požádej o požehnání): rozhovor je cíl, žádný boj. Splývá se zemí, nemá značku questu a slabě modrošedě září u skupiny tří stromů: z {area:2361} jdi na západ podél úpatí severních hor, mezerou mezi stromy a kopci. Pokud tam {npc:11802} po návratu není, vyjdi ven a znovu sešli {spell:18960}. Na později se nauč letovou trasu {area:493} ({npc:10897} jižně od jezera), pak leť s {npc:11800} ze středu {area:2361}: druidy vozí rovnou do {area:702}, letová trasa není potřeba. Portálem nahoru do {zone:1457}.",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path ({npc:12740}, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Sešli {spell:18960}: přistaneš vedle budovy, kde nahoře stojí {npc:11802}. {quest:5930} sedí v lesích na severozápadě. Promluv s ním a projdi všechna jeho slova (co představuje, síla těla, síla srdce, pak požádej o požehnání): rozhovor je cíl, žádný boj. Splývá se zemí, nemá značku questu a slabě modrošedě září u skupiny tří stromů: z {area:2361} jdi na západ podél úpatí severních hor, mezerou mezi stromy a kopci. Pokud tam {npc:11802} po návratu není, vyjdi ven a znovu sešli {spell:18960}. Nauč se letovou trasu {quest:5922} ({npc:12740}, jihozápadně od jezera); {npc:11798} v {area:2361} vozí druidy do {area:1638}.",
	["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Leť zpátky do {area:702} a vyjeď portálem nahoru k {npc:4217}.",
	["The {object:177525}"] = "{object:177525}",
	["{npc:255853} and {npc:258443}"] = "{npc:255853} a {npc:258443}",
	["{spell:5487} and {area:493}"] = "{spell:5487} a {area:493}",
}
t.guides["forever/class/druid/bloodpetal-poison"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. {area:1477} stands in the middle of the {area:74} in the {zone:1435}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. {npc:8580} (level 50 elite, {spell:12887} and {spell:6524}) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The {item:22444} always drops."] = "Dungeon pro pět hráčů: potřebuje skupinu pěti, asi level 50–55. Horda: leť do {area:75}; Aliance: leť do {area:1438} v {zone:1419} a jeď na sever. {area:1477} stojí uprostřed {area:74} v {zone:1435}: vyjdi po schodech na jižní straně ruiny, skoč do zatopené síně, proplav dolů a sleduj schody a chodby dolů k portálu. {npc:8580} (level 50 elite, {spell:12887} a {spell:6524}) se objeví, jen když klikneš na šest hadích soch v kruhu balkonu nad oltářní jámou v pořadí: jih, sever, jihozápad, jihovýchod, severozápad, severovýchod (každá zezelená, když je to správně; špatné pořadí selže). Nejdřív vybij trash u každé sochy a v jámě pod nimi; skok dolů do vody je rychlá cesta dolů, ale odhození u okraje může zabít. {item:22444} padá vždy.",
	["Any {npc:6498} counts, the Ironhide and Tyrant Devilsaurs too. They are elite (level 54-55), hit with {spell:14099} and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or {spell:339} it from range, stab it with the {item:22432} (the barb does not break {spell:2637}), then leave. The credit counts the moment the barb lands, even if you die after. The arrow points at the plain Devilsaurs of the west and north; an {npc:6499} roams the middle of the crater's south, nearer {npc:9619}."] = "Počítá se kterýkoli {npc:6498}, i Ironhide a Tyrant Devilsaurs. Jsou elitní (level 54–55), bijí {spell:14099} a předběhnou travel form. Doporučuje se skupina, ale druid to zvládne sám: uspi ho Hibernate nebo {spell:339} z dálky, bodni ho {item:22432} (osten neruší {spell:2637}) a odejdi. Zásluha se počítá ve chvíli, kdy osten zasáhne, i když potom zemřeš. Šipka ukazuje na obyčejné Devilsaury na západě a severu; {npc:6499} se toulá středem jihu kráteru, blíž k {npc:9619}.",
	["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "Zpět k {npc:9619} do jihovýchodního rohu {zone:1449}.",
	["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "Sešli {spell:18960}. {npc:12042} stojí v {area:2361}; stejný quest nabízí trenér tvého povolání ({npc:3033}, {npc:4217} nebo Theridran v {zone:1453}).",
	["Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the {area:540}, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' {spell:8137} makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around {area:541} and the western half): open them, about every other one gives a {item:22434}, back in three to five minutes."] = "Osm od každého. Gorishi Wasps a Stingers (level 51–52) v {area:540} a kolem, úlu na jihozápadě kráteru, dropují žihadlo zhruba jedno zabití ze sedmi; vosy sdílejí místa spawnu s ostatním hmyzem, tak zabíjej, co stojí kolem, ať udělají místo dalším vosám (obnova pět minut). {spell:8137} hmyzu ti na 30 minut zvýší přijaté fyzické poškození; Workers při zranění volají o pomoc. Bloodpetal Sprouts rostou po celém kráteru (kolem {area:541} a v západní polovině): otevírej je, zhruba každý druhý dá {item:22434}, obnova za tři až pět minut.",
	["Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever."] = "Zkušenosti v Un'Goro na 50 a dva léčivé lektvary; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["The {area:1417}"] = "{area:1417}",
}
t.guides["forever/class/druid/cat-form"] = {
	["Back to {npc:11802}"] = "Zpět do {npc:11802}",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a přistaneš u {npc:11802} v {area:2361} (quest pro Skyborne na Zephras Isle nikdo nebere), pak leť s {npc:11798} do {area:1638}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a přistaneš u {npc:11802} v {area:2361} (quest pro Skyborne na Zephras Isle nikdo nebere), pak leť s {npc:11800} do {area:702}: stojí uprostřed {area:2361} a druidy tam vozí, letová trasa není potřeba. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. No {area:493} flight path yet? Learn it from {npc:10897}, south of the lake: the flight master in {area:2361} flies only Druids, from her gossip, and has none to learn."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší. Ještě nemáš letovou trasu {area:493}? Nauč se ji od {npc:10897} jižně od jezera: letová mistryně v {area:2361} vozí jen druidy z rozhovoru a žádnou trasu k naučení nemá.",
	["The {area:2363}"] = "{area:2363}",
}
t.guides["forever/class/druid/cure-poison"] = {
	["Back in {area:442}, at the north end of the village."] = "Zpět v {area:442}, na severním konci vesnice.",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a zastav se u {npc:11802}, pak leť s {npc:11798} do {area:1638}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960} a zastav se u {npc:11802}, pak leť s {npc:11800} ze středu {area:2361} (druidy vozí do {area:702}, letová trasa není potřeba) a portálem nahoru do {zone:1457}. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "Sešli {spell:18960}: {npc:11802} stojí nahoře v budově vedle tebe. Dá ti {item:15842}. {npc:11798} vozí druidy do {area:1638}; odtud leť dál do Crossroads.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "Sešli {spell:18960}: {npc:11802} stojí nahoře v budově vedle tebe. Dá ti {item:15844}. Pak leť do {area:442} (pokud ji nemáš, nejdřív se u Sindrayl nauč letovou trasu {zone:1450}).",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the Crossroads. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Každý {npc:3234} (level 14–15) dropne roh, ale je jich málo a toulají se: hledej na dalekém severu u {area:382} a oáz, hlavně {area:388} jihovýchodně od Crossroads. Útočí náporem z dálky a dupou. Bylinkáři najdou {item:2449} po celém severním {zone:1413}.",
	["{item:15851} and {item:2449}"] = "{item:15851} a {item:2449}",
}
