t.guides["forever/class/hunter/taming-the-beast-alliance"] = {
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. {quest:6074} from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Na 10 jdi za {npc:1231}, trenérem lovců u kovárny v {area:131}. Sem vede i {quest:6074} od {npc:5116} v {zone:1455}, {npc:11807} severozápadně od {area:131} nebo {npc:5515} v {zone:1453}, za trochu zkušeností; je to jen rozcestník. Jsi na 10 radši v Elwynnu? Řetěz {npc:251507} v {area:87} učí totéž.",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "Na 10 jdi za {npc:251507}, trenérkou lovců, která stojí s ostatními trenéry u Lion's Pride Inn v {area:87}; {npc:258930}, trenér petů, je vedle ní. Skyborne: tohle je pro toho, kdo opustil {zone:2521} bez ochočení; učí totéž.",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. {quest:6071} from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Na 10 jdi za {npc:3601}, trenérem lovců v {area:186}. Sem vede i {quest:6071} od {npc:3596} v {area:256}, {npc:4146} v {zone:1457}, {npc:5515} v {zone:1453}, {npc:5116} v {zone:1455} nebo {npc:1231} v {area:131}, za trochu zkušeností; je to jen rozcestník. Jsi na 10 radši v Elwynnu? Řetěz {npc:251507} v {area:87} učí totéž.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Na 10 tě {npc:254084}, trenér lovců na {zone:2521}, může poslat dál do {area:16638} s {quest:94007}. Je to jen rozcestník: přeskoč ho, pokud už jsi v {area:16638}.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "Nejdřív propusť kance (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Gray Forest Wolves (level 7–8) běhají v lesích východně od {area:87}, východně od {area:18}.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "Nejdřív propusť kance (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Snow Leopards (level 7–8) slídí po svazích jihovýchodně od {area:131}, další severozápadně a západně od něj; menší Juvenile Snow Leopards se nepočítají.",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "Propusť kočku. Strigid Screechers (level 7–8), sovy, sedí v lesích jižně, jihozápadně a západně od {area:186}.",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Nejdřív propusť crawlera (pravé tlačítko na portrét peta, {spell:2641}). Ornery Galestriders se pasou v {area:16626}, na polích kousek pěšky západně a jihozápadně od {area:16638}.",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Propusť galestridera. Vuldren Alphas loví ve stejném {area:16626}, kousek dál na jih.",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "Propusť leoparda. Ice Claw Bears (level 7–8) se toulají po kopcích kolem {area:131}, hodně jihovýchodně od něj a další severozápadně směrem k {area:77}; jejich {spell:3130} tvrdě bije, tak začni s plným zdravím.",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "Nejdřív propusť pavouka (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet se může obrátit proti tobě. Nightsaber Stalkers (level 7–8) leží na svahu jižně od {area:259}, jižně od {area:186}; obyčejní Nightsabers u vesnice se nepočítají.",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "Propusť vlka. Young Forest Bears (level 8–9) se toulají v lesích kousek jižně od {area:87}, další jihozápadně a jihovýchodně od města.",
	["Tame {npc:1922}"] = "Ochoč {npc:1922}",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["Tame {npc:524}"] = "Ochoč {npc:524}",
	["Tame {npc:822}"] = "Ochoč {npc:822}",
	["{npc:10090} in {zone:1455}"] = "{npc:10090} v {zone:1455}",
	["{npc:1231} in {area:131}"] = "{npc:1231} v {area:131}",
	["{npc:1231}: the first {item:15908}"] = "{npc:1231}: první {item:15908}",
	["{npc:251507} in {area:87}"] = "{npc:251507} v {area:87}",
	["{npc:251507}: the first {item:15908}"] = "{npc:251507}: první {item:15908}",
	["{npc:252389} in {area:16638}"] = "{npc:252389} v {area:16638}",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}: první {item:15908}",
	["{npc:3601} in {area:186}"] = "{npc:3601} v {area:186}",
	["{npc:3601}: the first {item:15908}"] = "{npc:3601}: první {item:15908}",
	["{npc:4146} in {zone:1457}"] = "{npc:4146} v {zone:1457}",
	["{quest:6063} (Alliance)"] = "{quest:6063} (Aliance)",
}
t.guides["forever/class/hunter/taming-the-beast-horde"] = {
	["Adult Plainstriders (level 6-7) walk the plains south-west and north-west of {area:222}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw."] = "Dospělí Plainstriders (level 6–7) chodí po pláních jihozápadně a severozápadně od {area:222}. Jak hůl funguje: zaměř živé zvíře, použij {item:15908} a po celou dobu kanálu stůj na místě, zatímco tě bije; pohyb, bránění nebo pomoc kohokoli dalšího ho přeruší a stojí jeden z mála nábojů hole (bez nábojů: hůl znič, quest zruš a vezmi znovu). Plainstrider utíká na 25 % zdraví, takže ho předtím nezraňuj. Každou hůl si nech: vrací se Yawovi.",
	["At 10 go to {npc:3065}, who stands at the north edge of {area:222}. {quest:6065} from {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} or {npc:3171} in {area:362} also leads here, for a little experience; it is only a pointer."] = "Na 10 jdi za {npc:3065}, který stojí na severním okraji {area:222}. Sem vede i {quest:6065} od {npc:3038} v {zone:1456}, {npc:3407} v {zone:1454} nebo {npc:3171} v {area:362}, za trochu zkušeností; je to jen rozcestník.",
	["At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you {quest:6068}, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it."] = "Na 10 jdi za {npc:3171}, trenérem lovců v kasárnách v {area:362}. Pokud ti {npc:3407} v {zone:1454}, {npc:11814} v {area:367} nebo {npc:3038} v {zone:1456} dá {quest:6068}, vezmi ho a odevzdej {npc:3171} za trochu zkušeností; je to jen rozcestník a první hůl si vezmeš i bez něj.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Na 10 tě {npc:254084}, trenér lovců na {zone:2521}, může poslat dál do {area:16638} s {quest:94007}. Je to jen rozcestník: přeskoč ho, pokud už jsi v {area:16638}.",
	["Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}."] = "Dire Mottled Boars (level 6–7) se toulají kousek severně a západně od {area:362}. Jak hůl funguje: zaměř živé zvíře, použij {item:15908} z jeho dosahu a po celou dobu kanálu stůj na místě, zatímco tě zvíře bije. Pohyb, bránění, heal od někoho jiného nebo útok kohokoli dalšího na zvíře ho přeruší a stojí jeden z mála nábojů hole; když dojdou, hůl znič, quest zruš a vezmi znovu od {npc:3171}. Kanci útočí z 20 yardů, tak začni holí, ne {spell:75}. Ochočený kanec se stane tvým cvičným petem. Každou hůl si nech: vrací se {npc:3171}.",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Nejdřív propusť crawlera (pravé tlačítko na portrét peta, {spell:2641}). Ornery Galestriders se pasou v {area:16626}, na polích kousek pěšky západně a jihozápadně od {area:16638}.",
	["Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of {area:362}, some just south of the road west out of town; {spell:1494} shows them. Their hits can break the channel: start at full health and keep still."] = "Propusť crawlera. Armored Scorpids (level 7–8) lezou po suchých pláních západně a jihozápadně od {area:362}, někteří kousek jižně od cesty na západ z města; ukáže je {spell:1494}. Jejich údery můžou kanál přerušit: začni s plným zdravím a nehýbej se.",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Propusť galestridera. Vuldren Alphas loví ve stejném {area:16626}, kousek dál na jih.",
	["Dismiss the plainstrider first (right-click the pet portrait, {spell:2641}): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of {area:222}."] = "Nejdřív propusť plainstridera (pravé tlačítko na portrét peta, {spell:2641}): propuštěný cvičný pet může zaútočit. Prairie Stalkers (level 7–8) se toulají v trávě severně od {area:222}.",
	["Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A {npc:2970}'s knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it."] = "Propusť stalkera. Swoops (level 7–9) kloužou nad pláněmi severozápadně a severovýchodně od Bloodhoof; Taloned Swoops se nepočítají. Sražení od {npc:2970} kanál přeruší, ale zasáhne jen jednou za kanál: začni s holí hned poté, co ho použije.",
	["First dismiss the boar (right-click your pet's portrait, {spell:2641}): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around {area:367} and the {area:368}; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it."] = "Nejdřív propusť kance (pravým tlačítkem na portrét peta, {spell:2641}): propuštěný cvičný pet se na tebe může obrátit. Surf Crawlers (level 7–8) chodí po plážích kolem {area:367} a {area:368}; malí Pygmy Surf Crawlers se nepočítají. Crawler na 15 % zdraví utíká pro pomoc, tak mu neubližuj.",
	["Tame {npc:250874}"] = "Ochoč {npc:250874}",
	["Tame {npc:251707}"] = "Ochoč {npc:251707}",
	["Tame {npc:254588}"] = "Ochoč {npc:254588}",
	["{npc:252389} in {area:16638}"] = "{npc:252389} v {area:16638}",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}: první {item:15908}",
	["{npc:3039} in {zone:1456}"] = "{npc:3039} v {zone:1456}",
	["{npc:3065}: the first {item:15908}"] = "{npc:3065}: první {item:15908}",
	["{npc:3171} in {area:362}"] = "{npc:3171} v {area:362}",
	["{npc:3171}: the first {item:15908}"] = "{npc:3171}: první {item:15908}",
	["{npc:3352} in {zone:1454}"] = "{npc:3352} v {zone:1454}",
	["{quest:6061} (Horde)"] = "{quest:6061} (Horda)",
}
t.guides["forever/class/hunter/the-hunters-charm"] = {
	["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "Na 50 ho nabízí kterýkoli trenér lovců Aliance: {npc:5516} v {object:28027} v {zone:1453}, {npc:5116} v {object:32390} v {zone:1455} nebo Dorion v Cenarion Enclave v {zone:1457}.",
	["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Na 50 ho nabízí kterýkoli trenér lovců Hordy: {npc:3352} v {object:172958} v {zone:1454} nebo {npc:3039} na {area:1641} v {zone:1456}.",
	["Experience"] = "Zkušenosti",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Zkušenosti na 50 přes {zone:1447} a {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["{quest:8151} (Alliance)"] = "{quest:8151} (Aliance)",
	["{quest:8151} (Horde)"] = "{quest:8151} (Horda)",
}
