t.guides["forever/class/mage/celestial-orb"] = {
	["An off-hand orb or a staff for the late 30s, your pick."] = "Koule do druhé ruky nebo hůl pro pozdní třicítky, podle tvé volby.",
	["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. The reward window shows the {item:9527} and the {item:9531}."] = "Na 40 mají trenéři mágů, kteří tě posílají k {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}), i {quest:2861}, quest pro jakékoli povolání. {npc:6546} pak chce {quest:2846} od {npc:7795}, elitní nagy levelu 46 v {area:978}, trollím dungeonu na severozápadě {zone:1446}: skupina pěti, level 44–54. Okno odměny ukazuje {item:9527} a {item:9531}.",
	["Back at {npc:6546}'s. Hand in the orb now; {quest:1955} waits for level 40. Kill the critters around the cottage first: they join the fight. Accepting {quest:1955} starts a 3 minute timer, and {npc:6546} calls the {npc:6549} out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again."] = "Zpět u {npc:6546}. Kouli odevzdej teď; {quest:1955} čeká na level 40. Nejdřív zabij havěť kolem chalupy: přidá se do boje. Přijetí {quest:1955} spustí třiminutový časovač a {npc:6546} vyvolá v zahradě {npc:6549}: elitu levelu 40, která odolává mnoha kouzlům, rootům i zpomalení. Doporučuje se skupina: mág na 40 může potřebovat pomoc nebo lektvary, kolem 45 to zvládne sám. Můžeš ho natáhnout z dálky z mola. Časovač běží i po jeho smrti, tak quest odevzdej hned. Když čas vyprší, quest zruš a vezmi znovu; démona vyvolá znovu.",
	["Back to {npc:6546}. Accepting {quest:1957} opens a rift beside her cottage and starts a 10 minute timer: twelve {quest:1957} (level 40, Shock and {spell:403}) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out."] = "Zpět k {npc:6546}. Přijetí {quest:1957} otevře trhlinu vedle její chalupy a spustí desetiminutový časovač: dvanáct {quest:1957} (level 40, Shock a {spell:403}) vyjde zhruba po čtyřech. Útok na jednoho nenatáhne ostatní. Stání na okraji pole přitáhne všechny; strom jihozápadně od něj je mimo jejich dosah, ale v dosahu tvých kouzel. Zabij dvanáct a odevzdej, než časovač vyprší.",
	["{quest:2846} in {area:978}"] = "{quest:2846} v {area:978}",
}
t.guides["forever/class/mage/destroy-morphaz"] = {
	["Back to {npc:8395} and up to the tower."] = "Zpět k {npc:8395} a nahoru do věže.",
	["Back to {npc:8395}, who teleports you up to the tower."] = "Zpět k {npc:8395}, který tě teleportuje nahoru do věže.",
	["Back to {zone:1447}, {npc:8395} and the tower. Look at the reward window before you hand in: Classic offered the {item:20037}, the {item:20036} or the {item:20035}, and Forever's notes say the choice may be gone."] = "Zpět do {zone:1447}, k {npc:8395} a do věže. Před odevzdáním se podívej do okna odměny: Classic nabízel {item:20037}, {item:20036} nebo {item:20035} a poznámky Foreveru říkají, že volba možná zmizela.",
	["Experience"] = "Zkušenosti",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "Zkušenosti na 50 přes {zone:1447} a {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["The {item:20085}"] = "{item:20085}",
	["{npc:8379} again"] = "{npc:8379} znovu",
}
t.guides["forever/class/mage/ju-ju-heaps"] = {
	["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "Hůl nebo koule do druhé ruky na 10: Orkové a Trollové na {area:368}, Nemrtví na farmě v Tirisfalu.",
	["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "Na 10 tě {npc:2128}, trenér mágů v {area:159} nahoře v {area:2119}, pošle k {npc:4568} v {zone:1458}. Jeho přijetí uzavře {quest:1884}; pokud máš v deníku {quest:1883} (z {zone:1454} nebo {zone:1456}), nejdřív ho zruš, jinak ti {npc:2128} tenhle nedá. (Troll, který tenhle vzal v {area:159}, jde kroky Balnira; Nemrtvý, který vzal {quest:1884} v Sen'jinu, kroky {area:368}.)",
	["Back to Anastasia"] = "Zpět k Anastasii",
	["Back to Un'thuwa"] = "Zpět k Un'thuwovi",
	["The {quest:1884}"] = "{quest:1884}",
}
t.guides["forever/class/mage/mages-wand"] = {
	["\"Plucky\" Johnson"] = "\"Plucky\" Johnson",
	["A wand of your school for the 30s: frost, arcane or fire."] = "Wand tvé školy pro třicítky: frost, arcane nebo fire.",
	["Back to {npc:6546}. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire)."] = "Zpět k {npc:6546}. S oběma odevzdanými questy začne rituál: pár sekund počkej, pak s ní znovu promluv a vyber si wand: Icefury (frost), Nether Force (arcane) nebo Ragefire (fire).",
}
t.guides["forever/class/mage/manaweave-robe"] = {
	["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "Roucho na 15 pro mágy Aliance, z {zone:1453} a {zone:1432}.",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "{item:2589} dropuje kterýkoli humanoid a Tunnel Rats v {area:149} ho dropují, zatímco sbíráš drahokamy; prodává ho aukce v {object:2096}. Odevzdáváš deset.",
	["Back to {npc:5497}"] = "Zpět do {npc:5497}",
	["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "Zpět do {zone:1453} tramvají. {npc:1309} pracuje v {object:23296} v {object:2101}.",
	["The {area:149}"] = "{area:149}",
}
t.guides["forever/class/mage/nether-lace-garment"] = {
	["A robe or a tunic for Horde mages in their late 20s."] = "Roucho nebo tunika pro mágy Hordy v jejich pozdních dvacítkách.",
	["Back to {npc:5885}"] = "Zpět do {npc:5885}",
	["The {object:174797}"] = "{object:174797}",
	["The {quest:1945}"] = "{quest:1945}",
