t.guides["forever/class/mage/polymorph-pig"] = {
	["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Nový vzhled pro {spell:118}: cíl promění v prase místo ovce.",
	["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "Zpět do {area:1221}, plného nag Spitelash. Sešli na nagu svůj ovčí {spell:118} (želví nic nedělá) a pár sekund počkej: rozdělí se na dva až šest Polymorph Clones s asi 150 zdraví, které rychle utíkají. Stůj vedle ovce a zasáhni je ve chvíli, kdy se objeví, {spell:122} a {spell:1449}. Klonů je potřeba padesát, takže to chvíli trvá; ne v raidové skupině.",
	["Back to {npc:8395} and up to the tower."] = "Zpět k {npc:8395} a nahoru do věže.",
	["Back to {npc:8395} and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags."] = "Zpět k {npc:8395} a nahoru do věže. Xylem s dalším questem vrátí ulitu: nech si ji v taškách.",
}
t.guides["forever/class/mage/spellfire-robes"] = {
	["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "Roucho na 15 pro mágy Hordy, z {zone:1458} a {zone:1421}.",
	["Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed."] = "Algernonův alchymistický obchod je v Apothecariu. Stoupni si na schody nebo na most před obchodem a přečti {item:7308}: objeví se až čtyři neviditelní Rift Spawns (level 16–17) a hned zaútočí a městské stráže nepomůžou. Zasáhni jednoho kouzlem na jeden cíl a ustup přes most: ostatní to vzdají a zmizí, ten zasažený jde za tebou. Ubij ho na polovině mostu u obchodu (za polovinou na něj truhlička nefunguje), dokud nepřestane bojovat a nesedí omráčený pod spirálou, použij na něj {item:7247} a klikni na {item:7292}, až se objeví na podlaze (moc brzké kliknutí spálí náboj). Potřebuješ tři.",
	["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then {npc:4576} offers {quest:1962}: take it and hand it straight back to him for the robe."] = "Zpět do {zone:1458}. Krejčovství v {object:36082} drží {npc:4576}, {npc:11048} a {npc:11049}. Předej drahokamy a látku {npc:4576} a nech ty tři chvíli mluvit; pak {npc:4576} nabídne {quest:1962}: vezmi ho a hned mu ho odevzdej za roucho.",
	["Back to {npc:4568}"] = "Zpět do {npc:4568}",
}
t.guides["forever/class/mage/staff-or-orb-alliance"] = {
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "Hůl nebo koule do druhé ruky na 10 od trenéra mágů tvého domovského města; Skyborne navíc dostanou wand.",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "Na 10 tě {npc:1228}, trenér mágů v {area:131} v {area:2102}, pošle k {npc:5144} v {zone:1455}. Jeho přijetí uzavře {quest:1860}, pochůzku trenéra z {area:87}; Gizmonitor od {npc:5144} a {quest:1861} od {npc:5497} se navzájem vylučují, takže dostaneš jednu hůl nebo kouli. (Gnóm, který vzal quest {npc:328} v {area:87}, jde místo toho kroky {quest:1861}; Člověk, který vzal tenhle, kroky Gizmonitoru.)",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "Na 10 tě {npc:252373}, trenér mágů v {area:16638}, pošle k {npc:256507}, obchodníkovi s holemi pár kroků odsud ve stejném městě.",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {quest:1879}, the {area:131} trainer's errand; {quest:1861} and {npc:5144}'s Gizmonitor shut out each other, so you get one staff or orb."] = "Na 10 tě {npc:328}, trenér mágů v {area:87} nahoře v Lion's Pride Inn, pošle k {npc:5497} v {zone:1453}. Jeho přijetí uzavře {quest:1879}, pochůzku trenéra z {area:131}; {quest:1861} a Gizmonitor od {npc:5144} se navzájem vylučují, takže dostaneš jednu hůl nebo kouli.",
	["Back to {npc:256507}"] = "Zpět do {npc:256507}",
	["Back to {npc:5144}"] = "Zpět do {npc:5144}",
	["Back to {npc:5497}"] = "Zpět do {npc:5497}",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Zpět nahoru po Wizard's Sanctum a přes portál. Koule je do druhé ruky k jednoruční zbrani; hůl je obouruční.",
}
t.guides["forever/class/mage/teleports-alliance"] = {
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "Na 20 jdi do Wizard's Sanctum, fialové věže v {object:2101} v {zone:1453}. {npc:2485}, trenérka portálů, stojí úplně nahoře: vyjdi po spirálové rampě a vezmi portál u vrcholu. Naučí {spell:3561} za 20 stříbrných. Každý teleport spálí jeden {item:17031} (10 stříbrných u kteréhokoli obchodníka s reagenciemi; {npc:1308} je prodává u paty věže), tak jich nos pár.",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "Na 30. Vezmi loď z {area:17203} do {area:442} v {zone:1439}, pak loď do {area:702} a růžový portál nahoru do {zone:1457}. {npc:4165}, trenér portálů, naučí {spell:3565} za 80 stříbrných.",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "Na 40 naučí trenéři portálů portály: bránu, kterou projde celá skupina, za 1 zlatý 50 stříbrných každý. Každý portál spálí jeden {item:17032} (20 stříbrných u kteréhokoli obchodníka s reagenciemi). {npc:2485} má {spell:10059} na vrcholu Wizard's Sanctum; pak tramvají k {npc:2489} do {object:32362} v {zone:1455} pro {spell:11416}.",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "Na 50 tě {npc:4165} v {zone:1457} naučí poslední, {spell:11419}, za 3 zlaté 20 stříbrných. Dostaň se tam přes {spell:3565}.",
}
t.guides["forever/class/mage/teleports-horde"] = {
	["At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few."] = "Na 20 jdi do {object:173161} v {object:172961} v {zone:1454}, kde žijí trenéři mágů. {npc:5958}, trenér portálů, stojí v horním patře a naučí {spell:3567} za 20 stříbrných. Každý teleport spálí jeden {item:17031} (10 stříbrných u kteréhokoli obchodníka s reagenciemi), tak jich nos pár.",
	["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the Crossroads. {npc:5957}, the portal trainer, stands with the mage trainers in the {area:2197}, the cave under {area:1640}: go down inside, the arrow cannot tell the floors apart. She teaches {spell:3566} for 80 silver."] = "Na 30. {zone:1456} je v {zone:1412}: leť tam z {zone:1454} nebo z Crossroads. {npc:5957}, trenérka portálů, stojí s trenéry mágů v {area:2197}, jeskyni pod {area:1640}: jdi dovnitř dolů, šipka patra nerozliší. Naučí {spell:3566} za 80 stříbrných.",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}."] = "Na 40 naučí trenéři portálů portály: bránu, kterou projde celá skupina, za 1 zlatý 50 stříbrných každý. Každý portál spálí jeden {item:17032} (20 stříbrných u kteréhokoli obchodníka s reagenciemi). {npc:5958} v {object:173161} má {spell:11417}; teleportuj se do {zone:1458} pro {spell:11418} od {npc:2492}.",
	["At 50 {npc:5957}, down in the {area:2197} under {area:1640} in {zone:1456}, teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "Na 50 tě {npc:5957}, dole v {area:2197} pod {area:1640} v {zone:1456}, naučí poslední, {spell:11420}, za 3 zlaté 20 stříbrných. Dostaň se tam přes {spell:3566}.",
}
t.guides["forever/class/paladin/cloak-of-the-divine-storm"] = {
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Zpět k {npc:3663} do {area:413} v západním {zone:1440}, přes celou zónu.",
	["Back to {npc:5495}"] = "Zpět do {npc:5495}",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the {object:409289} at the top: it gives you the {item:209748}; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "Vyšplhej na vrchol {area:444} v severním {zone:1439}. Dark Strand Fanatics kolem jsou snadní (level 16–17), ale ve věži cestou ke kouli stojí čtyři Dark Strand Voidcallers (level 28–29): každý vyvolá voidwalkera a z dálky sesílá {spell:686}. Na 22–25 vezmi kamaráda nebo dva, tahej je po jednom a schovej se za zeď, ať musí přijít k tobě. Nahoře lootni {object:409289}: dá ti {item:209748}; kliknutím pravým začneš quest. Kouli nech v taškách až do {object:409311}: potřebují ji tři pozdější questy.",
	["The {object:409289}"] = "{object:409289}",
	["The {object:409311}"] = "{object:409311}",
}
t.guides["forever/class/paladin/holy-mightstone"] = {
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "Jednorázový kámen, který tě na 10 minut výrazně posílí proti nemrtvým; stará volba předmětu ve Foreveru možná není.",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "Na 50 tě {npc:5149}, trenér paladinů v {object:32362}, pošle do {area:3197} v {zone:1422}. Stejný quest dá {npc:928} v {zone:1453}.",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "Na 50 tě {npc:928}, trenér paladinů v Cathedral of Light, pošle do {area:3197} v {zone:1422}. Stejný quest dá {npc:5149} v {zone:1455}.",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "Zpět k Ashlamovi do {area:3197}: ukuje {item:20620}. Před odevzdáním se podívej do okna odměny: Classic nabízel i {item:20505}, {item:20504} nebo {item:20512} a poznámky Foreveru říkají, že ta volba možná zmizela. Kámen použij před bojem s nemrtvými ({area:2279}, {area:2057}): vydrží deset minut a po jednom použití je pryč.",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "Zpět do {area:3197}. Ashlam potřebuje na kámen voodoo trollů z {area:1417}.",
	["The {area:1417}"] = "{area:1417}",
	["The {quest:5401}"] = "{quest:5401}",
}
t.guides["forever/class/paladin/lumina-windsinger"] = {
	["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "Na 18 tě {npc:246378}, uvnitř {area:16602} na útesech severozápadně od {area:156}, pošle na jih k {area:228} v {zone:1421}.",
	["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "Na 20 chce {npc:259620} čepel, která dokáže zabít {quest:95140}. Promluv s {npc:248840} vedle ní kvůli jeho Weapon Notes, které vypisují části, a nech si je: chce je zpátky i s částmi. Tři části v libovolném pořadí: dvě z dungeonů (každý pro skupinu pěti) a drahokam od elitních nag venku u třetího.",
	["Back to the {area:228}"] = "Zpět do {area:228}",
	["Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword."] = "Zpět k {npc:248840} do spodní části {area:228}: dá ti {item:268484}, obouruční meč.",
	["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "Zpět k {npc:259620} do {area:228} s {item:268484} (quest ho chce): vezme ho a magií svého lidu ho požehná na {item:267369}.",
	["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "Zpět k {npc:259649} do Zoram'garu: očistí drahokam. {item:272448} si nech pro {npc:248840}.",
	["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "Přines dřevo, ingot a drahokam k {npc:248840} do {area:228}. Dá ti {item:268192} pro kováře v {area:272}: nech si ho v taškách.",
	["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 25 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "Nasaď {item:268484}. {quest:95140}, velký worgen, se toulá v lesích jižně od {area:228} směrem k branám {area:17065}. Je elitní (level 25): návod nejdřív počká na level 25 a doporučuje se skupina; hráči ho zabili od 22, jeden potřeboval druhého, jiný ho na 25 dal sám. Chrání ho fialový štít, dokud nedopadne tvůj první úder čepelí: zpráva ti řekne, že praskl.",
	["The {item:267361}"] = "{item:267361}",
	["The {item:272448}"] = "{item:272448}",
	["The {item:6995}"] = "{item:6995}",
}
t.guides["forever/class/paladin/tome-of-divinity"] = {
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "Na 12 tě {npc:5149}, trenér paladinů v {object:32362} v {zone:1455}, pošle nahoru k {npc:6179}. Pochůzka je volitelná, trochu XP: stejnou dá {npc:1232} v {area:131} i {npc:928} v {zone:1453} (přijetí jedné uzavře ostatní) a {npc:6179} řetěz začne i bez ní.",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "Na 12 tě {npc:927}, trenér paladinů v {area:87}, pošle k {npc:6171} do Cathedral of Light v {zone:1453}. Pochůzka je volitelná, trochu XP: stejnou dá {npc:5149} v {zone:1455} (přijetí jedné uzavře druhou) a {npc:6171} řetěz začne i bez ní.",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Zpět do Cathedral of Light: {npc:6173} vezme spis, {npc:6171} tě naučí {spell:7328}.",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Zpět do katedrály. {npc:6171} ti dá {item:6866}; {npc:6173} leží zraněný u oltáře ve stejné síni. Symbol si nech: potřebuješ ho na {npc:6172}. Když ho ztratíš, {npc:6171} ti dá další (The {item:6866}).",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Zpět nahoru do {object:32386}: {npc:6178} vezme spis, {npc:6179} tě naučí {spell:7328}.",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Zpět nahoře v {object:32386}. {npc:6179} ti dá {item:6866}; její manžel {npc:6178} odpočívá ve stejném patře. Symbol si nech: potřebuješ ho na {npc:6177}. Když ho ztratíš, {npc:6179} ti dá další (The {item:6866}).",
	["The {item:6846}"] = "{item:6846}",
	["The {item:6847}"] = "{item:6847}",
	["The {item:6866}"] = "{item:6866}",
	["{spell:7328} (Alliance)"] = "{spell:7328} (Aliance)",
}
t.guides["forever/class/paladin/tyrs-watch"] = {
	["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "Na 4 tě {npc:244808} pošle za {npc:246143}, která utekla do kopců západně od kostela, kousek jižně od netopýří jeskyně. Promluv s ní a nabídni pomoc: obrátí se proti tobě a musíš ji složit (level 3, snadné).",
	["At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later."] = "Na 8 tě {npc:246152} v {area:159} pošle do pevnosti řádu na západním pobřeží. {quest:91317} v {area:16881} a krypta pod ní na 8–9 tvrdě bijí: přijď na 10 nebo později.",
	["Back to the keep"] = "Zpět do pevnosti",
	["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "Zpět do {area:16602}, přes celé glades: Billmuth dole vezme plány, pak tě {npc:246378}, zpátky nahoře v pevnosti, naučí {spell:7328}.",
	["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "Zpět do {area:16602}. {npc:246378} ti dá {item:6866}; {npc:257655} čeká dole v pevnosti. Když symbol ztratíš, {npc:246378} ti dá další.",
	["Faintly Glowing Bones x6"] = "Faintly Glowing Bones x6",
	["The {item:6866}"] = "{item:6866}",
}
t.guides["forever/class/paladin/verigans-fist"] = {
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "Na 20 ti {npc:6179}, nahoře v {object:32386} v {object:32362}, dá {item:6776}. Klikni na něj pravým: pošle tě k {npc:6171} do Cathedral of Light v {zone:1453}. Vezmi {area:2257} z {zone:1455} do {zone:1453}.",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Zpět do Cathedral of Light: {npc:6171} ti dá štít {item:9607} a naučí tě {spell:5502}.",
	["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Zpět k {npc:3649} do {area:442}: očistí drahokam.",
	["Back to {npc:6241}"] = "Zpět do {npc:6241}",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "Přines čtyři části k {npc:6181} před {zone:1455}. Přijmi jeho poslední quest a čekej u něj, zatímco u kovadliny kuje palici.",
	["The {item:6995}"] = "{item:6995}",
	["The {item:7083}"] = "{item:7083}",
	["{object:91138}, inside"] = "{object:91138}, uvnitř",
}
t.guides["forever/class/priest/benediction"] = {
	["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "Nasaď {item:18646}, pak najdi {npc:14494}, ducha na svahu na severozápadě {zone:1423}, západně od brány {area:2279} (pokud se neukáže, Oko sundej a znovu nasaď). {quest:7621} je jen rozhovor; {quest:7622} začne ve chvíli, kdy ho přijmeš, tak se nejdřív připrav: plná mana, Major Mana Potions, Demonic nebo Dark Runes, jídlo na manu nebo {item:13931} a balík {item:8956} nebo {item:13180} na kostlivce.",
}
t.guides["forever/class/priest/blood-of-morphaz"] = {
	["17,060 XP and 1g55s at 50: {zone:1447}, then Morphaz in the {area:1417} (group of 5). The item choice may be gone."] = "17 060 XP a 1g55s na 50: {zone:1447}, pak Morphaz v {area:1417} (skupina 5). Volba předmětu už možná není.",
	["17,060 experience and 1 gold 55 silver"] = "17 060 zkušeností a 1 zlatý 55 stříbrných",
	["At 50 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) offers {quest:8254}. Before you leave a city, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 v {zone:1455} nabízí {npc:11406} v {object:32386} ({object:32362}) {quest:8254}. Než opustíš město, kup v aukci {item:7972} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["At 50, {npc:5489} at the altar of {zone:1453}'s Cathedral of Light offers {quest:8254} ({npc:11406} in {zone:1455} has it too). Before you leave, buy an {item:7972} at the Auction House in the {object:2096} (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 nabízí {npc:5489} u oltáře Cathedral of Light v {zone:1453} {quest:8254} (má ho i {npc:11406} v {zone:1455}). Než odejdeš, kup {item:7972} v aukci v {object:2096} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["At 50, {npc:6018} in {zone:1454}'s {object:172961} offers {quest:8254}. Before you leave, buy an {item:7972} at the Auction House (a few silver): the third quest asks for one and it drops rarely."] = "Na 50 nabízí {npc:6018} v {object:172961} v {zone:1454} {quest:8254}. Než odejdeš, kup v aukci {item:7972} (pár stříbrných): třetí quest jeden chce a padá vzácně.",
	["Carrying an {item:7972} already? It counts at once. Otherwise any undead may drop one, rarely: the {npc:7864} (level 48) in the {area:1221} below {npc:8405}'s cliff drop it about one kill in ten, the highborne ghosts on {zone:1447}'s border with {zone:1440} (level 45-46) a little less, the Anguished and {npc:7523} in {zone:1452} (54-55) about one in eight. The Auction House is usually quicker."] = "Už neseš {item:7972}? Započte se hned. Jinak ho může vzácně dropnout kterýkoli nemrtvý: {npc:7864} (level 48) v {area:1221} pod útesem {npc:8405} zhruba jedno zabití z deseti, highborne duchové na hranici {zone:1447} s {zone:1440} (level 45–46) o něco méně, Anguished a {npc:7523} v {zone:1452} (54–55) zhruba jeden z osmi. Aukce je obvykle rychlejší.",
}
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = {
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94820} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94823} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Jakýkoli dopis {quest:94825} jde k {npc:258785} v {object:32386}, {object:32362} v {zone:1455}.",
