	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis {quest:94817} pro {npc:258785} v {zone:1455}.",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 10 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:94817} pro {npc:258785} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "Na 10 jdi za {npc:258785} v {object:32386}, {object:32362} v {zone:1455} (severozápadně ve městě), hned vedle {npc:11406}: dá {quest:94817} a hned ho převezme. Dopis není potřeba. {quest:94817} zmate až pět nepřátel kolem tebe na 3 sekundy (probudí je jakékoli poškození) s cooldownem 2 minuty: čas ustoupit a vyléčit se, nebo utéct.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "Na 10 ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá dopis {quest:94817} pro {npc:258785} v {zone:1455}. {area:131} je na cestě nahoru do města.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:94818} pro {npc:258785} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "Na 20 tě {npc:258785} v {object:32386} naučí {quest:94818} questem, který dá a hned převezme. {quest:94818} na 30 sekund chrání přítele: když klesne pod 35 % zdraví, dostane hned štít a léčení v čase (stackuje se s {spell:139} a {spell:17}). Cooldown 5 minut.",
	["{npc:1226}: take his {quest:94817} letter"] = "{npc:1226}: vezmi jeho dopis {quest:94817}",
	["{npc:376}: take her {quest:94817} letter"] = "{npc:376}: vezmi její dopis {quest:94817}",
	["{npc:376}: take her {quest:94818} letter"] = "{npc:376}: vezmi její dopis {quest:94818}",
	["{npc:377}: take her {quest:94817} letter"] = "{npc:377}: vezmi její dopis {quest:94817}",
	["{quest:94817} and {quest:94818}"] = "{quest:94817} a {quest:94818}",
	["{quest:94820}: a letter from another trainer"] = "{quest:94820}: dopis od jiného trenéra",
	["{quest:94823}: a letter from another trainer"] = "{quest:94823}: dopis od jiného trenéra",
	["{quest:94824}: {npc:1226}'s letter"] = "{quest:94824}: dopis od {npc:1226}",
	["{quest:94825}: a letter from another trainer"] = "{quest:94825}: dopis od jiného trenéra",
