}
t.guides["forever/class/priest/desperate-prayer-and-chastise"] = {
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455} ({area:2257} z {object:28027} v {zone:1453}).",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Na 10 v {zone:1438} ti {npc:3600}, v budově na severním okraji {area:186}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455}.",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "Na 10 v {zone:1453} ti {npc:11397}, trenér kněží v Parku (čtvrť nočních elfů na západní straně města), dá dopis {quest:5634} pro {npc:11406} v {zone:1455}. {npc:376} v katedrále pro Trpaslíky žádný nemá.",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Na 10 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis {quest:5634} pro {npc:11406} v {zone:1455}.",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5639} and takes it back at once. No letter needed. {quest:5639} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "Na 10 jdi za {npc:11406} v {object:32386}, v {object:32362} v {zone:1455} (severozápadně ve městě): dá {quest:5639} a hned ho převezme. Dopis není potřeba. {quest:5639} tě okamžitě vyléčí, nestojí manu a má dlouhý cooldown: šetři ho na nouzi.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "Na 10 ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá dopis {quest:5634} pro {npc:11406}. {area:131} je na cestě nahoru do {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {quest:5641} pro {npc:11406} v {zone:1455} ({area:2257} z {object:28027}).",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "Na 20 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis {quest:5641} pro {npc:11406} v {zone:1455}.",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "Na 20 tě {npc:11406} v {object:32386} naučí {quest:5641} questem, který dá a hned převezme. Forever ho přejmenoval z A Lack of Fear: {quest:5641} zraní humanoida a na 2 sekundy ho přikove (okamžité, cooldown 2 minuty) a {spell:6346} teď trénuje každý kněz.",
	["{npc:11397}: take her {quest:5634} letter"] = "{npc:11397}: vezmi její dopis {quest:5634}",
	["{npc:11401}: take her {quest:5634} letter"] = "{npc:11401}: vezmi její dopis {quest:5634}",
	["{npc:11401}: take her {quest:5641} letter"] = "{npc:11401}: vezmi její dopis {quest:5641}",
	["{npc:1226}: take his {quest:5634} letter"] = "{npc:1226}: vezmi jeho dopis {quest:5634}",
	["{npc:3600}: take her {quest:5634} letter"] = "{npc:3600}: vezmi její dopis {quest:5634}",
	["{npc:376}: take her {quest:5641} letter"] = "{npc:376}: vezmi její dopis {quest:5641}",
	["{npc:377}: take her {quest:5634} letter"] = "{npc:377}: vezmi její dopis {quest:5634}",
	["{quest:5634} and {quest:5641}"] = "{quest:5634} a {quest:5641}",
	["{quest:5636}: {npc:3600}'s letter"] = "{quest:5636}: dopis od {npc:3600}",
