t.guides["forever/class/priest/divine-grace-and-feedback"] = {
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "Lidský kněz v {zone:1438} na 10: {npc:3600} v budově na severním okraji {area:186} ti dá dopis pro {npc:376} v {zone:1453}.",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94776} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94777} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94778} jde k {npc:376} u oltáře Cathedral of Light.",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Jakýkoli dopis {quest:94779} jde k {npc:376} u oltáře Cathedral of Light.",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get {spell:13908} in Forever: this is their spell instead."] = "Na 10 jdi za {npc:376} k oltáři Cathedral of Light v {object:2098} v {zone:1453} a vezmi její quest: naučí {quest:94773} na místě. Dopis není potřeba; funguje i dopis od jiného trenéra (další kroky). {quest:94773} okamžitě vyléčí přítele pod polovinou zdraví a zruší {spell:6788}, takže ho můžeš znovu stínit (cooldown 5 minut); na sebe nefunguje. Lidští kněží ve Foreveru nedostanou {spell:13908}: tohle je jejich kouzlo místo něj.",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "Na 10 ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá dopis pro {npc:376}. {area:87} je na cestě na sever do {zone:1453}, takže to nestojí žádnou odbočku.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "Na 20 v {zone:1455} ti {npc:11406} v {object:32386} ({object:32362}) dá dopis pro {npc:376} v {zone:1453}. Dostane tě tam {area:2257} z {object:171524}.",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "Na 20 v {zone:1457} ti {npc:11401}, na horním balkonu Temple of the Moon vedle {npc:7999}, dá dopis pro {npc:376} v {zone:1453}.",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "Na 20 tě {npc:376} u oltáře Cathedral of Light naučí {spell:13896} questem, který dá a hned převezme.",
	["{npc:11401}: take her {quest:5676} letter"] = "{npc:11401}: vezmi její dopis {quest:5676}",
	["{npc:11406}: take his {quest:5676} letter"] = "{npc:11406}: vezmi jeho dopis {quest:5676}",
	["{npc:3600}: take her {quest:94773} letter"] = "{npc:3600}: vezmi její dopis {quest:94773}",
	["{npc:377}: take her {quest:94773} letter"] = "{npc:377}: vezmi její dopis {quest:94773}",
	["{quest:94773} and {spell:13896}"] = "{quest:94773} a {spell:13896}",
	["{quest:94775}: {npc:3600}'s letter"] = "{quest:94775}: dopis od {npc:3600}",
	["{quest:94776}: a letter from another trainer"] = "{quest:94776}: dopis od jiného trenéra",
	["{quest:94777}: a letter from another trainer"] = "{quest:94777}: dopis od jiného trenéra",
