t.guides["forever/class/priest/hex-of-weakness-and-shadowguard"] = {
	["At 10 in the {zone:1458}, {npc:4606}, the priest trainer in the {object:36070}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454} (the zeppelin from the tower outside the {zone:1458})."] = "Na 10 v {zone:1458} ti {npc:4606}, trenérka kněží v {object:36070}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454} (zeppelin z věže před {zone:1458}).",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "Na 10 v {zone:1412} ti {npc:11407}, kousek jihozápadně od {area:222}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454}.",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "Na 10 v {zone:1456} ti {npc:3044}, trenér kněží v jeskyni pod {area:1640}, dá dopis {quest:5652} pro {npc:6018} v {zone:1454}.",
	["At 10, go to {npc:6018}, the priest trainer in a hut in the {object:172961}, {zone:1454}'s south-west corner: he gives {quest:5652} and takes it back at once. No letter needed."] = "Na 10 jdi za {npc:6018}, trenérem kněží v chýši v {object:172961}, v jihozápadním rohu {zone:1454}: dá {quest:5652} a hned ho převezme. Dopis není potřeba.",
	["At 10, {npc:3706}, the priest trainer inside the barracks of {area:362} (the first building on the right as you come up the road from the {area:363}), hands you a {quest:5652} letter for {npc:6018} in {zone:1454}. {area:362} is on the road north to the city."] = "Na 10 ti {npc:3706}, trenér kněží v kasárnách {area:362} (první budova vpravo, když jdeš po cestě nahoru z {area:363}), dá dopis {quest:5652} pro {npc:6018} v {zone:1454}. {area:362} je na cestě na sever do města.",
	["At 20 in the {zone:1458}, {npc:4606} in the {object:36070} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "Na 20 v {zone:1458} ti {npc:4606} v {object:36070} dá dopis {quest:5642} pro {npc:6018} v {zone:1454}.",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "Na 20 v {zone:1456} ti {npc:3044} v jeskyni pod {area:1640} dá dopis {quest:5642} pro {npc:6018} v {zone:1454}.",
	["At 20, {npc:6018} in the {object:172961} teaches {quest:5680} with a quest he gives and takes back at once."] = "Na 20 tě {npc:6018} v {object:172961} naučí {quest:5680} questem, který dá a hned převezme.",
	["{npc:3044}: take his {quest:5642} letter"] = "{npc:3044}: vezmi jeho dopis {quest:5642}",
	["{npc:3044}: take his {quest:5652} letter"] = "{npc:3044}: vezmi jeho dopis {quest:5652}",
