t.guides["forever/class/priest/priest-robes-alliance"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Neobvyklé roucho zdarma na 5: ošetři a posilni zraněného strážce u svého prvního města.",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:3595}, trenérka kněží ve druhém patře {area:256}, velkého stromu v {area:188}, pošle k {npc:3600} v {area:186}. Když už jsi tady, vytrénuj od ní {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:375}, trenérka kněží v {area:24}, pošle k {npc:377} v {area:87}. Když už jsi tady, vytrénuj od Anetty {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:837}, trenér kněží v {area:77} v {area:132}, pošle k {npc:1226} v {area:131}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "Zpět na severním okraji {area:186}: {npc:3600} ti dá {item:16604}.",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "Zpět v {area:2102}: {npc:1226} ti dá {item:16605}.",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "Zpět nahoře v Lion's Pride Inn: Josetta ti dá {item:16605}.",
}
t.guides["forever/class/priest/priest-robes-horde"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Neobvyklé roucho zdarma na 5: ošetři a posilni zraněného strážce u svého prvního města.",
	["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:2123}, trenér kněží v kapli {area:154}, pošle k {npc:2129} v {area:159}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Na 5 tě {npc:3707}, trenér kněží v Den uprostřed {area:363}, pošle k {npc:3706} v {area:362}. Když už jsi tady, vytrénuj od něj {spell:613} (Rank 2): otevře se na levelu 4 za 1 stříbrný a další quest chce přesně tento rank.",
	["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "Zpět v kasárnách {area:362}: {npc:3706} ti dá {item:16606}.",
	["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "Zpět nahoře v hostinci {area:159}: Beryl ti dá {item:16607}.",
}
t.guides["forever/class/priest/starshards-and-elunes-grace"] = {
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1426} ti {npc:1226}, trenér kněží v {area:2102} v {area:131}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1429} ti {npc:377}, nahoře v Lion's Pride Inn v {area:87}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Na 10 v {zone:1453} ti {npc:5489} u oltáře Cathedral of Light dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}. Stejný dopis má {npc:11397} v Parku.",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Na 10 v {zone:1455} ti {npc:5142} v {object:32386} ({object:32362}) dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}.",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Na 10 jdi za {npc:11401} na horní balkon Temple of the Moon na jižním konci {zone:1457}: vyjdi po rampě z podlahy chrámu; stojí vedle {npc:7999}. {quest:5627} se dá a hned převezme a naučí {spell:10797}. Dopis není potřeba. Forever udělal {spell:10797} mnohem silnějším, s cooldownem 30 sekund.",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Na 10 ti {npc:3600}, trenér kněží v budově na severním okraji {area:186}, dá {quest:5628}, dopis pro {npc:11401} v {zone:1457}. {area:186} je na cestě na západ do {zone:1457}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Na 20 v {zone:1453} ti {npc:376} u oltáře Cathedral of Light dá dopis {spell:2651} pro {npc:11401} v {zone:1457}. Stejný dopis má {npc:11397} v Parku.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Na 20 v {zone:1455} ti {npc:11406} v {object:32386} ({object:32362}) dá dopis {spell:2651} pro {npc:11401} v {zone:1457}.",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Na 20 tě {npc:11401} na horním balkonu Temple of the Moon, vedle {npc:7999}, naučí {quest:5672} questem, který dá a hned převezme. Ve Foreveru {quest:5672} na 15 sekund nebo do tří minutí sníží na polovinu šanci, že tě zasáhnou útoky na blízko a na dálku.",
	["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}: vezmi jeho dopis {spell:2651}",
	["{npc:376}: take her {spell:2651} letter"] = "{npc:376}: vezmi její dopis {spell:2651}",
	["{spell:10797} and {spell:2651}"] = "{spell:10797} a {spell:2651}",
	["{spell:10797}: {npc:1226}'s letter"] = "{spell:10797}: dopis od {npc:1226}",
	["{spell:10797}: {npc:3600}'s letter"] = "{spell:10797}: dopis od {npc:3600}",
	["{spell:10797}: {npc:5142}'s letter"] = "{spell:10797}: dopis od {npc:5142}",
}
t.guides["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = {
	["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Na 10 v {zone:1411} ti {npc:3706}, trenér kněží v kasárnách {area:362}, dá dopis {spell:2652} pro {npc:4606} v {zone:1458}.",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Na 10 v {zone:1412} ti {npc:11407}, kousek jihozápadně od {area:222}, dá dopis {spell:2652} pro {npc:4606} v {zone:1458}.",
	["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "Na 10 v {zone:1454} ti {npc:6018} v {object:172961} dá dopis {spell:2652} pro {npc:4606} v {zone:1458}. Zeppelin do {zone:1420} odlétá z věže před hlavní branou {zone:1454}.",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "Na 10 v {zone:1456} ti {npc:3044}, trenér kněží v jeskyni pod {area:1640}, dá dopis {spell:2652} pro {npc:4606} v {zone:1458}.",
	["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "Na 10 jdi za {npc:4606}, trenérkou kněží v {object:36070} v {zone:1458}: dá {quest:5658} a hned ho převezme. Dopis není potřeba. Z {area:159} jdi po cestě na jih do zničeného města Lordaeron; výtahy do {zone:1458} jsou vzadu v trůnním sále. {quest:5658} zasáhne dalšího útočníka na blízko Shadow poškozením a na 2 minuty mu sníží melee attack power.",
	["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Na 20 v {zone:1454} ti {npc:6018} v {object:172961} dá dopis {quest:5644} pro {npc:4606} v {zone:1458}.",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "Na 20 v {zone:1456} ti {npc:3044} v jeskyni pod {area:1640} dá dopis {quest:5644} pro {npc:4606} v {zone:1458}.",
	["At 20, {npc:4606} in the {object:36070} teaches {quest:5679} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "Na 20 tě {npc:4606} v {object:36070} naučí {quest:5679} questem, který dá a hned převezme (jeho text pořád mluví o {spell:2944}, které se teď každý kněz učí u trenéra).",
	["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044}: vezmi jeho dopis {quest:5644}",
	["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044}: vezmi jeho dopis {spell:2652}",
	["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706}: vezmi jeho dopis {spell:2652}",
	["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018}: vezmi jeho dopis {quest:5644}",
