	["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646}: dopis od {npc:6018}",
	["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660}: dopis od {npc:3706}",
	["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661}: dopis od {npc:11407}",
