	["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "Na 10 tě {npc:1234}, trenér rogue v {area:2102} v {area:131}, pošle k {npc:5165} v {zone:1455}.",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Na 10 ti {npc:3599}, trenér rogue v hostinci {area:186}, dá růži pro {npc:4163} v {zone:1457}. Když růži ztratíš, quest zruš a vezmi znovu.",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Na 10 ti {npc:917}, trenér rogue nahoře v Lion's Pride Inn v {area:87}, dá balíček pro {npc:332} v {zone:1453}. Pokud nemáš {spell:921}, vytrénuj ho: tenhle řetěz ho potřebuje.",
	["Back to Mathias Shaw"] = "Zpět k Mathiasi Shawovi",
