t.guides["forever/class/rogue/plundering-the-plunderers"] = {
	["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "Na 16 tě {npc:3170}, trenér rogue v {area:362}, pošle k {npc:3401} v {zone:1454}.",
	["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "Na 16 tě {npc:6467} v {object:36073} pošle k {npc:3401} v {zone:1454}. Vezmi od něj i {quest:1998}; plní se v {zone:1421} na konci tohoto návodu.",
