t.guides["forever/class/rogue/poisons-alliance"] = {
	["/lay with the Doc targeted"] = "/lay se zaměřeným Docem",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Všechny čtyři jsou v {zone:1453}. {item:3421}: Bernard nebo květinářství {npc:1303} u kanálu {object:2096}. {item:3372}: hodně obchodníků se smíšeným zbožím a alchymií ({npc:1257}, {npc:1325} a další). {item:4371}: aukce v {object:2096}; dodavatelé inženýrství mají jen jeden a skoro vždy vyprodaný, a inženýr ho umí vyrobit. {item:8431} leží na podlaze u levého konce pultu v {object:2177}, krejčovství na kanálech; sebrat ho jde jen s tímto questem. Když léčbu přeskočíš, {spell:9810} odstraní i {item:6452} ({skill:129}) nebo druidův {spell:526}.",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Na 20 tě {npc:332}, nahoře v budově SI:7 v {object:2100}, pošle k {npc:7024} v {zone:1436}. Tímhle řetězem se ve Foreveru učíš Poisons, tak ho nepřeskakuj.",
	["Back to {npc:7207}"] = "Zpět do {npc:7207}",
	["{item:4371}: the Auction House"] = "{item:4371}: aukce",
}
t.guides["forever/class/rogue/poisons-horde"] = {
	["/salute {npc:3401}"] = "/salute {npc:3401}",
	["Back to {npc:3401}"] = "Zpět do {npc:3401}",
	["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {spell:8681} takes one of each."] = "Leť zpátky do {zone:1454} ({area:392} nebo Crossroads; rychlejší je umřít u věže a vrátit se cestou spirit healera do Crossroads). {item:8072} si potom nech. Než opustíš {area:263}, kup u Rekkula {item:2928} a Empty Vials: jakmile tě Hinott naučí Poisons, každá dávka {spell:8681} spotřebuje od obojího jeden kus.",
}
t.guides["forever/class/rogue/ravenholdt"] = {
	["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "Na 24 pro tebe má trenér rogue kteréhokoli hlavního města ({npc:332} nebo {npc:918} v {zone:1453}, Gest nebo Ormok v {zone:1454} a ostatní) {item:17126} od {npc:13936}: požádej o něj v jeho okně rozhovoru. Otevři ho: quest ti dá {item:17125} pro {npc:6707}. Pokud ho nemáš, nejdřív se u trenéra nauč {spell:1846}; cesta dovnitř je jeho zkouška.",
	["Back to {npc:13085}"] = "Zpět do {npc:13085}",
	["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Zpět k {npc:13085}; hlášení tě pošle za dědictvím Perenolde. Mezi {area:281} uprostřed {zone:1416} stojí dvě věže v držení zlobrů: štít leží v severní věži, meč v jižní, kterou obklopují a z dálky hlídají elitní zlobři. Zůstaň ve stealthu; dědictví uvnitř nic nehlídá.",
	["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Falconcrestovi muži provádějí předání na jižním konci {area:1057}, staré zdi mezi Arathi a {area:287}. Zabij ty dva, co hlídají bednu, a vezmi {item:275882}. {item:275706} si nech: {npc:13085} ho chce zpátky spolu se zásilkou.",
	["The {item:17126}"] = "{item:17126}",
	["{quest:96784}: the {item:275706}"] = "{quest:96784}: {item:275706}",
}
t.guides["forever/class/rogue/the-azure-key"] = {
	["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "Aliance letí do {area:3137}, Horda do {area:1237}. Vak nesou jen Timbermaw Shamans levelu 50–51 ve furbolžích kopcích severního {zone:1447} (furbolgové 47–49 dál na jih ne): padá zhruba z jednoho zabití z třiceti. Místo toho je {spell:921} a nepřijdeš o reputaci Timbermaw; pokud jsi s {area:1769} Unfriendly nebo líp, nejdřív je v panelu reputace označ At War. Sesílají {spell:403} a {spell:6535}, léčí se navzájem a při nízkém zdraví utíkají.",
	["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "Na 50 ho má {npc:3328} v {object:172960}; stejně tak {npc:4583} v {object:36073} v {zone:1458}.",
	["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "Na 50 ho má {npc:918} v {object:2100} v {zone:1453}; stejně tak Syurna v {zone:1457} a {npc:5165} v {zone:1455}.",
	["Back to Xylem"] = "Zpět k Xylemovi",
	["{quest:8233} (Alliance)"] = "{quest:8233} (Aliance)",
	["{quest:8233} (Horde)"] = "{quest:8233} (Horda)",
}
t.guides["forever/class/rogue/the-eye-of-bhossca"] = {
	["Back to the dead drop"] = "Zpět k mrtvé schránce",
	["C's dead drop"] = "Cova mrtvá schránka",
	["C's next job comes by letter: once you are level 30 and have done the horn job (The {item:210183}, its payment from this {object:410369} handed in), visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "Další práce od C přijde dopisem: jakmile máš level 30 a hotovou práci s rohem (The {item:210183}, její platbu z této {object:410369} odevzdanou), navštiv kterékoli hlavní město a Cův dopis dorazí do poštovní schránky; teprve pak ho {object:410369} u {area:204}, v jižním Silverpine kousek jižně od {area:236}, nabídne. Data questu uvádějí minimum 25, ale hráči dopis i práci dostávají na 30.",
	["The {area:796}"] = "{area:796}",
}
t.guides["forever/class/rogue/the-horn-of-xelthos"] = {
	["Back to the dead drop"] = "Zpět k mrtvé schránce",
	["C's dead drop"] = "Cova mrtvá schránka",
	["{item:210183}, inside {area:236}"] = "{item:210183}, uvnitř {area:236}",
}
t.guides["forever/class/shaman/call-of-air-alliance"] = {
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Na 30 tě {npc:258098}, trenér šamanů v {zone:1455}, pošle k {npc:259023} v {zone:1417}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují {item:5178}, který dá.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Pět Twisted Air Totems. Nosí je kentauři Maraudine (level 36–40) severně a severovýchodně od {area:2408} v západním {zone:1443}; Scouts dropnou jeden skoro každé druhé zabití. Wranglers házejí síť a odzbrojují, Windchasers léčí, Stormers sesílají {spell:9654}: tahej je po jednom. Respawn asi pět minut.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Pět Twisted Earth Totems. Nosí je Lost Ones (murloci, level 34–39) severně a severovýchodně od {area:75} v {zone:1435}; většina při zranění utíká pro pomoc.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Pět Twisted Fire Totems. Nosí je troggové Stonevault (Skullthumpers, Bonesnappers a Shamans, level 37–41) jižně od {area:338} v {zone:1418}; Shamans pokládají Fire Nova Totems a {npc:3560}, Bonesnappers při zranění utíkají pro pomoc. Respawn asi pět minut.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Pět Twisted Water Totems. Nosí je murloci Mirefin (level 35–38) severovýchodně od {area:496} v severním {zone:1445}.",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}, od {npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}, od {npc:4421}",
}
t.guides["forever/class/shaman/call-of-air-horde"] = {
	["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "Na 30 dostanou šamani Skyborne vlastní {quest:96136}. {npc:259119} čeká tam, kde přistává vzducholoď ze Zephras Isle, v severním {zone:1412} vedle {zone:1456}. Tvoje vzdušné totemy levelu 30 potřebují Air Totem, který dá Prate Cloudseer. Pokud pro tebe nic nemá, jdi nahoru k {npc:5906} v {zone:1456} (další krok): {quest:96136} od trenérů je Skyborne otevřený a dá stejný totem.",
	["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "Na 30 tě {npc:5892} v {object:172957} pošle k {npc:5905} v {zone:1441}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují {item:5178}, který dá.",
	["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1532} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "Na 30 tě {npc:5906}, trenér šamanů na {area:1640} v {zone:1456}, pošle k {npc:5905} v {zone:1441}. Tvoje vzdušné totemy levelu 30 (Grounding, {spell:10596}) potřebují Air Totem, který dá Prate. Už neseš {quest:1532} od {npc:5892} z {zone:1454}? Jde taky k {npc:5905}: {npc:5906} přeskoč.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Pět Twisted Air Totems. Nosí je kentauři Maraudine (level 36–40) severně a severovýchodně od {area:2408} v západním {zone:1443}; Scouts dropnou jeden skoro každé druhé zabití. Wranglers házejí síť a odzbrojují, Windchasers léčí, Stormers sesílají {spell:9654}: tahej je po jednom. Respawn asi pět minut.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Pět Twisted Earth Totems. Nosí je Lost Ones (murloci, level 34–39) severně a severovýchodně od {area:75} v {zone:1435}; většina při zranění utíká pro pomoc.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Pět Twisted Fire Totems. Nosí je troggové Stonevault (Skullthumpers, Bonesnappers a Shamans, level 37–41) jižně od {area:338} v {zone:1418}; Shamans pokládají Fire Nova Totems a {npc:3560}, Bonesnappers při zranění utíkají pro pomoc. Respawn asi pět minut.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Pět Twisted Water Totems. Nosí je murloci Mirefin (level 35–38) severovýchodně od {area:496} v severním {zone:1445}.",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}, od {npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}, od {npc:4421}",
}
t.guides["forever/class/shaman/call-of-earth-alliance"] = {
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Zpět k Teovi do {area:77}. Dá ti {item:6635}: zatím ho nepij.",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Teovi do {area:77}. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Lost the {quest:94472}?"] = "Ztratil jsi {quest:94472}?",
