}
t.guides["forever/class/shaman/call-of-earth-horde"] = {
	["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "{item:251924} může nést kterýkoli kultista Al'Aketh: Converts (level 2–3) u menhirů kousek východně od vesnice, nebo Brutes a Neophytes (level 4) v táboře za {npc:252095}, jihozápadně od vesnice. Zabíjej, dokud ho jeden nedropne.",
	["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "Zpět k Borovi do {area:16635}. Dá ti {quest:1462}: zatím ho nepij.",
	["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "Zpět k Vědmě do {area:221}. Dá ti {quest:1462}: zatím ho nepij.",
	["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "Zpět k {npc:5887} před Den. Dá ti {quest:1462}: zatím ho nepij.",
	["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Borovi. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět Vědmě. {item:5175} si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Přines {item:6656} zpět {npc:5887} před Den. {item:5175}, který ti dá, si nech v taškách natrvalo: potřebuje ho každý zemní totem.",
	["Felstalker Hooves"] = "Felstalker Hooves",
	["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Felstalkeři (level 3–4) se potulují po svahu pod {area:365}, jeskyní na severu údolí, a hned uvnitř jejího ústí mezi Vile Familiars. Skoro každý {npc:3102} dropne kopyto (čtyři zabití z pěti); respawnují se za něco přes tři minuty.",
	["Lost the {quest:1462}?"] = "Ztratil jsi {quest:1462}?",
	["Lost the {quest:1463}?"] = "Ztratil jsi {quest:1463}?",
	["The {area:16988}"] = "{area:16988}",
	["{item:6635}, beside {area:637}"] = "{item:6635}, vedle {area:637}",
	["{item:6635}, beside {area:639}"] = "{item:6635}, vedle {area:639}",
	["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}: {spell:8071} a tvůj {item:5175}",
	["{npc:5887}: a new {quest:1463}"] = "{npc:5887}: nový {quest:1463}",
	["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}: {spell:8071} a tvůj {item:5175}",
	["{npc:5888}: a new {quest:1462}"] = "{npc:5888}: nový {quest:1462}",
	["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}: {spell:8071} a tvůj {item:5175}",
	["{quest:1516} (Horde)"] = "{quest:1516} (Horda)",
}
t.guides["forever/class/shaman/call-of-fire-alliance"] = {
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Na 10 tě {npc:258113}, trenér šamanů v {area:131}, nebo {npc:258098}, trenér šamanů v {zone:1455}, pošle k {npc:257597}.",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Zpět tunelem South Gate a po stezce nahoru do jeskyně {npc:257597}. {item:5176} si nech v taškách natrvalo: potřebuje ho každý ohnivý totem.",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Zpět nahoru po stezce k {npc:257808}. Z dehtu a váčku vyrobí {item:6636}: nech si ho s pochodní.",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "S pochodní v taškách klikni na {object:61934} na vrcholu svatyně a polož uhlík, pak klikni znovu pro další quest: zapálenou {item:277329}.",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Vyšplhej kolem {npc:257808} až na vrchol. Vypij {item:6636} u kamenné sochy, ať uvidíš {npc:5893} (level 12): čeká, dokud neudeříš, ale čím déle ho necháš, tím je silnější, a na oheň je imunní. Začni hned {spell:8017} a {spell:8042}. Jeho {item:6655} padá pokaždé.",
	["Lost the {quest:94473}?"] = "Ztratil jsi {quest:94473}?",
	["The {object:61934}"] = "{object:61934}",
	["{npc:257808}: a new {quest:94473}"] = "{npc:257808}: nový {quest:94473}",
	["{quest:94449} (Alliance)"] = "{quest:94449} (Aliance)",
}
t.guides["forever/class/shaman/call-of-fire-horde"] = {
	["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "Na 10 ti {npc:252382}, trenérka šamanů vedle {npc:251968} v {area:16638}, dá {item:6653} (stejný quest nabízí {npc:254082}). Už jsi opustil ostrov? {quest:97243} tě k nim pošle zpět: vezmi skycutter z útesů jižně od {area:17045}, severně od {zone:1456}. Nauč se teď od ní {spell:8050}: {npc:268605}, později v řetězu, bere jen fire poškození.",
	["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "Na 10 tě {npc:3066}, trenér šamanů v {area:222}, pošle k {npc:5907} v {zone:1413}. Už neseš dopis od {npc:5906} z {zone:1456}? Jde taky k {npc:5907}: Narma přeskoč.",
	["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "Na 10 tě {npc:3173}, trenér šamanů na východní straně {area:362}, pošle k {npc:5907} v {zone:1413}. Už neseš dopis od {npc:5892} z {zone:1454}? Jde taky k {npc:5907}: {npc:3173} přeskoč.",
	["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "Zpět na východ přes most, pak na jih po břehu řeky v {zone:1411} tam, kde se hory setkávají s vodou. Stezka nahoru začíná u paty hory vedle malého tmavého kamene s vytesanými symboly, blízko tábora quilboarů; je úzká a uklouznutí stojí poškození pádem. Svatyni nahoře drží {npc:5900}.",
	["Back to {npc:268592} at the Shrine of Flames."] = "Zpět k {npc:268592} do Shrine of Flames.",
	["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "Zpět k {npc:268592}. Přijmi poslední quest a čekej u {npc:268762}, zatímco provádí rituál; až ohniví duchové zapálí {object:148418}, přilož k němu pochodeň. Od té chvíle máš šest minut: nes plamen rovnou k {npc:268679} vedle {npc:252382} v {area:16638}, bez odboček a bojů. Čas vypršel? Quest zruš a vezmi znovu od {npc:268592}.",
	["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "Zpět nahoru po stezce k {npc:5900}. Z dehtu a váčku vyrobí {quest:1464} a dá ti ho s pochodní: nech si obojí.",
	["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "S pochodní v taškách klikni na {object:61934} na plošině a polož uhlík, pak klikni podruhé: další quest se neotevře sám. Dá ti zapálenou {item:277329}.",
	["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Dolů po stezce, zpět přes most k {npc:5907} u jeho věže. {item:5176} si nech v taškách natrvalo: potřebuje ho každý ohnivý totem.",
	["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Vypij {item:6636} vedle {object:63674}, velkého šedého kamene kousek pod vrcholem, pak vyšplhej na plošinu. Z ohnivých elementálů tam jde napadnout jen ten uprostřed: má level 12, je imunní vůči ohni a čím déle boj trvá, tím je silnější, tak začni hned {spell:8017} a {spell:8042} a ostatní nech být. Jeho {item:6655} padá pokaždé.",
	["Lost the {quest:1464}?"] = "Ztratil jsi {quest:1464}?",
	["The {npc:5893}"] = "{npc:5893}",
	["The {object:148418}"] = "{object:148418}",
	["The {object:61934}"] = "{object:61934}",
	["{npc:5900}: a new {quest:1464}"] = "{npc:5900}: nový {quest:1464}",
	["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}: dopis od {npc:3066}",
	["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}: dopis od {npc:3173}",
	["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}: dopis od {npc:5892}",
	["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}: dopis od {npc:5906}",
	["{quest:1522} (Horde)"] = "{quest:1522} (Horda)",
}
t.guides["forever/class/shaman/call-of-water-alliance"] = {
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Na 20 tě {npc:258098}, trenér šamanů v {object:32362} v {zone:1455}, pošle k {npc:258043} v {zone:1432}.",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Zpět k {npc:258043} u {area:146} s {item:7810}. Dá ti {item:6637} a {item:7811}: nech si obojí pro {zone:1436}.",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zpět k {npc:258043} s {item:7813}. {item:5177} si nech v taškách natrvalo: potřebuje ho každý vodní totem.",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Naplň {item:265732} na úpatí vodopádů pod jeskyní {npc:258203}, kde se sladká voda mísí s brakickou. U vodopádů se potulují trpaslíci {object:147516}.",
	["Lost the {quest:94616}?"] = "Ztratil jsi {quest:94616}?",
	["{npc:258043}: a new {quest:94616}"] = "{npc:258043}: nový {quest:94616}",
	["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} a tvůj {item:5177}",
	["{quest:94494} (Alliance)"] = "{quest:94494} (Aliance)",
}
t.guides["forever/class/shaman/call-of-water-horde"] = {
	["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "Na 20 tě {npc:5892} v {object:172957} pošle k {npc:5901} v {zone:1413}. (Swart v {area:362} dá stejný dopis: nos kterýkoli.)",
	["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "Na 20 tě {npc:5906}, trenér šamanů na {area:1640} v {zone:1456}, pošle k {npc:5901} v {zone:1413}. ({npc:3066} v {area:222} dá stejný dopis: nos kterýkoli.)",
	["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "Zpět k {npc:5899}. Dá ti {item:7810} pro {npc:5901}.",
	["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Zpět k {npc:5901} jižně od {area:392}. {item:5177} si nech v taškách natrvalo: potřebuje ho každý vodní totem.",
	["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Klikni na {object:113791} a polož náramky a kapky. Za pár sekund se na kameni uprostřed tůně zvedne čistý {npc:5895}: promluv s ním, dokud trvá {spell:8202} (pokud vyprchalo, napij se znovu u kamene). Dá ti {item:7813} pro {npc:5901}. Zmizel dřív, než jsi s ním promluvil? Zpět u {npc:5901} požádej o {quest:63} (nový {quest:972} pro {npc:7007}, který stojí kousek západně od svatyně): předej ho Tievovi, zůstaň blízko, zatímco ducha přivolá zpět, a pak s ním promluv.",
	["Lost the {quest:972}?"] = "Ztratil jsi {quest:972}?",
	["The {npc:5895}"] = "{npc:5895}",
	["The {object:107045}"] = "{object:107045}",
	["The {object:107046}"] = "{object:107046}",
	["The {object:113791}"] = "{object:113791}",
	["{npc:5901}: a new {quest:972}"] = "{npc:5901}: nový {quest:972}",
	["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}: dopis od {npc:5892}",
	["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} a tvůj {item:5177}",
	["{quest:63} (Horde)"] = "{quest:63} (Horda)",
}
t.guides["forever/class/shaman/darkreaver"] = {
	["200 Horde reputation"] = "200 reputace u Hordy",
	["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Dungeonová událost pro pět hráčů: {area:2057} leží pod {area:2298}, ostrovním městem na jihovýchodě {zone:1422}. Ve sklepě {object:179746} nejdřív vybij všechny moby v místnosti, pak uprostřed použij {item:18746}: následují čtyři vlny duchů, každou uzavře mini-boss Aspect (první vlna slabá a pomalá, ostatní elitní). Bojuj v rohu, aby se nic dalšího nepřidalo, a mezi vlnami pij: je to dlouhé. Pak se objeví {npc:14516} (level 62 elite): Cleavuje, sesílá {spell:686} a {spell:6958} a ovládne mysl hráče proti skupině. Jeho hlava padá vždy.",
	["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Souboj v {area:2057} na 60 kvůli reputaci u Hordy; {item:20134} ve Foreveru možná není.",
	["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "Na 58 chce {npc:13417}, trenér šamanů v {object:172957}, dva vzácné diamanty; chodí k němu každý šaman Hordy. Skyborne: stránka questu ve Foreveru ho uvádí jen pro Orky, Taureny a Trolly: zeptej se, než diamanty koupíš.",
	["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Oba diamanty jsou vzácné: rychlá cesta je aukce. Horníci najdou {item:12800} zhruba v jedné Thorium žíle ze sta (Small Thorium Veins severně od {area:2418} v {zone:1428} se obnovují každých pět minut). {item:18335} padá z vysokolevelových elit zhruba jeden ze sta, nejlépe ze vzácné elity Revanchion (zhruba jeden z devíti).",
}
t.guides["forever/class/shaman/spirit-totem"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Dungeon pro pět hráčů: potřebuje skupinu pěti, asi level 50–55. Leť do {area:75} a jeď na východ. {area:1417} ({area:1477}) stojí uprostřed {area:74}: vyjdi po schodech na jižní straně ruiny, skoč do zatopené síně, proplav dolů a sleduj schody a chodby dolů k portálu. Dvě pera od každé barvy, po jednom od každého ze šesti elitních trollích mini-bossů (level 51–52) na balkonech kolem velké kruhové síně chrámu, při každém zabití, a každý hráč na questu lootuje svoje: Gasher a {npc:5716} Amber, Hukku a Mijan Blue, Zolo a Loro Green. Mijan léčí ostatní ({spell:139}, {npc:3560}): zabij ho první; Hukku vyvolává strážce a hází Shadow Bolt Volley.",
	["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "Na 50 chce {npc:13417}, trenér šamanů v {object:172957}, čtyři živly pro {npc:6176}.",
	["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "Na 50 chce {npc:3032}, trenér šamanů na {area:1640} v {zone:1456}, čtyři živly pro {npc:6176}. Skyborne: stránka questu ve Foreveru uvádí {quest:8410} a {quest:8412} jen pro Orky, Taureny a Trolly; pokud pro tebe {npc:3032} nic nemá, vlastní {quest:8411} od {npc:6176} je otevřený každé rase Hordy, ale {quest:8412} po něm tě pořád může odmítnout.",
	["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Osm od každého. Leť nebo jeď do {area:813} a dál na západní okraj {zone:1422}, severozápadně od {area:3197}: Venom Mist Lurkers (level 50–51, otravují) dají {item:20610} a Diseased Black Bears (level 51–52, {spell:3427}) {item:20611}, každý zhruba jedno zabití z pěti; dva Carrion Vultures tam dropují obojí. Větší Diseased Grizzlies a Plague Lurkers dál na východ je skoro nedropují. Pár medvědů a lurkerů se toulá i jihovýchodně od {area:159} v Tirisfalu.",
	["Experience and gold"] = "Zkušenosti a zlato",
	["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "Zkušenosti a zlato na 50, končí v {area:1417}; výběr předmětu z Classicu ve Foreveru možná chybí.",
	["The {area:1417}"] = "{area:1417}",
	["{quest:8412} and {quest:8413}"] = "{quest:8412} a {quest:8413}",
}
t.guides["forever/class/warlock/dread-mage-hat"] = {
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Látková čepice ve tvých pozdních dvacítkách: Zardethova pochůzka pro kteréhokoli hráče Aliance za ni warlockům platí navíc.",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Na 25 chce {npc:1435}, ve sklepě {object:2164} v {object:2101} (vedle trenérů warlocků), dvě přísady do lektvaru. Udělej to, až tě levelování zavede do {zone:1431} a {zone:1437}.",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Ještě jednou zpět k Zardethovi: warlockům nabídne odměnu, kterou předá jeho imp {npc:1733} stojící vedle něj.",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Zpět k Zardethovi. Uvaří {item:2788} a dá ti ho pro {npc:1439} v Hall of Petitioners, první síni vpravo v {object:2117}.",
}
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = {
	["A rare cloth robe for your 30s from {npc:6266}; its last parts wait for levels 37 and 39."] = "Vzácné látkové roucho pro tvoje třicítky od {npc:6266}; jeho poslední části čekají na levely 37 a 39.",
	["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:3326} v {object:172960} pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:4563} v {object:36082} pošle k {npc:6266} v {area:392}; zeppelin z {zone:1420} letí do {zone:1411}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Na 31 tě {npc:5172} v {zone:1455} pošle k {npc:6266} v {area:392}. Nejdřív kup {item:5770} a {item:3577} (další kroky), ušetříš cestu.",
	["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "Zpět k {npc:2670} do {area:35}: nabídne {quest:4785} jako quest, který mu hned vrátíš. Nemusí mít značku questu; promluv s ním i tak.",
	["Back to {npc:6266}"] = "Zpět do {npc:6266}",
	["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "Zpět k {npc:6266} s nití, uhlíky a {item:6265}. Pak čekej vedle ní, zatímco pracuje na rouchu (neútoč na ni: deník questů tomu říká zabití), a znovu s ní promluv.",
	["{item:3577}: the Auction House"] = "{item:3577}: aukce",
	["{item:5770}: the Auction House"] = "{item:5770}: aukce",
	["{npc:6266} again"] = "{npc:6266} znovu",
}
t.guides["forever/class/warlock/felhunter-alliance"] = {
	["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:6120} v {object:32383} pošle k {npc:6251} v {area:392}.",
	["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:6122}, ve sklepě {object:2164} v {object:2101}, pošle k {npc:6251} v {area:392}.",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zpět k {npc:6251} do {area:392}. Když přijmeš, nakreslí vyvolávací kruh a jeho akolyté nad ním kanálují větší kruh: počkej ve věži, dokud nejsou oba hotové. Pak použij {quest:1804} na kruh. Felhunter (level 30, ne elitní) umlčuje a žere manu a po dvou minutách zmizí: měj venku voidwalkera, hned začni DoTy a nech voidwalkera tankovat. Když zemřeš nebo vyhraje, zruš {quest:1795} a vezmi ho znovu od {npc:6251}. Knihu si nech: {npc:6251} si ji vezme zpět.",
	["Back to {npc:6294}"] = "Zpět do {npc:6294}",
	["Felhunter (Alliance)"] = "Felhunter (Aliance)",
	["{item:6997}, in the {object:92423}"] = "{item:6997}, v {object:92423}",
}
t.guides["forever/class/warlock/felhunter-horde"] = {
	["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "Na 30 tě {npc:5675} v {object:36082} pošle k {npc:6251} v {area:392}. Zeppelin z {zone:1420} letí do {zone:1411}. Vezmi jen jeden {quest:3001}: když ti {npc:6251} nic nenabídne, duplikát z deníku zruš.",
	["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "Na 30 tě {npc:5875}, v {object:172960} pod {object:172982}, pošle k {npc:6251} v {area:392}.",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Zpět k {npc:6251} do {area:392}. Když přijmeš, nakreslí vyvolávací kruh a jeho akolyté nad ním kanálují větší kruh: počkej ve věži, dokud nejsou oba hotové. Pak použij {quest:1804} na kruh. Felhunter (level 30, ne elitní) umlčuje a žere manu a po dvou minutách zmizí: měj venku voidwalkera, hned začni DoTy a nech voidwalkera tankovat. Když zemřeš nebo vyhraje, zruš {quest:1795} a vezmi ho znovu od {npc:6251}. Knihu si nech: {npc:6251} si ji vezme zpět.",
	["Back to {npc:6293}"] = "Zpět do {npc:6293}",
	["Felhunter (Horde)"] = "Felhunter (Horda)",
	["{item:6997}, in the {object:92423}"] = "{item:6997}, v {object:92423}",
}
