t.guides["forever/class/warlock/impsys-request"] = {
	["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Hůl, předmět do druhé ruky nebo roucho pro tvoje padesátky; vlastní pochůzka {npc:14470}, ne krok řetězu Dreadsteed.",
	["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Amber Voodoo Feathers: Gasher, {npc:5716}",
	["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:3326} v {object:172960} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:4563} v {object:36082} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "Na 50 tě {npc:5172} v {zone:1455} pošle k {npc:14470} v {zone:1448} s kusem {item:14256}.",
	["Blue Voodoo Feathers: Hukku, Mijan"] = "Blue Voodoo Feathers: Hukku, Mijan",
	["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Vyber {item:20536} (hůl), {item:20534} (do druhé ruky) nebo {item:20530}.",
	["The {area:1417}"] = "{area:1417}",
	["{npc:14470} again"] = "{npc:14470} znovu",
}
t.guides["forever/class/warlock/incubus-alliance"] = {
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Na 20 tě {npc:6120}, trenér warlocků v {object:32383} v {zone:1455}, pošle k {npc:6122} v {zone:1453}. Vezmi {area:2257}.",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Na 20 tě {npc:6122}, ve sklepě {object:2164} v {object:2101}, pošle k {npc:6244} v {zone:1413}: pro Alianci dlouhá cesta. Vezmi loď z {area:150} do Theramore a jdi na západ přes {zone:1445}, nebo loď z {area:35} do {area:392}.",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Na 20: succubus a incubus Foreveru, její mužské dvojče, každý s váčkem duší na tvoje shardy.",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Zpět k {npc:6122} s {quest:1738}. Dá ti {item:6913}: sejdi po schodech za ním dolů do krypty; zhruba v polovině nejnižší chodby vede vlevo boční schodiště do místnosti s fialovým kruhem. Stoupni si do něj a použij jádro. Nejdřív vyvolej voidwalkera a drž succubus (level 20, ne elitní) v kruhu, jinak ji můžou zabít stráže a zabití se nepočítá. Když vyhraje, použij jádro znovu; nech si ho, {npc:6122} si ho vezme zpět.",
	["The {item:190309}"] = "{item:190309}",
	["{item:190309}, upstairs"] = "{item:190309}, nahoře",
}
t.guides["forever/class/warlock/incubus-horde"] = {
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1507} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "Na 20 tě {npc:5875}, v {object:172960} pod {object:172982}, pošle k {npc:5909} pár kroků odsud. Tyhle démony začínají dva trenéři, {npc:5875} tady a {npc:5675} v {zone:1458}, a vzít můžeš jen jeden; tento návod sleduje ten {quest:1507}, který jsi vzal. {npc:5909} nabízí obě větve {zone:1454}: vezmi obě.",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Na 20: succubus a incubus Foreveru, její mužské dvojče, každý s váčkem duší na tvoje shardy.",
	["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Zpět k {npc:5675} s Dalinovým a Cormaným srdcem. Dá ti {item:6286}: jdi dolů do vyvolávacího kruhu pod ním, stoupni si do něj a použij je. Nejdřív vyvolej voidwalkera a drž boj v kruhu, jinak ji můžou zabít stráže a zabití se nepočítá. Když vyhraje, použij srdce znovu; nech si je, {npc:5675} si je vezme zpět.",
	["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Zpět k {npc:5675} se srdci milenců, pak polož {item:190181} do stejného kruhu a poraz incuba, kterého přivolají (level 20, ne elitní; může tě okouzlit). Srdce si nech: {npc:5675} si je vezme zpět.",
	["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Zpět k {npc:5875} s přívěskem. Dá ti {item:6626}: přenes ho přes {object:172960} do stanu {npc:3216}, stoupni si do fialového kruhu a použij ho. Nejdřív vyvolej voidwalkera a nech ho tankovat: succubus (level 20, ne elitní) okouzluje a šlehá; drž na ní svoje DoTy. Když vyhraje, použij přívěsek znovu. Přívěsek si nech: {npc:5875} si ho vezme zpět.",
	["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Zpět k {npc:5875} se šálou, pak použij {item:190232} ve stejném kruhu v Neeruově stanu a poraz incuba, kterého přivolá (level 20, ne elitní), s tankujícím voidwalkerem. Šálu si nech: {npc:5875} si ji vezme zpět.",
	["Corma Villard"] = "Corma Villard",
	["Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "Corma Villard (level 22, ne elitní; ve starších záznamech Comar) se toulá na severu {zone:1437} kousek za {area:881}, vpravo, když sejdeš z mostu. Z {zone:1458} jdi přes {area:287} a {zone:1417}, kde mají mobové 30 a víc. Útok na ni tě označí pro PvP.",
}
t.guides["forever/class/warlock/orb-of-orahil"] = {
	["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Koule do druhé ruky nebo hůl pro tvoje pozdní třicítky, cestou felhounda nebo infernala, podle tvé volby.",
	["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:3326} v {object:172960} pošle k {npc:6266} v {area:392}.",
	["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Na 35 tě {npc:4563} v {object:36082} pošle k {npc:6266} v {area:392}. Zeppelin z {zone:1420} letí do {zone:1411}.",
	["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:461} v {object:2164}, v {object:2101}, pošle k {npc:6266} v {area:392}.",
	["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Na 35 tě {npc:5172} v {zone:1455} pošle k {npc:6266} v {area:392}.",
	["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Zpět k {npc:6266} do věže nad {area:392} s očištěnou koulí. Na cestě felhounda přijmi její poslední quest a čekej vedle ní, dokud nedokončí {item:15108} (neútoč na ni: deník questů tomu říká zabití), pak s ní znovu promluv a vyber kouli do druhé ruky nebo hůl.",
	["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Nejdřív zpět k {npc:6266} do věže nad {area:392} s duchem a drahokamem: z nich následuje její koule.",
	["Choose an acolyte"] = "Vyber akolytu",
	["The {item:15107}"] = "{item:15107}",
	["The {item:15108}"] = "{item:15108}",
}
t.guides["forever/class/warlock/orb-of-soranruk"] = {
	["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Vzácná koule do druhé ruky nebo hůl pro tvoje dvacítky, za úlomky ze dvou dungeonů.",
	["Back to {npc:6247}"] = "Zpět do {npc:6247}",
	["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Vyber {item:6898} do druhé ruky, nebo obouruční {item:15109}.",
}
t.guides["forever/class/warlock/shard-of-the-green-flame"] = {
	["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Vzácný předmět do druhé ruky pro tvoje padesátky od {npc:14469} a {npc:14470} v {zone:1448}, v táboře, který nabízí i An Imp's Request.",
	["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "Na 50 čekají {npc:14469} a jeho imp {npc:14470} na vyvýšenině ve středním {zone:1448} kousek severovýchodně od {area:1997}: když jdeš na sever přes most {area:1765}, stojí kousek od cesty na východ, za pár slizy. {npc:14469} tě pošle k {npc:14470} vedle sebe, který chce tři Flawless Fel Essences ze tří míst.",
	["Back to {npc:14469}"] = "Zpět do {npc:14469}",
	["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "Zpět k {npc:14470}. Dá ti {item:18626}: nech si ho, probudí infernala {npc:14467}.",
}
t.guides["forever/class/warlock/tome-of-sacrifice"] = {
	["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Vzácný předmět do druhé ruky na 60, platba {npc:14463} za chycení {npc:12396} v {zone:1419}.",
	["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "Na 60 čeká {npc:14463} v {area:73}, prohlubni plné démonů na západě {zone:1419}. Scar je plná tvrdě bijících elit: nejdřív si dej Soulstone, pak se při vstupu drž pravé stěny, nebo projeď na mountovi. {npc:14463} ti dá dvě pochůzky naráz.",
	["Back to {npc:14463}"] = "Zpět do {npc:14463}",
}
t.guides["forever/class/warlock/voidwalker-alliance"] = {
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Na 10 tě {npc:6120}, trenér warlocků v {object:32383} v {zone:1455}, pošle k {npc:6122} v {zone:1453}. Vezmi {area:2257} z {object:171524}. Když ti ho {npc:6120} nenabídne, jdi za {npc:6122} i tak: další quest ti dá stejně.",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Na 10 tě {npc:6121}, ve sklepě Lion's Pride Inn v {area:87} (schody dolů jsou v zadní místnosti za řeznickým stolem), pošle k {npc:6122} v {zone:1453}.",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Zpět k {npc:6122}. Dá ti {item:6928}. Kruh se špatně hledá: sejdi po schodech za {npc:6122} dolů; zhruba v polovině nejnižší chodby vede vlevo boční schodiště do místnosti se zářícím fialovým kruhem uprostřed. Stoupni si do něj a použij obojek. Voidwalker (level 10, ne elitní) je pod 30 % zdraví nebezpečný: {spell:14868}, Corruption a {spell:348} s impem na něm, Fear, když se přiblíží. Když tě porazí, použij obojek znovu. Obojek si nech: {npc:6122} si ho vezme zpět.",
}
t.guides["forever/class/warlock/voidwalker-horde"] = {
	["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "Na 10 tě {npc:3294} pošle k {npc:5875}. Stojí venku za kasárnami {area:362}, velkou budovou na východní straně města (ne hostincem), pár kroků od {npc:3172}, trenéra warlocků. {npc:5875} stojí se staršími warlocky v {object:172960}, jeskyni pod {object:172982} v {zone:1454}. Ork nebo Troll, který leveluje v {zone:1420}, může místo toho vzít verzi pro {zone:1458} od {npc:5724} v {area:159} (kroky {zone:1458} níže): můžeš udělat jen jednu z obou.",
	["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "Na 10 tě {npc:5724}, nahoře v {area:2119} v {area:159}, pošle k {npc:5675}: verze pro Nemrtvé a pro Orky a Trolly, kteří levelují v {zone:1420} místo toho, aby vzali quest {npc:5875}. {npc:5675} stojí v {object:36082} v {zone:1458}, u Temple of the Damned.",
	["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "Zpět k {npc:5675}. Dá ti {item:6284}: jdi od něj po schodech dolů k vyvolávacímu kruhu a použij je, zatímco v něm stojíš. S voidwalkerem (level 10, ne elitní) bojuj v kruhu: když odejde, můžou ho zabít městské stráže a zabití se nepočítá. {spell:14868}, Corruption a {spell:348} s tankujícím impem ho složí; pod 30 % bije silněji. Když prohraješ, použij runy znovu. Runy si nech: {npc:5675} si je vezme zpět.",
	["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "Zpět k {npc:5875}. Dá ti {item:7464}: přenes je přes {object:172960} do stanu {npc:3216}, stoupni si do fialového kruhu na jeho podlaze a použij je. Voidwalker (level 10, ne elitní) na 30 % zdraví bije tvrdě a po třech minutách odejde, tak začni hned: {spell:14868}, Corruption a {spell:348}, pošli na něj impa a Fearni ho, když potřebuješ oddech. Když tě porazí nebo odejde, glyfy se nespotřebují: použij je v kruhu znovu. Glyfy si nech: {npc:5875} si je vezme zpět.",
	["{item:6285}, in {object:37098}"] = "{item:6285}, v {object:37098}",
	["{item:6535}, in the {object:58595}"] = "{item:6535}, v {object:58595}",
}
t.guides["forever/class/warrior/brutal-armor"] = {
	["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:3041}, trenér warriorů v {zone:1456}, pošle k {npc:6394} v {area:378}.",
	["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:3354} v {object:172958} pošle k {npc:6394} v {area:378}.",
	["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "Na 20 tě {npc:4595}, trenér warriorů v {zone:1458}, pošle k {npc:6394} v {area:378}.",
	["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "Zpět k {npc:5878} na {area:1699}. {quest:1848} je první kus; pak tě pošle ke třem řemeslníkům, jeden na kus: vezmi všechny tři.",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}, od {npc:6167}",
}
t.guides["forever/class/warrior/fire-hardened-armor"] = {
	["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:5113}, trenér warriorů v {zone:1455}, pošle k {quest:1698} v Redridge.",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:5479}, vedle {npc:5480} v budově trenérů warriorů v {object:2100}, pošle k {quest:1698} v Redridge.",
	["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "Na 20 tě {npc:7315}, trenér warriorů v {zone:1457}, pošle k {quest:1698} v Redridge.",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Zpět k {npc:5413} do {object:28027} pro kroužkovou zbroj. Pak tě pošle ke kováři tvé rasy; kusy dalších dvou kovářů jsou ti otevřené taky: promluv s nimi přímo.",
	["Charred and Galvanized Horns"] = "Charred a Galvanized Horns",
	["Enter the {area:98} and come back; below ground, at the first fork"] = "Vejdi do {area:98} a vrať se; pod zemí, u prvního rozcestí",
	["Fire Hardened Armor"] = "Fire Hardened Armor",
	["The {area:98}"] = "{area:98}",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}, od {npc:6167}",
	["{item:6845}, from {npc:6170}"] = "{item:6845}, od {npc:6170}",
	["{item:6848}, from {quest:1708}"] = "{item:6848}, od {quest:1708}",
}
t.guides["forever/class/warrior/haggards-weapons"] = {
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Na 10 tě {npc:1229}, trenér warriorů v {area:131}, pošle k {quest:1679} v {zone:1455}. Každý warrior Aliance smí vzít jednu ze tří cest, nikdy dvě: jsi na 10 stejně v {zone:1453}? {quest:1638} od {npc:5480} je nejrychlejší postoj (jeden boj v hospodě), s Haggardovou zbraní potom.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Na 10 stojí {npc:252377} s trenéry u západní brány {area:16638}. Kultista {npc:257196} drží štít její rodiny u {area:16629}.",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Na 10 tě {npc:3598}, trenér warriorů v {area:186}, nebo {npc:2151}, který hlídkuje na cestě západně od {area:186}, pošle k {quest:1684} na {area:1660} v {zone:1457}. Každý warrior Aliance smí vzít jednu ze tří cest, nikdy dvě: jsi na 10 stejně v {zone:1453}? {quest:1638} od {npc:5480} naučí stejný postoj po jednom boji v hospodě.",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Na 10 tě {npc:913}, trenér warriorů u hostince v {area:87}, pošle k {npc:6089} v {zone:1453}; nabízí ho i {npc:5480}, trenér warriorů v {object:2100} v {zone:1453}.",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "Zpět na {area:1660}: {npc:4088} ti dá {item:6812}; {npc:6142} pracuje na vzdálené, jižní straně stejné terasy, snadno se přehlédne.",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Zpět k {npc:252377} do {area:16638}. Naučí {spell:71} a dá ti {item:275290}, štít k němu. Cesta {npc:6090} níže pořád dá zbraň, až se dostaneš do {zone:1453}.",
	["Back to {npc:294}"] = "Zpět do {npc:294}",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Zpět k {npc:6114} pro {spell:71}, pak k {quest:1680} u {object:32372} uprostřed {zone:1455}.",
	["Elunite under {area:442}"] = "Elunit pod {area:442}",
	["{item:263993}, from {npc:257196}"] = "{item:263993}, od {npc:257196}",
	["{item:6782}, from {object:85563}"] = "{item:6782}, od {object:85563}",
	["{item:6800}, from {object:85562}"] = "{item:6800}, od {object:85562}",
	["{item:6809}, from the {npc:6133}"] = "{item:6809}, od {npc:6133}",
	["{npc:252377} in {area:16638}"] = "{npc:252377} v {area:16638}",
	["{quest:1679} in {zone:1455}"] = "{quest:1679} v {zone:1455}",
	["{quest:1684} in {zone:1457}"] = "{quest:1684} v {zone:1457}",
}
t.guides["forever/class/warrior/heirloom-weapon"] = {
	["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "Na 10 tě {npc:2131}, trenér warriorů v hostinci {area:159}, pošle k {npc:1496} u hřbitova na západním okraji {area:159}. Tahle cesta a cesta {npc:5810} se vylučují: pokud máš v deníku {quest:1505} nebo {quest:1498}, zruš ho.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Na 10 stojí {npc:252377} s trenéry u západní brány {area:16638}. Kultista {npc:257196} drží štít její rodiny u {area:16629}.",
	["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "Na 10 tě {npc:3063}, trenér warriorů v {area:222}, pošle k {npc:5810} v {zone:1413}. Nabízí ho i {npc:3041} v {zone:1456}.",
	["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "Na 10 tě {npc:3169}, trenér warriorů v kasárnách {area:362}, pošle k {npc:5810} v {zone:1413}. Nabízí ho i Sorek v {object:172958} v {zone:1454}. Každý warrior Hordy smí vzít jednu ze dvou cest, nikdy obě: míříš na 10 stejně do {zone:1420}? {npc:2131} v hostinci {area:159} nabízí tu druhou: jeden boj u hřbitova {area:159} za stejný postoj, pak krypta Agamandů za zděděnou zbraň.",
	["Back to {npc:1500}"] = "Zpět do {npc:1500}",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "Zpět k {npc:252377} do {area:16638}. Naučí {spell:71} a dá ti {item:275290}, štít k němu. Cesta {npc:5810} níže dá později pořád zbraň, až se dostaneš do Kalimdoru.",
	["Back to {npc:5810} under his tree west of {area:379}."] = "Zpět k {npc:5810} pod jeho strom západně od {area:379}.",
	["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger stojí u hřbitova na západním okraji {area:159}. Ork, Troll, Tauren nebo Skyborne, který místo cesty {npc:5810} vzal {quest:1818} od {npc:2131}, je odsud veden přes {area:159}.",
	["The {area:158}"] = "{area:158}",
	["{item:263993}, from {npc:257196}"] = "{item:263993}, od {npc:257196}",
	["{item:6534}, from the {object:58369}"] = "{item:6534}, od {object:58369}",
	["{npc:252377} in {area:16638}"] = "{npc:252377} v {area:16638}",
}
t.guides["forever/class/warrior/quelserrar"] = {
	["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Tankovací meč na 60: kniha z {area:2577}, pak dech {npc:10184} zakalí čepel (meč zatím ve Foreveru mezi předměty není).",
	["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "Zpět k {npc:14368} do Athenaea v Dire Maul West: znovu přes západní dveře s {item:18249} a se skupinou až do knihovny.",
}
