t.guides["forever/class/warrior/whirlwind-weapon"] = {
	["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:3041}, trenér warriorů v {zone:1456}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:3354} v {object:172958} pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:4595}, trenér warriorů v {zone:1458}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:5113}, trenér warriorů v {zone:1455}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Na 30 tě {npc:5479}, vedle {npc:5480} v budově trenérů warriorů v {object:2100}, pošle k {npc:6236} na {area:720} v {zone:1413}.",
	["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "Zpět k {npc:6176}. Přijetím {quest:1713} začne jeho rituál a {quest:1712} se objeví kousek severně od jeho tábora. {quest:1712} je elitní (level 40): doporučuje se skupina; potřebuje skupinu dvou nebo tří kolem levelu 40. Dává nature poškození (pohltí ho {item:6052}), víří a {spell:10101} tě odhodí daleko, zatímco se léčí, když běžíš zpátky: bojuj zády ke svahu nebo skále. {item:6894} padá vždy. Když boj selže, {npc:6176} přestane odpovídat: zruš {quest:1713} a vezmi znovu kvůli novému vyvolání; dřívější předměty znovu potřeba nejsou.",
	["Bloodscalp Tusks"] = "Bloodscalp Tusks",
	["Click {object:89931} with the 24 charms in your bags and {quest:1712} in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the {quest:1714}."] = "S 24 amulety v taškách a {quest:1712} v deníku klikni na {object:89931}. Jeho okno si hned řekne o amulety a nic se nepřijímá: Continue, pak Complete, a dá ti {quest:1714}.",
	["{item:6894}, from {quest:1712}"] = "{item:6894}, od {quest:1712}",
}
