	["Journeyman {skill:762}"] = "Journeyman {skill:762}",
	["{item:18776}, 200g"] = "{item:18776}, 200g",
	["{item:18777}, 200g"] = "{item:18777}, 200g",
	["{item:18778}, 200g"] = "{item:18778}, 200g",
	["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} prodává ostatní barvy (ve klientu Forever po 200g). Kup si, kterou chceš, nebo žádnou, pokud se ti líbí mount, který jsi dostal.",
	["{npc:4732}, riding trainer"] = "{npc:4732}, trenér jízdy",
	["{spell:824} for other races"] = "{spell:824} pro ostatní rasy",
}
