t.guides["forever/collectibles/mounts/neutral/warlock-dreadsteed"] = {
	["At 60 {npc:5520}, the demon trainer in the {object:2164}, sends you to {quest:7562} in the {zone:1428}."] = "Na 60 tě {npc:5520}, trenér démonů v {object:2164}, pošle k {quest:7562} v {zone:1428}.",
	["At 60 {npc:5753}, the demon trainer in the {object:36082}, sends you to {quest:7562} in the {zone:1428}."] = "Na 60 tě {npc:5753}, trenér démonů v {object:36082}, pošle k {quest:7562} v {zone:1428}.",
	["At 60 {npc:5815}, the demon trainer in the {object:172960}, sends you to {quest:7562} in the {zone:1428}."] = "Na 60 tě {npc:5815}, trenér démonů v {object:172960}, pošle k {quest:7562} v {zone:1428}.",
	["At 60 {npc:6382}, the demon trainer in {zone:1455}, sends you to {quest:7562} in the {zone:1428}."] = "Na 60 tě {npc:6382}, trenér démonů v {zone:1455}, pošle k {quest:7562} v {zone:1428}.",
	["Back to {npc:14436}: he gives you the {item:18591} for {npc:14437} beside him. Then {npc:14436} asks for the bell, the wheel and the candle, and {npc:14437} sends you to {quest:7623} in {area:1763}: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after {npc:14523}, and a spare in case one runs out) and bring 150 gold for the stardust."] = "Zpět k {npc:14436}: dá ti {item:18591} pro {npc:14437} vedle sebe. Pak {npc:14436} chce zvon, kolo a svíci a {npc:14437} tě pošle k {quest:7623} do {area:1763}: kup u něj na tu cestu tři Shadowy Potions (po 6 zlatých: jeden na vstup, jeden po {npc:14523} a jeden do rezervy, kdyby některý vyprchal) a přines 150 zlatých na hvězdný prach.",
	["Back to {npc:14437} with the stardust; with the {quest:7630} also done he gives you the {item:18688} for the {area:2057}. Put a group of five together now: a party, not a raid group."] = "Zpět k {npc:14437} s hvězdným prachem; s hotovým i {quest:7630} ti dá {item:18688} do {area:2057}. Teď dej dohromady skupinu pěti: partu, ne raidovou skupinu.",
	["Back to {npc:14437}, then {npc:14436} hands you his instructions. Buy {item:18663} (150 gold), the {item:18629} (50) and the {item:18670} (50) from {npc:14437}; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards."] = "Zpět k {npc:14437}, pak ti {npc:14436} dá svoje pokyny. Kup od {npc:14437} {item:18663} (150 zlatých), {item:18629} (50) a {item:18670} (50); může přinést i svoje kamarád warlock, který je má. Každý další warlock, který bude dobíjet uzly, potřebuje vlastní Lodestone. Nos 15 a víc Soul Shardů.",
	["Every owlbeast of {zone:1452} (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. {area:2250}, in the north-east, and the {area:2242}'s surroundings are packed with them, and they respawn in five and a half minutes."] = "Každý sovodlak v {zone:1452} (level 53–58, žádný elitní) dropne krev zhruba jednou ze tří: asi devadesát zabití na třicet. {area:2250} na severovýchodě a okolí {area:2242} jich je plné a obnovují se za pět a půl minuty.",
	["The {area:2057}"] = "{area:2057}",
	["{item:12360}: the Auction House"] = "{item:12360}: aukce",
	["{item:14344}: the Auction House"] = "{item:14344}: aukce",
	["{item:18629}, 50 gold"] = "{item:18629}, 50 zlata",
	["{item:18663}, 150 gold"] = "{item:18663}, 150 zlata",
