	["At 40 {npc:3326}, in the {object:172960}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Na 40 tě {npc:3326} v {object:172960} pošle k {npc:6251} v {area:392}. Nenabízí quest? Nejdřív dokonči řetěz felhuntera: hráči hlásí, že mount přichází po něm.",
	["At 40 {npc:4563}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}; {area:392} is a short flight from {zone:1454}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Na 40 tě {npc:4563} v {object:36082} pošle k {npc:6251} v {area:392}. Zeppelin z {zone:1420} letí do {zone:1411}; {area:392} je kousek letu z {zone:1454}. Nenabízí quest? Nejdřív dokonči řetěz felhuntera: hráči hlásí, že mount přichází po něm.",
	["At 40 {npc:461}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Na 40 tě {npc:461}, ve sklepě {object:2164} v {object:2101}, pošle k {npc:6251} v {area:392}. Nenabízí quest? Nejdřív dokonči řetěz felhuntera: hráči hlásí, že mount přichází po něm.",
	["At 40 {npc:5172}, by the warlock trainers in {zone:1455}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Na 40 tě {npc:5172}, u trenérů warlocků v {zone:1455}, pošle k {npc:6251} v {area:392}. Nenabízí quest? Nejdřív dokonči řetěz felhuntera: hráči hlásí, že mount přichází po něm.",
