t.guides["forever/collectibles/pets/excitable-slime"] = {
	["Buy {item:278265} from {npc:4612} in the {zone:1458} canals first (25 copper for a stack of 5): you hand it in as soon as the slime offers its quest."] = "Nejdřív kup {item:278265} od {npc:4612} v kanálech {zone:1458} (25 měďáků za balík 5): odevzdáš ho, jakmile sliz nabídne svůj quest.",
	["Find an {npc:269452}, a little critter in the canal water beside {npc:4612}, target it and /dance at it, again and again, until it dances back and offers {quest:97583}; this takes many tries. Hand in the sludge right away. If the slime seems tired, /dance with it again before you hand in."] = "Najdi {npc:269452}, malého tvorečka ve vodě kanálu vedle {npc:4612}, zaměř ho a /dance na něj znovu a znovu, dokud ti tanec neoplatí a nenabídne {quest:97583}; chce to hodně pokusů. Sliz hned odevzdej. Pokud se sliz zdá unavený, zatancuj si s ním /dance znovu, než ho odevzdáš.",
}
