t.guides["forever/collectibles/pets/hyacinth-macaw"] = {
	["Bloodsail camp, the {area:43}"] = "Tábor Bloodsail, {area:43}",
	["Bloodsail pirates"] = "Piráti Bloodsail",
	["Every Bloodsail pirate on the Stranglethorn coast (level 39-45) can drop it, but only about once in 5,000 kills; the Swabbies on the ships off the southern tip, about once in 2,500. That is a grind of many hours, so most players kill pirates while doing something else there, or buy the cage on the Auction House. The waypoint is the Swashbucklers' and Warlocks' camp on the {area:43}, south of {area:35}. Every pirate kill also lowers your Bloodsail Buccaneers standing."] = "Může ho dropnout každý pirát Bloodsail na pobřeží Stranglethornu (level 39–45), ale jen zhruba jednou za 5 000 zabití; Swabbies na lodích u jižního cípu zhruba jednou za 2 500. To je grind na mnoho hodin, takže většina hráčů zabíjí piráty, zatímco tam dělá něco jiného, nebo klec koupí v aukci. Bod trasy je tábor Swashbucklers a Warlocks na {area:43}, jižně od {area:35}. Každé zabití piráta navíc sníží reputaci u Bloodsail Buccaneers.",
}
