	["Flight path here: {area:69} ({npc:931})."] = "Letová trasa tady: {area:69} ({npc:931}).",
	["Fly from {area:144} to {zone:1453} if you have its flight path; otherwise ride back to {zone:1455} and take the {area:2257}. Walk west out of {zone:1429} past the {area:120} into {zone:1436}."] = "Leť z {area:144} do {zone:1453}, pokud máš jeho letovou trasu; jinak jeď zpátky do {zone:1455} a vezmi {area:2257}. Jdi na západ ze {zone:1429} kolem {area:120} do {zone:1436}.",
