t.guides["forever/horde/02-the-barrens"] = {
	["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Pomoz {npc:261366}: zůstaň u něj, až {npc:261367} a mariňáci z {area:21} vylezou na hřeben",
	["At the {area:2362}"] = "U {area:2362}",
	["At the {object:147538}: summons {quest:882}"] = "U {object:147538}: přivolá {quest:882}",
	["Back down to {npc:11857}."] = "Zpět dolů k {npc:11857}.",
	["Back east over the bridge and up the trail to {npc:5900}'s shrine again. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Zpět na východ přes most a po stezce znovu nahoru ke svatyni {npc:5900}. {npc:5900} vyrobí z dehtu a váčku {item:6636}. Použij ho u pánve vedle něj, odhal {npc:5893}, zabij ho kvůli {item:6655} a pak dej uhlík do pánve.",
	["Back north along the beach to {area:392}."] = "Zpět na sever po pláži do {area:392}.",
	["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "Zpět na sever do táborů Bristleback. Kterýkoli Bristleback může dropnout kel pro {npc:3432}, tak je sbírej, zatímco zabíjíš tyhle pro {npc:3430}. Jeden {item:5075} si nech.",
	["Back north into {area:378} before the antennae fade: {npc:6394} is inside."] = "Zpět na sever do {area:378}, než tykadla zvadnou: {npc:6394} je uvnitř.",
	["Back north into {area:378} on the way to the Crossroads: Jorn takes the thunderhawk wings."] = "Zpět na sever do {area:378} cestou do Crossroads: Jorn vezme křídla thunderhawků.",
	["Back out of the caverns and up to the cave above the entrance."] = "Zpět ven z jeskyní a nahoru do jeskyně nad vchodem.",
	["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them. Careful: Razormane Flesheaters and Berserkers (18-19) are elites in the camp's north-east, near {npc:3438} and the supply crates, and {npc:267307} (20, elite) lies in the cave under {area:1699} beside them: pull {npc:3438} and the quilboar away from them one at a time, and leave the cave alone unless you are in a group."] = "Zpět do tábora Razormane. Geomancers a Defenders drží jeho východní polovinu; {npc:3438} chodí mezi nimi. Pozor: Razormane Flesheaters a Berserkers (18–19) jsou elity na severovýchodě tábora, blízko {npc:3438} a beden se zásobami, a {npc:267307} (20, elitní) leží v jeskyni pod {area:1699} vedle nich: odlákej {npc:3438} a quilboary od nich po jednom a jeskyni nech být, pokud nejsi ve skupině.",
	["Bristleback Geomancers"] = "Bristleback Geomancers",
	["Bristleback camps"] = "Tábory Bristleback",
	["Cast {spell:18960}"] = "Sešli {spell:18960}",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} stojí nahoře ve své budově v {area:2361}: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Cure {npc:12296}"] = "Vyléč {npc:12296}",
	["Dogran is chained up in the quilboar camp west of the road."] = "Dogran je přikovaný v táboře quilboarů západně od cesty.",
	["Down the {area:458} to {area:378} again."] = "Znovu dolů po {area:458} do {area:378}.",
	["East along the road to {npc:4049} and {npc:11857}'s camp, on the way back out of Stonetalon."] = "Na východ po cestě do tábora {npc:4049} a {npc:11857}, cestou zpět ze Stonetalonu.",
	["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "Na východ od {npc:261366} směrem k {area:382}: {npc:9316} stojí v táboře na cestě severně od Crossroads.",
	["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints."] = "Východně od Ziz Venture Company holoseče kácí {area:461}; plány nese jeden z Operators.",
	["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, and {npc:3467} (16) stands beside them."] = "Na východ na pláž, na jižní konec pirátského tábora: bedna s botami a křehká bedna s čočkou jsou tam a vedle nich stojí {npc:3467} (16).",
	["Fill the {item:7766} at the quilboar watering hole"] = "Naplň {item:7766} u napajedla quilboarů",
	["Finish the Plainstrider Beaks"] = "Dokonči Plainstrider Beaks",
	["Finish the Raptor Heads"] = "Dokonči Raptor Heads",
	["Fly from the Crossroads to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}. {spell:499} and {spell:526} follow in {zone:1450} on the same trip, then {npc:11798} flies you back here and on to {area:392}."] = "Leť z Crossroads do {area:1638} a vytrénuj si ranky levelu 20: {npc:3033} je na {area:1639}. {spell:499} a {spell:526} následují ve {zone:1450} na stejné cestě, pak tě {npc:11798} odveze letem zpátky sem a dál do {area:392}.",
	["Fly from the Crossroads to {area:1638}. {quest:853} waits in the {area:2197}, the cave under {area:1640}: hand in the spores there first, while their time runs. Then {npc:3033} trains you on {area:1639}."] = "Leť z Crossroads do {area:1638}. {quest:853} čeká v {area:2197}, jeskyni pod {area:1640}: odevzdej tam výtrusy jako první, dokud jim běží čas. Pak tě {npc:3033} vytrénuje na {area:1639}.",
