t.guides["forever/horde/04-the-barrens"] = {
	["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "Pár kroků východně od stromu {npc:14242} je malý tábor: dva Encroaching Soldiers a {npc:268623} pro Logmara. {npc:268623} je elitní: doporučuje se skupina.",
	["Back down the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Zpět dolů po {area:1076} k chýši {npc:4201}, pak na východ po cestě k {area:461}: {npc:4074} hlídkuje na cestě kousek východně od rozcestí, {npc:4073} na svazích dál na severovýchod pod skalou. Oba jsou osamělí shredder roboti; toulají se, tak jdi po cestě, dokud je nepotkáš.",
	["Back west to {npc:4201}' hut, on the way down to {area:2539}."] = "Zpět na západ k chýši {npc:4201}, cestou dolů do {area:2539}.",
