t.guides["forever/horde/06-hillsbrad-foothills"] = {
	["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Po vrácení Mission: Possible But Not Probable Shenthulovi přines {quest:2479} k {npc:2391} v {area:272}. Zůstaň vedle něj, dokud se nesplní cíl vaření, pak odevzdej navazující quest a nauč se Poisons. Dokonči ho, i když je Zanzilův jed už odstraněný; samotné odstranění debuffu dovednost nenaučí.",
	["Back north up the road to the {area:228}: {npc:1938} stands just north of Allister."] = "Zpět na sever po cestě k {area:228}: {npc:1938} stojí kousek severně od Allistera.",
	["Back to the Crossroads"] = "Zpět do Crossroads",
	["Bears, creepers and lions"] = "Medvědi, plazivci a lvi",
	["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Pozor: Když zaútočíš na jednoho lva, přijdou mu na pomoc lvi kolem a přidat se můžou i Vicious Black Bears, kteří s nimi sdílejí pole.",
	["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. Než se zastavíš u {npc:11802} v {area:2361}, spoj obě poloviny přívěsku u {area:2362} na severozápadním břehu jezera. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Darthalia's next {quest:528} and Lydon's Elixir of Agony are for the next visit, at about 30."] = "Darthaliin další {quest:528} a Lydonův Elixir of Agony jsou na další návštěvu, kolem 30.",
	["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues, Watchmen and Shadow Mages hold the camps along the way; the Shadow Mages carry Lydon's Vials of Innocent Blood."] = "Drull a {npc:2238} jsou přikovaní v budovách na nádvoří {area:275}. Jejich zámky potřebují klíče: {npc:2427} nese {item:3467} a {npc:2428} {item:3499}, oba v pevnosti. Zabij je a pak otevři oba zámky.\nZ {area:272} jdi na jihovýchod do kopců cestou k {area:275}. Tábory po cestě drží Rogues, Watchmen a Shadow Mages; Shadow Mages nesou Lydonovy Vials of Innocent Blood.",
	["Drull's ball and chain"] = "Drullova koule s řetězem",
	["Fill the {item:7768} at the {object:107045} beside the inn"] = "Naplň {item:7768} u {object:107045} vedle hostince",
	["{area:272} flight master"] = "letový mistr {area:272}",
	["{area:275}: kill these as you meet them"] = "{area:275}: zabíjej je, jak na ně narazíš",
	["{area:286}: kill these as you meet them"] = "{area:286}: zabíjej je, jak na ně narazíš",
	["{npc:1952}, below ground"] = "{npc:1952}, pod zemí",
	["{npc:2216}, inside"] = "{npc:2216}, uvnitř",
	["{npc:2229}, inside"] = "{npc:2229}, uvnitř",
	["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} chodí po okolí: hledej uvnitř kruhu na mapě",
	["{npc:4606} stands in the {object:36070}."] = "{npc:4606} stojí v {object:36070}.",
	["{quest:1014}: the {item:5442}"] = "{quest:1014}: {item:5442}",
}
t.guides["forever/horde/07-ashenvale"] = {
	["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "Kousek severně od táborů Galaků vede jeskyně {area:1557} dolů do nejhlubší komory, kde hoří {object:20807}. Použij na něj {item:5868} a hned lootni {item:5869}: plamen zůstane zhasnutý jen krátce, a když se znovu rozhoří, lahvička je pryč. Pak na východ k mesě {npc:2986}.\nPozor: u pánve stojí dva Galak Flame Guards (30) a jeskyní chodí kentauří strážce: než plamen uhasíš, odlákej je po jednom.",
	["Back east past {area:2237} to {area:484}."] = "Zpět na východ kolem {area:2237} do {area:484}.",
	["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Zpět na jih do tábora, pak nahoru do {zone:1456} na let do {area:378}.",
	["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "Zpět na jihozápad do {area:421}. {npc:12759}, zkažený vodní elementál, se vznáší kolem ostrova jezera a pod vodou. {item:16408} dropne, jen když máš {quest:25} od {npc:12737}; začíná quest pro Splintertree.",
	["Back to {npc:12867} at the lumber camp, on the road north to Splintertree."] = "Zpět k {npc:12867} do dřevorubeckého tábora, na cestě na sever do Splintertree.",
	["Back west to Zoram'gar from Thistlefur before heading east for good."] = "Zpět na západ do Zoram'garu z Thistlefuru, než se natrvalo vydáš na východ.",
	["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Befouled Water Elementals se vznášejí kolem břehů jezera; altánek stojí na ostrově s výhledem na stanoviště Aliance.",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["East along the road from Seereth's camp to the Crossroads' wind rider master, and fly to {area:2897}. If your hearthstone is ready, hearth to {area:378} and fly from there instead."] = "Na východ po cestě ze Seerethova tábora k mistrovi wyvern v Crossroads a leť do {area:2897}. Pokud máš připravený Hearthstone, hearthni do {area:378} a leť odtamtud.",
	["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "Východně od Zoram'garu plní vesnici a kopce kolem jejich doupěte furbolgové Thistlefur.\nPozor: Shaman na 15 % zdraví nebo méně uteče hledat pomoc, což může natáhnout další furbolgy.",
	["Felmusk satyrs"] = "Satyrové Felmusk",
