t.guides["forever/horde/30-40/03-stranglethorn-vale"] = {
	["Back north to the camp."] = "Zpět na sever do tábora.",
	["Back to {area:1637}"] = "Zpět do {area:1637}",
	["Back to {object:3202}."] = "Zpět k {object:3202}.",
	["Boat to {area:35}"] = "Loď do {area:35}",
	["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "Dizzywigovy díly jdou zpět Kravelovi do {area:439}, mimo trasu: nech je být.",
	["Dustwallow's quests are 35-38. Still below 36 after {object:3202}'s hand-ins? The Snapjaw Crocolisks (35-36) line the river just east of the camp, below the Mosh'Ogg hills: kill them until level 36, then walk back to the zeppelin tower. Leave the Mosh'Ogg ogres (36-37) above them alone."] = "Questy Dustwallow mají 35–38. Pořád pod 36 po odevzdáních v {object:3202}? Snapjaw Crocolisks (35–36) lemují řeku kousek východně od tábora, pod kopci Mosh'Ogg: zabíjej je do levelu 36, pak se vrať k věži zeppelinů. Zlobry Mosh'Ogg (36–37) nad nimi nech být.",
	["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them; the 38s can be two over you: pull them one at a time and leave the Elders alone."] = "Východně od kopců Mosh'Ogg slídí Shadowmaw Panthers (37–38) v džungli směrem k jezeru; po stejném území se toulají Stranglethorn Tigresses a občas dropnou nepoškozený tesák. Snapjaw Crocolisks lemují řeku kousek západně od džungle; jejich kůže si nech pro {npc:2495}. Pozor: Shadowmaw Panthers (level 37–38) a Elder Shadowmaw Panthers (level 42–43) jsou mimo boj ve Sneak, takže zůstanou skrytí, dokud nepřijdeš blízko; ty 38 můžou být o dva nad tebou: tahej je po jednom a Elders nech být.",
	["Elder Stranglethorn Tigers"] = "Elder Stranglethorn Tigers",
	["Escort {npc:268992} out of the ruins and keep him alive: Lozgil takes the news once he is safe."] = "Eskortuj {npc:268992} ven z ruin a udrž ho naživu: Lozgil vezme zprávu, až bude v bezpečí.",
