t.guides["forever/horde/30-40/05-arathi-highlands"] = {
	["Back east along the foothills to {area:272}: everything from the first loop is handed in inside the inn."] = "Zpět na východ po úpatí do {area:272}: všechno z prvního kola se odevzdává v hostinci.",
	["Back north to {area:321}: the doctor stands at the south gate."] = "Zpět na sever do {area:321}: doktor stojí u jižní brány.",
	["Back north-east to {area:321}."] = "Zpět na severovýchod do {area:321}.",
	["Back to {area:272}"] = "Zpět do {area:272}",
	["Back to {area:321}"] = "Zpět do {area:321}",
	["Below ground"] = "Pod zemí",
	["Boulderfist camp"] = "Tábor Boulderfist",
	["Boulderfist quests for a group"] = "Questy Boulderfist pro skupinu",
	["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Každý {object:180105} je kruh menhirů; klíč leží na kameni v jeho středu. Východní kruh je v kopcích severozápadně od {area:321}.\nPozor: Každý středový kámen hlídají asi tři elementálové kolem levelu 39, kteří zaútočí naráz, když na kámen klikneš, aniž bys je vybil: Burning Exiles na West, Thundering Exiles na Outer, Cresting Exiles na East.",
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Eskortuj profesora na kopec do jeskyně nad zátokou a hlídej ho, zatímco pracuje. Přepadnou ho tam dva vodní elementálové levelu 40, imunní vůči mrazu. Drž je u ústí jeskyně, daleko od něj: když se boj odehraje v jeskyni, přidá se místo práce a přicházejí další elementálové.",
	["Find where {quest:503} is held, on the top floor"] = "Najdi, kde drží {quest:503}, v nejvyšším patře",
	["Fleshstalker raptors"] = "Raptoři Fleshstalker",
