t.guides["forever/horde/40-50/01b-riverglades"] = {
	["About 70 quests in Forever's new zone, from the fort of {area:16743}."] = "Asi 70 questů v nové zóně Foreveru, z pevnosti {area:16743}.",
	["Across the {area:3} to {area:340}, the Horde fortress built into the cliffs at the zone's western edge: its flight master stands at the foot of the fortress."] = "Přes {area:3} do {area:340}, pevnosti Hordy vestavěné do útesů na západním okraji zóny: její letový mistr stojí u paty pevnosti.",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Zpět na sever po břehu: cestou k crawlerům odevzdej v docích murloky a kůži.",
	["Back through the port"] = "Zpět přes přístav",
	["Back to the port, from the north pier west through the docks."] = "Zpět do přístavu, ze severního mola na západ přes doky.",
	["Back to the port."] = "Zpět do přístavu.",
	["Back to {area:16743} from the port, where your Hearthstone is set. {npc:256418} in the middle of the fort: {npc:255829}'s word sends him looking for {npc:258570}, his warrior in the west."] = "Zpět do {area:16743} z přístavu, kde máš nastavený Hearthstone. {npc:256418} uprostřed pevnosti: slovo {npc:255829} ho pošle hledat {npc:258570}, jeho válečníka na západě.",
	["Back to {area:16743}, where your Hearthstone is set: {npc:263190} on the fort's west side first, then {npc:256418}, {npc:256655} by the cook fire, {npc:256657} and {npc:258031} on your way east through the fort."] = "Zpět do {area:16743}, kde máš nastavený Hearthstone: nejdřív {npc:263190} na západní straně pevnosti, pak {npc:256418}, {npc:256655} u kuchařského ohně, {npc:256657} a {npc:258031} cestou na východ přes pevnost.",
	["Back to {npc:255829} on his hill. {npc:257062} runs the {quest:94668} just below it."] = "Zpět k {npc:255829} na jeho kopec. {npc:257062} vede {quest:94668} hned pod ním.",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Bonegnaw"] = "Bonegnaw",
	["Careful: {npc:256899}, the two-headed ogre at the western edge of {area:16723}, is an elite (level 41): grouping up is advised under 43. Clear the cultists around him first and come in with full health and mana: recorded players of 42-43 killed him alone. {npc:255829}'s quests in {area:16726} wait on this one: skip him and {quest:95420}, the {area:16726} quests and {npc:258570}'s camp in the west go with him (about 21,000 XP); the guide then leaves them out."] = "Pozor: {npc:256899}, dvouhlavý zlobr na západním okraji {area:16723}, je elitní (level 41): pod 43 se doporučuje skupina. Nejdřív vybij kultisty kolem něj a přijď s plným zdravím a manou: zaznamenaní hráči 42–43 ho zabili sami. Questy {npc:255829} v {area:16726} na něm závisí: když ho přeskočíš, s ním odpadne {quest:95420}, questy {area:16726} a tábor {npc:258570} na západě (asi 21 000 XP); návod je pak vynechá.",
	["Down to the port."] = "Dolů do přístavu.",
	["Each bout is a fight in the ring below {npc:255829}'s hill against an elite: Buzzbeak (41), Kronk and Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) and {npc:257059} (45). Come in rested, with full health and mana; if a bout goes wrong, {npc:257062} offers it again."] = "Každé kolo je souboj v ringu pod kopcem {npc:255829} proti elitě: Buzzbeak (41), Kronk a Bonegnaw (42), {npc:258626} (43), Snufflesnout (44) a {npc:257059} (45). Přijď odpočatý, s plným zdravím a manou; když se kolo pokazí, {npc:257062} ho nabídne znovu.",
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Na východ podél útesů na vzdálený konec tábora pirátů: {npc:260390} čeká u vody, {npc:260391} vedle něj.",
	["East back to {area:16743}."] = "Na východ zpět do {area:16743}.",
	["East back to {area:16743}: {npc:260931}'s word goes to {npc:256710}, and {npc:256710}'s to {npc:255829}, the ogres' chieftain."] = "Na východ zpět do {area:16743}: slovo {npc:260931} jde k {npc:256710} a slovo {npc:256710} k {npc:255829}, náčelníkovi zlobrů.",
	["East of Rog'mar, on the hill above the road to {area:16727}: {npc:263367} has his workshop there. The gas vents are in the marsh south-west of it, on your first hunt for {npc:258031}."] = "Východně od Rog'maru, na kopci nad cestou do {area:16727}: má tam dílnu {npc:263367}. Plynové průduchy jsou v bažině jihozápadně od ní, při tvém prvním lovu pro {npc:258031}.",
	["East to {area:16735}, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. {area:16744}, the Alliance outpost on the road, has guards: pass south of it.\nCareful: {npc:263380}, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."] = "Na východ do {area:16735}, farmy Aliance u řeky: na polích pracují pomocníci a vaky s krmivem leží u stodol. {area:16744}, stanoviště Aliance na cestě, má stráže: projdi jižně od něj.\nPozor: {npc:263380}, elita (level 42), loví podél řeky u farmy: hlídej břeh.",
	["Finish the {item:268632}"] = "Dokonči {item:268632}",
	["Fly to {area:340}"] = "Leť do {area:340}",
	["Fly to {area:484}"] = "Leť do {area:484}",
	["Into the {area:16591}"] = "Do {area:16591}",
	["The {area:16737}"] = "{area:16737}",
	["{area:75} flight master"] = "letový mistr {area:75}",
	["{item:269257}, from {npc:260973}"] = "{item:269257}, od {npc:260973}",
	["{npc:256728}'s camp"] = "tábor {npc:256728}",
	["{quest:93976}: for {npc:255897} in {area:16727}, keep it"] = "{quest:93976}: pro {npc:255897} v {area:16727}, nech si ho",
	["{quest:94727}: for {npc:260931} in {area:16723}"] = "{quest:94727}: pro {npc:260931} v {area:16723}",
	["{quest:95062}: for {npc:256418} in {area:16743}"] = "{quest:95062}: pro {npc:256418} v {area:16743}",
	["{quest:95418}: for {npc:256710} in {area:16743}"] = "{quest:95418}: pro {npc:256710} v {area:16743}",
	["{quest:95420}: for {npc:255829} in {area:16726}"] = "{quest:95420}: pro {npc:255829} v {area:16726}",
}
