	["Below ground"] = "Pod zemí",
	["Coming from Stranglethorn, you carry these already. Starting here: {npc:5591} stands inside {area:75}'s great hall and {npc:1443} on its top floor."] = "Ze Stranglethornu je už neseš. Pokud začínáš tady: {npc:5591} stojí ve velké síni {area:75} a {npc:1443} v jejím nejvyšším patře.",
	["Dragon caves"] = "Dračí jeskyně",
	["East through the {area:511}: the Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Na východ přes {area:511}: zvědové a popelaví ocasové Firemane se toulají po jeho severním okraji s mláďaty a dráčaty Searing; scalebanes hlídají dračí jeskyně dál na jihovýchod. Šňupací tabák, grog a pokladnička Mok'Morokka leží v táborech drakonidů.",
