t.guides["forever/horde/40-50/04-tanaris"] = {
	["Back east to Fizzledowser on the west side of {area:976}; {npc:7771} is south from there."] = "Zpět na východ k Fizzledowserovi na západní straně {area:976}; {npc:7771} je odtud na jih.",
	["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "Zpět na sever, kousek jižně od {area:976}, použij teď {item:8524}: začne dvouhodinový časovač. Blisterpaw Hyenas, Glasshide Basilisks a Scorpid Hunters sdílejí zdejší duny. Každý může dropnout netestovaný vzorek: použij ho a buď projde jako přijatelný, nebo se ztratí. Zabíjej, dokud nemáš osm od každého.",
	["Below ground"] = "Pod zemí",
	["Below ground: the plans, on the {area:1443}'s upper ledge"] = "Pod zemí: plány, na horní římse {area:1443}",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Careful: Shadow Mages (level 42-43) call a Voidwalker while out of combat and attack with Immolate and {spell:686}. Thieves can Disarm you, Rogues move around in Sneak, and Assassins use Execute once you are at 20% health or less."] = "Pozor: Shadow Mages (level 42–43) mimo boj vyvolávají Voidwalkera a útočí Immolate a {spell:686}. Thieves tě můžou odzbrojit, Rogues se pohybují ve Sneak a Assassins používají Execute, jakmile máš 20 % zdraví nebo méně.",
	["Dark Iron Lookouts"] = "Dark Iron Lookouts",
	["Dig up the {quest:3161} ornaments around the {area:1938} and north of the {area:983}. Leave the ogres for now: {npc:12046} is 49 and the Brutes 46-48; the {area:983} comes at the end of 40-50/06, at about 52."] = "Vykopej ozdoby {quest:3161} kolem {area:1938} a severně od {area:983}. Zlobry zatím nech: {npc:12046} má 49 a Brutes 46–48; {area:983} přijde na konci 40-50/06, kolem 52.",
	["Fly to {area:976}"] = "Leť do {area:976}",
	["Into {zone:1427}"] = "Do {zone:1427}",
	["The {area:247}"] = "{area:247}",
	["the {object:173265}"] = "{object:173265}",
	["{area:1099} flight master"] = "letový mistr {area:1099}",
	["{item:11818}, a rare drop"] = "{item:11818}, vzácný drop",
	["{item:8623}, a rare drop"] = "{item:8623}, vzácný drop",
	["{npc:5594}, inside"] = "{npc:5594}, uvnitř",
	["{quest:3362}: kill these as you meet them"] = "{quest:3362}: zabíjej je, jak na ně narazíš",
	["{zone:1427}: kill these as you meet them"] = "{zone:1427}: zabíjej je, jak na ně narazíš",
}
