t.guides["forever/horde/50-60/01-un-goro-crater"] = {
	["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "Pár kroků zpět na západ na Felstone Farm, první farmu podél cesty; {npc:10778} čeká v domě.",
	["Back north-east to {area:251}."] = "Zpět na severovýchod do {area:251}.",
	["Back to {area:976}"] = "Zpět do {area:976}",
	["Below ground"] = "Pod zemí",
	["Boat to {area:16727}"] = "Loď do {area:16727}",
	["Bridge into {area:254}"] = "Most do {area:254}",
	["Careful: Gorishi Workers may call for help within 25 yd when below 45% health; silithids cast {spell:8137} and Tunnelers and the Hive Guard use {spell:14120}."] = "Pozor: Gorishi Workers můžou pod 45 % zdraví volat o pomoc do 25 yd; silithidi sesílají {spell:8137} a Tunnelers a Hive Guard používají {spell:14120}.",
	["Careful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd. The Hive Guards (54) and the Queen stand inside the hive: work the Workers and Wasps outside it."] = "Pozor: Gorishi Workers pod 45 % zdraví mají 50% šanci zavolat o pomoc spojence do 25 yd. Hive Guards (54) a Queen stojí uvnitř úlu: dělej Workers a Wasps venku.",
	["Careful: There are many ravasaurs roaming the area, so you can easily pull several at the same time."] = "Pozor: V okolí se toulá hodně ravasaurů, takže snadno natáhneš víc naráz.",
	["Cross the south of the crater to the pylon on the western cliffs."] = "Přejdi jih kráteru k pylonu na západních útesech.",
	["Eastern Pylon"] = "Východní pylon",
	["Fly to {area:1497}"] = "Leť do {area:1497}",
