t.guides["forever/horde/50-60/02-felwood"] = {
	["Back north to {area:1763}. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "Zpět na sever do {area:1763}. Naplň Gretinu čutoru u zkažené moonwell uprostřed jižního tábora.",
	["Below ground"] = "Pod zemí",
	["Careful: Den Watchers are level 53-54 and the Deadwood Avengers 54-55; they call nearby allies within 25 yd once below 50% health and run off for help below 15%.\nKeep killing them until one drops a {quest:8470}, about one kill in thirty, then right-click it: {npc:11558} in {area:1769} takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 59."] = "Pozor: Den Watchers mají level 53–54 a Deadwood Avengers 54–55; pod 50 % zdraví volají spojence do 25 yd a pod 15 % utíkají pro pomoc.\nZabíjej je, dokud jeden nedropne {quest:8470}, zhruba jedno zabití z třiceti, pak na něj klikni pravým: {npc:11558} v {area:1769} ho vezme, jakmile jsou k tobě Timbermaw Neutral, teď, pokud už jsou, nebo až poslední návod na 59 znovu mine jeskyni.",
	["Class trainer"] = "Trenér povolání",
	["Derrington's watchtowers and Vandis' cauldron are done on a later visit: keep them."] = "Derringtonovy strážní věže a Vandisův kotel se dělají při pozdější návštěvě: nech si je.",
	["Diseased Wolves"] = "Diseased Wolves",
	["Druid trainer"] = "Trenér druidů",
	["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Východně od Bloodvenom Post, údolí plné kráterů, kde se toulají Entropic Beasts a Horrors. Zabij od každého dva, pak dojdi ke každému ze tří kráterů s fel vodou.",
	["Fly to {area:431}"] = "Leť do {area:431}",
	["Level 55"] = "Level 55",
	["grind on {npc:7157}"] = "grinduj na {npc:7157}",
	["grind on {npc:8957}"] = "grinduj na {npc:8957}",
	["{npc:246152} in {zone:1420}; {zone:1454} has no paladin trainer"] = "{npc:246152} v {zone:1420}; {zone:1454} nemá trenéra paladinů",
	["{npc:9996}: the {quest:86612}"] = "{npc:9996}: {quest:86612}",
	["{zone:1454} flight master"] = "letový mistr {zone:1454}",
}
