t.guides["forever/horde/50-60/04-azshara"] = {
	["Back north to {npc:8420} with the rune, then south-west along the road."] = "Zpět na sever k {npc:8420} s runou, pak na jihozápad po cestě.",
	["Back north-west to {npc:8420}."] = "Zpět na severozápad k {npc:8420}.",
	["Back to the Sin'dorei Tome: hand in the seals, then use it to call {npc:8578}.\nCareful: Which crystal is linked to Rimtori is random. Each of the other two summons a hostile infernal instead."] = "Zpět k Sin'dorei Tome: odevzdej pečeti a pak ho použij k vyvolání {npc:8578}.\nPozor: Který krystal je spojený s Rimtori, je náhodné. Každý z ostatních dvou místo toho vyvolá nepřátelského infernala.",
	["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "Cleansed Water jde do {area:2479} v {zone:1448}: nech si ji na později.",
	["Crossroads flight master"] = "Letový mistr Crossroads",
	["Each of the camp's three officers (53) carries a seal: {npc:247006} in the middle of the camp, {npc:247013} at its eastern end, and {npc:246991}, who walks its western half: take him on the east side of his walk, where the arrow points.\nCareful: the {npc:250023}, a level 55-57 elite, stands at the camp's western edge, close to the far end of Hawkhelm's walk: wait for Hawkhelm to come back east."] = "Každý ze tří důstojníků tábora (53) nese pečeť: {npc:247006} uprostřed tábora, {npc:247013} na jeho východním konci a {npc:246991}, který chodí po jeho západní polovině: ber ho na východní straně jeho trasy, kam ukazuje šipka.\nPozor: {npc:250023}, elita levelu 55–57, stojí na západním okraji tábora, blízko vzdáleného konce Hawkhelmovy trasy: počkej, až se Hawkhelm vrátí na východ.",
	["Fly to {area:1237}"] = "Leť do {area:1237}",
	["Fly to {area:1637}"] = "Leť do {area:1637}",
	["Fly to {area:392}"] = "Leť do {area:392}",
