t.guides["forever/horde/50-60/06-silithus"] = {
	["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "Roztržený svitek leží u vchodu do {area:2261}, krypty jižně od {area:2260}.",
	["Andorhal watchtowers and silos"] = "Strážní věže a sila Andorhalu",
	["Back east past the {area:202} to {area:201}, the farm under the eastern hills: {npc:11078} guards its cauldron. Kill him for the key, then use the cauldron."] = "Zpět na východ kolem {area:202} do {area:201}, farmy pod východními kopci: její kotel hlídá {npc:11078}. Zabij ho kvůli klíči a pak použij kotel.",
	["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Zpět do Southwindu a vyšplhej na věž. Rozvířený úl nahoře vypustí Hive'Ashi Ambushers; jeden nese {item:17346}.",
	["Back to {area:3425}"] = "Zpět do {area:3425}",
	["Below ground"] = "Pod zemí",
	["Class trainer"] = "Trenér povolání",
	["Collect twenty Encrypted Twilight Texts from the cultists here, ten for {npc:15306} and ten for Ortell. Take them from the Twilight Avengers and Geolords; leave the Flamereavers and Stonecallers (59-60)."] = "Sesbírej od zdejších kultistů dvacet Encrypted Twilight Texts, deset pro {npc:15306} a deset pro Ortella. Ber je od Twilight Avengers a Geolords; Flamereavers a Stonecallers (59–60) nech být.",
	["Diseased Grizzlies"] = "Diseased Grizzlies",
	["Dredge Crushers and Pincers"] = "Dredge Crushers a Pincers",
	["Dredge Strikers"] = "Dredge Strikers",
	["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Dredge Strikers, Stonelash Scorpids a Sand Skitterers sdílejí písky kousek severně od Hold.",
	["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Na východ po cestě, {npc:11077} hlídá kotel u {area:200}.",
