	["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders a padlí strážci jsou kousek jihozápadně od věže. Vezmi z těl Raaniho pero a pečetní prsten Shadowsong.",
	["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Zpět u {quest:92529}: vesnici plní Stormcallers a {npc:251662}, Supply Caches stojí mezi domy a {npc:251966} čeká na jejím jihovýchodním konci.",
	["Back to Boro in {area:16635} with the Signet."] = "Zpět k Borovi do {area:16635} s pečetním prstenem.",
