t.guides["forever/horde/tauren/01-mulgore"] = {
	["/sit by Kaga's campfire until you get {spell:1229451}"] = "/sit u Kagina táboráku, dokud nedostaneš {spell:1229451}",
	["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Zpět na východ do {area:358}: Bristleback Shamans tam stojí mezi quilboary.",
	["Back north-west up to {area:221}."] = "Zpět na severozápad nahoru do {area:221}.",
	["Back south to the {area:396}."] = "Zpět na jih do {area:396}.",
	["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Zpět k {npc:5888} do tábora. {npc:5891} čeká na mese východně od tábora: vypij tam {item:6635}, ať ho uvidíš, pak odnes {item:6656} zpět Vědmě.",
	["Back west to the camp."] = "Zpět na západ do tábora.",
	["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Battleboars se pasou severně od svatyně; quilboaři Bristleback drží rokli na severovýchodě. {npc:8554} stojí na jejím východním konci a {object:3076} leží na zemi v táboře.",
	["Below ground"] = "Pod zemí",
	["Burning Blade Cultists hold {area:1898}, east of the road north to {zone:1454}; they drop the {item:6652}. The {item:5026} comes from the Razormane on the next guide's first visit to their camp."] = "Kultisté Burning Blade drží {area:1898}, východně od cesty na sever do {zone:1454}; dropují {item:6652}. {item:5026} je od Razormane při první návštěvě jejich tábora v dalším návodu.",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the north-western woods. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sešli {spell:18960}. {npc:11802} je v {area:2361}; {quest:5930} sedí v severozápadních lesích. {npc:11802} stojí nahoře ve své budově: jdi nahoru uvnitř, šipka patra nerozliší.",
	["Class trainer"] = "Trenér povolání",
	["Class turn-in in {area:1638}"] = "Odevzdání povolání v {area:1638}",
	["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Projdi na severozápad kolem {zone:1456} do {area:398} na dalekém severu {zone:1412}.",
	["Cross to {area:1639}."] = "Přejdi na {area:1639}.",
	["Deathskip to {area:220}"] = "Deathskip do {area:220}",
	["Die to the mobs at 63.7,78.4 ({npc:2954}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 63.7,78.4 ({npc:2954}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
