t.guides["forever/horde/troll/01-durotar"] = {
	["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Armored Scorpids lezou po pláních západně od {area:362}. Ochoč si jednoho a vrať se k {npc:3171}.",
	["Back east to Sen'jin on the way to the {area:368}."] = "Zpět na východ do Sen'jinu cestou do {area:368}.",
	["Back north-west to {area:362}: {npc:3139} first, then {npc:3147} in the watchtower, then {npc:3142} and {npc:266940} on the way out east to the shore."] = "Zpět na severozápad do {area:362}: nejdřív {npc:3139}, pak {npc:3147} ve strážní věži, pak {npc:3142} a {npc:266940} cestou ven na východ k pobřeží.",
	["Back over the bridge and south along the {zone:1411} bank of the river to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Zpět přes most a na jih po břehu řeky v {zone:1411} tam, kde úzká stezka stoupá do hory: svatyni nahoře drží {npc:5900}. Cestou nahoru dávej pozor na okraje a dolů se vrať stejnou stezkou.",
	["Back to the Den"] = "Zpět do Den",
	["Back to the Den: {npc:3143} takes {quest:804}'s claw and {npc:5887}, just outside, has {quest:1516} now that you are level 4."] = "Zpět do Den: {npc:3143} vezme dráp {quest:804} a {npc:5887} hned venku má teď, když máš level 4, {quest:1516}.",
	["Back to {area:362}."] = "Zpět do {area:362}.",
	["Back to {area:362}: {npc:3139}, then {npc:3142}."] = "Zpět do {area:362}: {npc:3139}, pak {npc:3142}.",
	["Back to {zone:1411}"] = "Zpět do {zone:1411}",
	["Below ground"] = "Pod zemí",
	["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}.\nCareful: voidwalkers fight beside the Burning Blade cultists in {quest:827} and {npc:3204} (14) waits at the back with his own: pull one cultist at a time near the entrance for the collars. The {item:4903} is optional: leave {npc:3204} unless you are 13 or have a friend."] = "Kultisté Burning Blade drží jeskyně {quest:827}; {item:4871} dropne kterýkoli z nich. {npc:3204}, warlock levelu 14, stojí hluboko uvnitř a dropne {item:4903}.\nPozor: V {quest:827} bojují vedle kultistů Burning Blade voidwalkeři a {npc:3204} (14) čeká vzadu se svým: kvůli obojkům tahej kultisty po jednom u vchodu. {item:4903} je volitelný: {npc:3204} nech být, pokud nemáš 13 nebo kamaráda.",
	["Class trainer"] = "Trenér povolání",
	["Deathskip to Northern Durotar"] = "Deathskip do severního Durotaru",
	["Die to the mobs at 52.0,21.4 ({npc:3118}): a death there sends you to this graveyard. Release your spirit and take the {npc:6491}'s resurrection."] = "Nech se zabít moby na 52.0,21.4 ({npc:3118}): smrt tam tě pošle na tento hřbitov. Uvolni ducha a přijmi oživení od {npc:6491}.",
	["Druid trainer"] = "Trenér druidů",
	["Felstalkers roam the slope below the cave, on the valley's north side."] = "Felstalkeři se potulují po svahu pod jeskyní, na severní straně údolí.",
	["Fizzle holds the Burning Blade camp on {area:369}, just north of Misha's hut. Hunters: tame a {npc:3099} with the {item:15908} on the way.\nCareful: Burning Blade cultists surround Fizzle, some linked so they aggro in pairs, and they respawn quickly.\nCareful: Halikor, a level 12 elite, roams {area:369} among the lizards: watch for him before you pull."] = "Fizzle drží tábor Burning Blade na {area:369}, kousek severně od Mishiny chýše. Hunteři: cestou si ochočte {npc:3099} pomocí {item:15908}.\nPozor: Fizzla obklopují kultisté Burning Blade, někteří propojení, takže aggrují ve dvojicích, a rychle se respawnují.\nPozor: Halikor, elite levelu 12, se potuluje po {area:369} mezi ještěry: než začneš tahat, dej si na něj pozor.",
	["Level 10"] = "Level 10",
