t.guides["forever/legacy/legacy-challenges"] = {
	["Adventure: explore the world map"] = "Dobrodružství: prozkoumej mapu světa",
	["Adventure: {npc:16042}"] = "Dobrodružství: {npc:16042}",
	["Adventure: {quest:8999} (Alliance)"] = "Dobrodružství: {quest:8999} (Aliance)",
	["Adventure: {quest:9007} (Horde)"] = "Dobrodružství: {quest:9007} (Horda)",
	["All 13 Hyjal Summit bosses are a point. Hyjal Summit is a new 20-player Forever raid at the top of {zone:2482}, near Nordrassil, open from 9 December; its bosses are not in our data, so tick it off once all 13 are down."] = "Všech 13 bossů Hyjal Summit je bod. Hyjal Summit je nový raid Foreveru pro 20 hráčů na vrcholu {zone:2482} u Nordrassilu, otevřený od 9. prosince; jeho bossové nejsou v našich datech, tak to odškrtni, až jich padne všech 13.",
	["All 8 Barrow Deeps bosses are a point. Barrow Deeps is a new 10-player Forever raid beneath {zone:2482}, entered from {zone:2482}, {zone:1452} or {area:1216} and open from 9 December; its bosses are not in our data, so tick it off once all 8 are down."] = "Všech 8 bossů Barrow Deeps je bod. Barrow Deeps je nový raid Foreveru pro 10 hráčů pod {zone:2482}, vstup z {zone:2482}, {zone:1452} nebo {area:1216}, otevřený od 9. prosince; jeho bossové nejsou v našich datech, tak to odškrtni, až jich padne všech 8.",
	["City of Dalaran (Forever's, {zone:1416}): {npc:246020}"] = "City of Dalaran (Foreverův, {zone:1416}): {npc:246020}",
	["Classes give 27 points: every class reaching 25, 45 and 60. They count once per class across your account, so a second character of a class you already raised adds nothing; a new class does. The first character to reach 25 usually unlocks the Legacy System itself."] = "Povolání dají 27 bodů: každé povolání na 25, 45 a 60. Počítají se jednou za povolání v celém účtu, takže druhá postava povolání, které už máš vytažené, nic nepřidá; nové povolání ano. První postava na 25 obvykle odemkne samotný Legacy System.",
	["Classes: level 25"] = "Povolání: level 25",
	["Classes: level 45"] = "Povolání: level 45",
	["Classes: level 60"] = "Povolání: level 60",
	["Dire Maul East"] = "Dire Maul East",
	["Dire Maul North"] = "Dire Maul North",
	["Dire Maul West"] = "Dire Maul West",
	["Dungeons: level 15-25"] = "Dungeony: level 15–25",
	["Dungeons: level 26-45"] = "Dungeony: level 26–45",
	["Dungeons: level 46-60"] = "Dungeony: level 46–60",
	["Each crafting profession gives 3 points, at 150, 225 and 300. Ranks count once per profession across your account. Follow the Evertally guide \"{skill:171} 1-300\" (Professions). A crafting profession at 150 also unlocks the Legacy System."] = "Každá výrobní profese dá 3 body, na 150, 225 a 300. Ranky se počítají jednou za profesi v celém účtu. Sleduj návod Evertally „{skill:171} 1–300“ (Profese). Výrobní profese na 150 navíc odemkne Legacy System.",
	["Exalted with each of the four battleground factions is worth a point. Follow the Evertally Reputation guides Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation and Darkspear Islands Reputation (Forever's new battleground, open from level 30). The Diplomat Legacy perk increases reputation gains."] = "Exalted u každé ze čtyř frakcí battlegroundů má cenu jednoho bodu. Následuj reputační návody Evertally Warsong Gulch Reputation, Arathi Basin Reputation, Alterac Valley Reputation a Darkspear Islands Reputation (nový battleground Foreveru, otevřený od levelu 30). Výhoda Legacy Diplomat zvyšuje zisky reputace.",
	["Exploring the entire world map on one character is a point, and it can also unlock the Legacy System. It must all be on the same character. Forever's new zones are part of the map: the {zone:2548}, {zone:2652} and {zone:2482}, a level 60 zone."] = "Prozkoumání celé mapy světa je bod a může také odemknout Legacy System. Všechno musí být na stejné postavě. Nové zóny Foreveru jsou součástí mapy: {zone:2548}, {zone:2652} a {zone:2482}, zóna levelu 60.",
	["Follow the Evertally guide \"{skill:164} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:164} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:165} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:165} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:197} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:197} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:202} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:202} 1–300“ (Profese).",
	["Follow the Evertally guide \"{skill:333} 1-300\" (Professions)."] = "Následuj návod Evertally „{skill:333} 1–300“ (Profese).",
	["Tradeskills: {skill:164}"] = "Profese: {skill:164}",
	["Tradeskills: {skill:165}"] = "Profese: {skill:165}",
	["Tradeskills: {skill:171}"] = "Profese: {skill:171}",
