}
t.guides["forever/miscellaneous/cozy-sleeping-bag"] = {
	["A hundred paces north"] = "Sto kroků na sever",
	["A trail of hidden notes across both continents: the {item:211527} at the end, a 12-slot {item:221498} on the way."] = "Stopa skrytých poznámek přes oba kontinenty: na konci {item:211527}, po cestě {item:221498} s 12 místy.",
	["Along the coast to {zone:1436}"] = "Podél pobřeží do {zone:1436}",
	["At the gate in {area:1057} between Arathi and {area:287}, turn north and follow the wall on the {area:287} side to a fallen cart leaning against it. Jump up the cart and its ladder onto the wall, then over the rocks to the hidden camp. Some characters cannot fit under the cargo netting at the camp; another race or a smaller form gets through."] = "U brány v {area:1057} mezi Arathi a {area:287} zahni na sever a jdi podél zdi na straně {area:287} k převrácenému vozu opřenému o zeď. Vyskoč na vůz a po jeho žebříku na zeď, pak přes skály do skrytého tábora. Některé postavy se v táboře nevejdou pod síť s nákladem; jiná rasa nebo menší forma projde.",
	["Careful: off the dam's ledge you land in the river below it, in the {zone:1437}. Climb out on its west bank well before the waterfall at about 65,77: the fall kills. Then head north-west to the road and follow it north over {area:880} into Arathi, or hearth if your Hearthstone is set at {area:272}."] = "Pozor: Ze stupně hráze spadneš do řeky pod ní, v {zone:1437}. Vylez na západní břeh dlouho před vodopádem kolem 65,77: pád zabíjí. Pak jdi na severozápad k cestě a po ní na sever přes {area:880} do Arathi, nebo hearthni, pokud máš Hearthstone nastavený v {area:272}.",
	["Fallen cart"] = "Převrácený vůz",
}
t.guides["forever/miscellaneous/library-books"] = {
	["At {area:118}, the dig in the middle of the {zone:1437}."] = "V {area:118}, vykopávkách uprostřed {zone:1437}.",
	["At {area:233}, the mage village in south-eastern Silverpine."] = "V {area:233}, vesnici mágů na jihovýchodě Silverpine.",
	["Beside a tent entrance in the troll village in south-eastern Arathi."] = "U vchodu do stanu v trollí vesnici na jihovýchodě Arathi.",
	["Cave mouth at {area:387}"] = "Ústí jeskyně u {area:387}",
	["Down the stairs at the {area:443} in northern {zone:1439}."] = "Dolů po schodech u {area:443} v severním {zone:1439}.",
	["Eight more books lie in level 55-60 zones; the mage trainers beside the librarians take them, not the librarians. {item:228141} lies on a table in the ruined keep on {area:2298}, above {area:2057} (outside the dungeon); {item:228132} at {area:199}."] = "Dalších osm knih leží v zónách levelu 55–60; berou je trenéři mágů vedle knihovníků, ne knihovníci. {item:228141} leží na stole ve zničené pevnosti na {area:2298}, nad {area:2057} (mimo dungeon); {item:228132} u {area:199}.",
}
t.guides["forever/miscellaneous/stalk-with-the-earthmother"] = {
	["A one-hand blade or mace at 11 from {npc:205729}'s three tests in and around {zone:1456}, for a Tauren of any class."] = "Jednoruční čepel nebo palice na 11 za tři zkoušky {npc:205729} v {zone:1456} a okolí, pro Taurena jakéhokoli povolání.",
	["Back to {npc:205729} in {zone:1456}. He gives you the {item:206176} for his next test."] = "Zpět k {npc:205729} do {zone:1456}. Dá ti {item:206176} na další zkoušku.",
	["Back to {npc:205729}. He hands you the {item:206344} for the last test."] = "Zpět k {npc:205729}. Dá ti {item:206344} na poslední zkoušku.",
	["Buy a {item:6291} at the Auction House ({npc:8674}, north of the pool), or fish one yourself: {npc:3028} trains {skill:356} and {npc:3029} beside him sells the {item:6256} and a {item:6529}; the pool on the main mesa gives smallfish at any skill. Then use the {item:206344} on it, wherever you are."] = "Kup {item:6291} v aukci ({npc:8674}, severně od tůně), nebo si ji vylov sám: {npc:3028} učí {skill:356} a {npc:3029} vedle něj prodává {item:6256} a {item:6529}; tůň na hlavní mese dává smallfish při jakékoli dovednosti. Pak na ni použij {item:206344}, ať jsi kdekoli.",
	["{item:206157}, from the {object:403041}"] = "{item:206157}, od {object:403041}",
}
