	["44 {item:1210} for {item:7945}: {item:1210} turns up in about one {object:1731}, {object:1732} or {object:1733} in 100: keep the ones you find while mining."] = "44 {item:1210} pro {item:7945}: {item:1210} se objeví zhruba v jednom z 100 {object:1731}, {object:1732} nebo {object:1733}: nech si, co najdeš při těžbě.",
	["44 {item:7912} for {item:7945}: {skill:186}: {object:2040} (skill 175) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55). The densest cluster of {object:2040} in {zone:1425} is marked."] = "44 {item:7912} pro {item:7945}: {skill:186}: {object:2040} (dovednost 175) v {zone:1425} (40–50), {zone:1444} (40–50) a {zone:1447} (45–55). Nejhustší výskyt {object:2040} v {zone:1425} je označený.",
