t.guides["forever/professions/cooking"] = {
	["Any {skill:185} trainer of your faction teaches Apprentice {skill:185} (any character level, 1s); the arrow picks the nearest. Forever: every cook knows {object:29784}. Craft a {item:279981} from one {item:4470} (38c) with {item:4471} (1s 35c, kept in your bags), then place the kit to light a cooking fire anywhere; make a few in advance (one use every 5 minutes). The first kits also raise {skill:185} to about 5. The Camping 101: {skill:185} quest at your starting area's camp sends you to this trainer."] = "Apprentice {skill:185} naučí kterýkoli trenér {skill:185} tvé frakce (jakýkoli level postavy, 1s); šipka vybere nejbližšího. Forever: každý kuchař umí {object:29784}. Vyrob {item:279981} z jednoho {item:4470} (38c) s {item:4471} (1s 35c, zůstává v taškách) a pak polož sadu a rozdělej ohniště kdekoli; udělej jich pár dopředu (jedno použití za 5 minut). První sady zvednou {skill:185} asi na 5. Quest Camping 101: {skill:185} v táboře tvé startovní oblasti tě pošle k tomuto trenérovi.",
	["Artisan {skill:185}"] = "Artisan {skill:185}",
	["Artisan {skill:185} comes from {npc:8125} in {area:976} ({zone:1446}). The cooking trainer in {zone:1454} sends you; it needs skill 225 and level 35."] = "Artisan {skill:185} je od {npc:8125} v {area:976} ({zone:1446}). Pošle tě tam trenér vaření v {zone:1454}; potřebuje dovednost 225 a level 35.",
	["Artisan {skill:185} comes from {npc:8125} in {area:976} ({zone:1446}). The cooking trainer in {zone:1455} sends you; it needs skill 225 and level 35."] = "Artisan {skill:185} je od {npc:8125} v {area:976} ({zone:1446}). Pošle tě tam trenér vaření v {zone:1455}; potřebuje dovednost 225 a level 35.",
	["Buy and read {item:16072} (Expert {skill:185})"] = "Kup a přečti {item:16072} (Expert {skill:185})",
	["Coyote (54%), {npc:833} (51%) in {zone:1436}, or wherever the arrow points"] = "Kojot (54 %), {npc:833} (51 %) v {zone:1436}, nebo kamkoli šipka ukáže",
	["Expert {skill:185}"] = "Expert {skill:185}",
	["Expert {skill:185} raises the cap to 225; it needs skill 125 and character level 20: it is a book, {item:16072} (1g); the arrow picks its nearest seller for your faction. Buy it and read it."] = "Expert {skill:185} zvedne strop na 225; potřebuje dovednost 125 a level postavy 20: je to kniha, {item:16072} (1g); šipka vybere jejího nejbližšího prodejce pro tvou frakci. Kup ji a přečti.",
	["Journeyman {skill:185}"] = "Journeyman {skill:185}",
	["Learn {skill:185}"] = "Nauč se {skill:185}",
	["What {item:12210} takes that the Auction House sells: 52 {item:12184}. The counts drop by what your bags, bank and mail hold."] = "Co {item:12210} potřebuje a aukce prodává: 52 {item:12184}. Počty se sníží o to, co máš v taškách, bance a poště.",
