t.guides["forever/professions/enchanting"] = {
	["1 {item:11082} for {item:11130}: {skill:333}: disenchant green items of item level 16-25."] = "1 {item:11082} pro {item:11130}: {skill:333}: disenchantuj zelené předměty item levelu 16–25.",
	["1 {item:11128} for {item:11130}: {skill:164}: {item:11128}."] = "1 {item:11128} pro {item:11130}: {skill:164}: {item:11128}.",
	["1 {item:11135} for {item:11145}: {skill:333}: disenchant green items of item level 26-35."] = "1 {item:11135} pro {item:11145}: {skill:333}: disenchantuj zelené předměty item levelu 26–35.",
	["1 {item:11144} for {item:11145}: {skill:164}: {item:11144}."] = "1 {item:11144} pro {item:11145}: {skill:164}: {item:11144}.",
	["1 {item:1210} for {item:6339}: {item:1210} turns up in about one {object:1731}, {object:1732} or {object:1733} in 100: keep the ones you find while mining."] = "1 {item:1210} pro {item:6339}: {item:1210} se objeví zhruba v jednom z 100 {object:1731}, {object:1732} nebo {object:1733}: nech si, co najdeš při těžbě.",
	["1 {item:5500} for {item:11130}: open the Giant Clams at the marked spot."] = "1 {item:5500} pro {item:11130}: otevři Giant Clams na označeném místě.",
	["1 {item:6338} for {item:6339}: {skill:164}: {item:6338}."] = "1 {item:6338} pro {item:6339}: {skill:164}: {item:6338}.",
	["121 {item:10940} for {spell:7420}, {spell:7771} and {item:6339}: {skill:333}: disenchant green items of item level 5-20."] = "121 {item:10940} pro {spell:7420}, {spell:7771} a {item:6339}: {skill:333}: disenchantuj zelené předměty item levelu 5–20.",
	["20 {item:11083} for {spell:13501}: {skill:333}: disenchant green items of item level 21-30."] = "20 {item:11083} pro {spell:13501}: {skill:333}: disenchantuj zelené předměty item levelu 21–30.",
	["208 {item:11176} for {item:20747} and {spell:20017}: {skill:333}: disenchant green items of item level 41-50."] = "208 {item:11176} pro {item:20747} a {spell:20017}: {skill:333}: disenchantuj zelené předměty item levelu 41–50.",
	["21 {item:11137} for {item:11145} and {spell:13746}: {skill:333}: disenchant green items of item level 31-40."] = "21 {item:11137} pro {item:11145} a {spell:13746}: {skill:333}: disenchantuj zelené předměty item levelu 31–40.",
	["34 {item:8831} for {item:20747}: {skill:182}: {item:8831} (skill 210) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55). The densest patch of {item:8831} in {zone:1425} is marked."] = "34 {item:8831} pro {item:20747}: {skill:182}: {item:8831} (dovednost 210) v {zone:1425} (40–50), {zone:1444} (40–50) a {zone:1447} (45–55). Nejhustší porost {item:8831} v {zone:1425} je označený.",
	["34 {item:8831} for {item:20747}: {skill:182}: {item:8831} (skill 210) in {zone:1425} (40-50), {zone:1444} (40-50) and {zone:1447} (45-55). The densest patch of {item:8831} in {zone:1444} is marked."] = "34 {item:8831} pro {item:20747}: {skill:182}: {item:8831} (dovednost 210) v {zone:1425} (40–50), {zone:1444} (40–50) a {zone:1447} (45–55). Nejhustší porost {item:8831} v {zone:1444} je označený.",
	["39 {item:11137} for {spell:13815}: {skill:333}: disenchant green items of item level 31-40."] = "39 {item:11137} pro {spell:13815}: {skill:333}: disenchantuj zelené předměty item levelu 31–40.",
	["51 {item:10940} for {spell:7420}: {skill:333}: disenchant green items of item level 5-20."] = "51 {item:10940} pro {spell:7420}: {skill:333}: disenchantuj zelené předměty item levelu 5–20.",
	["71 {item:11083} for {item:11130}, {spell:13501} and {spell:13637}: {skill:333}: disenchant green items of item level 21-30."] = "71 {item:11083} pro {item:11130}, {spell:13501} a {spell:13637}: {skill:333}: disenchantuj zelené předměty item levelu 21–30.",
	["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) and {npc:11065} ({zone:1455}); Horde {npc:257004} (Zephras Isle), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "Apprentice {skill:333} ti dovolí vyrábět až do 75 za 10c, na jakémkoli levelu postavy. Ne každý trenér {skill:333} ho učí: Aliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) a {npc:11065} ({zone:1455}); Horda {npc:257004} (Zephras Isle), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) a {npc:5695} ({zone:1420}). Šipka vybere nejbližšího z tvé frakce. Kup {item:6217} a {item:247786} u obchodníka s očarovatelskými potřebami (v hlavních městech a na Zephras Isle; trenéři ve startovních oblastech žádného vedle nemají a šipka dalšího kroku vybere nejbližšího). Odteď disenchantuj každý zelený předmět, který nenosíš: odtud je prach a esence. Dva startovní questy naučí Disenchant na questovém předmětu: An Enchanting Lesson od {npc:11072} ({area:91}, {zone:1429}) a A Pain in the Neck od {npc:266881} ({area:367}, {zone:1411}). 1–75 stojí asi 50c za recepty a 4s 44c za zboží od obchodníků, plus 51 {item:10940} k nasbírání nebo koupi.",
	["Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs {skill:333} 200 and character level 35, so you can take it on any visit from 200. {npc:11073} teaches Artisan {skill:333} inside the {area:1517} dungeon ({zone:1418}); bring a group. Learn now: {spell:13815} (from 210). 225-300 takes about 2g 20s of recipes and 1g 70s of vendor goods, plus 34 {item:8831}, 39 {item:11137} and 208 {item:11176} to gather or buy."] = "Artisan zvedne strop z 225 na 300 za 5g (cena Classicu; ceny Foreveru v datech nejsou); potřebuje {skill:333} 200 a level postavy 35, takže ho můžeš vzít při jakékoli návštěvě od 200. Artisan {skill:333} učí {npc:11073} uvnitř dungeonu {area:1517} ({zone:1418}); vezmi skupinu. Nauč se teď: {spell:13815} (od 210). 225–300 stojí asi 2g 20s za recepty a 1g 70s za zboží od obchodníků, plus 34 {item:8831}, 39 {item:11137} a 208 {item:11176} k nasbírání nebo koupi.",
	["Artisan {skill:333}"] = "Artisan {skill:333}",
	["Back to an {skill:333} trainer: {spell:7420} (from 15, 50c). Also learn {spell:1230643} (1s): Forever's {skill:333} camp item, 1 {item:4470} and 1 {item:10940}, placed at a campsite beside a campfire for its buff. The Camping 101: {skill:333} quest from your starting area's camping guide (after The Great Outdoors) sends you to an enchanting trainer who teaches it free."] = "Zpět k trenérovi {skill:333}: {spell:7420} (od 15, 50c). Nauč se i {spell:1230643} (1s): táborový předmět {skill:333} ve Foreveru, 1 {item:4470} a 1 {item:10940}, položený v kempu u táboráku kvůli buffu. Quest Camping 101: {skill:333} od průvodce kempováním ve tvé startovní oblasti (po The Great Outdoors) tě pošle k trenérovi očarování, který ho naučí zdarma.",
	["Back to an {skill:333} trainer: {spell:7795} (from 100) and {spell:13501} (from 130)."] = "Zpět k trenérovi {skill:333}: {spell:7795} (od 100) a {spell:13501} (od 130).",
	["Buy the whole bracket's share in one go: 1 {item:6217} (1s 24c) and 32 {item:247786} (3s 20c); about 4s 44c in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286} and {npc:1318}; {zone:1454}: {npc:3367}, {npc:3346} and {npc:5817})."] = "Kup podíl celého pásma najednou: 1 {item:6217} (1s 24c) a 32 {item:247786} (3s 20c); celkem asi 4s 44c. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1286} a {npc:1318}; {zone:1454}: {npc:3367}, {npc:3346} a {npc:5817}).",
	["Buy the whole bracket's share in one go: 34 {item:8925} (1g 70s); about 1g 70s in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286}, Eldraeith and {npc:1325}; {zone:1454}: {npc:3367}, {npc:3348} and {npc:3334})."] = "Kup podíl celého pásma najednou: 34 {item:8925} (1g 70s); celkem asi 1g 70s. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1286}, Eldraeith a {npc:1325}; {zone:1454}: {npc:3367}, {npc:3348} a {npc:3334}).",
	["Buy the whole bracket's share in one go: 4 {item:10938} (32s). The arrow picks the nearest seller of your faction. {item:10938}: no vendor of the other faction sells it; that side gathers or buys it at the Auction House (next steps)."] = "Kup podíl celého pásma najednou: 4 {item:10938} (32s). Šipka vybere nejbližšího prodejce tvé frakce. {item:10938}: žádný obchodník druhé frakce ho neprodává; ta strana ho sbírá nebo kupuje v aukci (další kroky).",
	["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:333} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:11072} ({zone:1429}); Horde {npc:11074} ({zone:1442}). The arrow picks the nearest of your faction. Learn now: {spell:13628} (from 150). 150-225 takes 1 {item:5500}, 1 {item:7971}, 1 {item:11082}, 71 {item:11083}, 1 {item:11128}, 1 {item:11135}, 21 {item:11137} and 1 {item:11144} to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach {spell:13637} (from 160), {item:11145} (from 200) and {spell:13746} (from 205), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3."] = "Expert zvedne strop ze 150 na 225 za 50s (cena Classicu; ceny Foreveru v datech nejsou); potřebuje {skill:333} 125 a level postavy 20, takže ho můžeš vzít při jakékoli návštěvě od 125. Učí ho jen pár trenérů: Aliance {npc:11072} ({zone:1429}); Horda {npc:11074} ({zone:1442}). Šipka vybere nejbližšího z tvé frakce. Nauč se teď: {spell:13628} (od 150). 150–225 stojí 1 {item:5500}, 1 {item:7971}, 1 {item:11082}, 71 {item:11083}, 1 {item:11128}, 1 {item:11135}, 21 {item:11137} a 1 {item:11144} k nasbírání nebo koupi. Přijď se vším v taškách (kroky výše, zbytek z aukce): tihle trenéři učí i {spell:13637} (od 160), {item:11145} (od 200) a {spell:13746} (od 205) a výroba nepotřebuje stanici, takže vyráběj přímo tady a každý recept se nauč, jakmile dosáhneš jeho dovednosti. Jedna cesta místo 3.",
	["Expert {skill:333}"] = "Expert {skill:333}",
