t.guides["forever/professions/first-aid"] = {
	["Any {skill:129} trainer of your faction teaches Apprentice {skill:129} (any character level, 1s); the arrow picks the nearest. Forever teaches {item:118} with it: {item:2447}, {item:2678} and an {item:3371}, orange to 55. With {skill:182} it can replace the Linen Bandages below."] = "Apprentice {skill:129} naučí kterýkoli trenér {skill:129} tvé frakce (jakýkoli level postavy, 1s); šipka vybere nejbližšího. Forever s ní učí {item:118}: {item:2447}, {item:2678} a {item:3371}, oranžové do 55. S {skill:182} může nahradit Linen Bandages níže.",
	["Artisan {skill:129}"] = "Artisan {skill:129}",
	["Artisan {skill:129} comes from the {quest:6622} quest. It needs skill 225 and level 35; the {skill:129} trainer in {zone:1454} sends you to the doctor in {area:321}. Bring the Mageweave (about 74) and {item:14047} (about 65) for 225-300 now: bandages need no fire, so you craft 225-300 beside the doctor, who teaches the Artisan bandages."] = "Artisan {skill:129} je z questu {quest:6622}. Potřebuje dovednost 225 a level 35; trenér {skill:129} v {zone:1454} tě pošle za doktorem v {area:321}. Přines teď Mageweave (asi 74) a {item:14047} (asi 65) na 225–300: obvazy nepotřebují oheň, takže 225–300 vyrobíš vedle doktora, který učí obvazy Artisan.",
	["Artisan {skill:129} comes from the {quest:6624} quest. It needs skill 225 and level 35; the {skill:129} trainer in {zone:1455} sends you to the doctor in Theramore. Bring the Mageweave (about 74) and {item:14047} (about 65) for 225-300 now: bandages need no fire, so you craft 225-300 beside the doctor, who teaches the Artisan bandages."] = "Artisan {skill:129} je z questu {quest:6624}. Potřebuje dovednost 225 a level 35; trenér {skill:129} v {zone:1455} tě pošle za doktorem v Theramore. Přines teď Mageweave (asi 74) a {item:14047} (asi 65) na 225–300: obvazy nepotřebují oheň, takže 225–300 vyrobíš vedle doktora, který učí obvazy Artisan.",
	["Buy and read {item:16084} (Expert {skill:129})"] = "Kup a přečti {item:16084} (Expert {skill:129})",
	["Expert {skill:129}"] = "Expert {skill:129}",
	["Expert {skill:129} raises the cap to 225; it needs skill 125 and character level 20: it is a book, {item:16084} (1g); the arrow picks its nearest seller for your faction. Buy it and read it. The same vendor sells the Heavy Silk and {item:8544} manuals (22s and 50s): buy both now, you read them at 180 and 210."] = "Expert {skill:129} zvedne strop na 225; potřebuje dovednost 125 a level postavy 20: je to kniha, {item:16084} (1g); šipka vybere jejího nejbližšího prodejce pro tvou frakci. Kup ji a přečti. Stejný obchodník prodává i manuály Heavy Silk a {item:8544} (22s a 50s): kup oba hned, přečteš je na 180 a 210.",
	["Journeyman {skill:129}"] = "Journeyman {skill:129}",
	["Learn {skill:129}"] = "Nauč se {skill:129}",
	["What {item:1251} takes that the Auction House sells: 41 {item:2589}. The counts drop by what your bags, bank and mail hold."] = "Co {item:1251} potřebuje a aukce prodává: 41 {item:2589}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:14529} takes that the Auction House sells: 65 {item:14047}. The counts drop by what your bags, bank and mail hold."] = "Co {item:14529} potřebuje a aukce prodává: 65 {item:14047}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:2581} takes that the Auction House sells: 20 {item:2589}. The counts drop by what your bags, bank and mail hold."] = "Co {item:2581} potřebuje a aukce prodává: 20 {item:2589}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:2581} takes that the Auction House sells: 92 {item:2589}. The counts drop by what your bags, bank and mail hold."] = "Co {item:2581} potřebuje a aukce prodává: 92 {item:2589}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:6450} takes that the Auction House sells: 42 {item:4306}. The counts drop by what your bags, bank and mail hold."] = "Co {item:6450} potřebuje a aukce prodává: 42 {item:4306}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:6451} takes that the Auction House sells: 84 {item:4306}. The counts drop by what your bags, bank and mail hold."] = "Co {item:6451} potřebuje a aukce prodává: 84 {item:4306}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What {item:8544} takes that the Auction House sells: 18 {item:4338}. The counts drop by what your bags, bank and mail hold."] = "Co {item:8544} potřebuje a aukce prodává: 18 {item:4338}. Počty se sníží o to, co máš v taškách, bance a poště.",
