t.guides["forever/professions/fishing"] = {
	["Any {skill:356} trainer of your faction teaches Apprentice {skill:356} at any character level (1s); the arrow picks the nearest, and every starting area has one on its lake or shore. Buy a {item:6256} (23c) from a trade goods or fishing vendor and equip it (you can only fish with a pole in your hands), and two or three Shiny Baubles (+25, 50c each): a lure adds its bonus to your skill for ten minutes, so fewer fish get away at the start. If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:356}, handed in to the fishing trainer it names at skill 20 for the {spell:1229745} recipe."] = "Apprentice {skill:356} naučí na jakémkoli levelu postavy (1s) kterýkoli trenér {skill:356} tvé frakce; šipka vybere nejbližšího a každá startovní oblast má jednoho u jezera nebo pobřeží. Kup {item:6256} (23c) u obchodníka se surovinami nebo rybářskými potřebami a nasaď ho (rybařit jde jen s prutem v rukou) a dva tři Shiny Baubles (+25, po 50c): návnada přidá svůj bonus k dovednosti na deset minut, takže na začátku uteče méně ryb. Pokud sis sedl k táboráku své startovní oblasti kvůli The Great Outdoors, tamní průvodce kempováním nabízí i Camping 101: {skill:356}, odevzdávaný trenérovi rybaření, kterého jmenuje, při dovednosti 20 za recept {spell:1229745}.",
	["Artisan {skill:356}"] = "Artisan {skill:356}",
	["Artisan {skill:356} (cap 300) comes from {npc:12919} in {zone:1445}. The fishing trainer in {zone:1454} sends you to him; the quest needs skill 225 and level 35."] = "Artisan {skill:356} (strop 300) je od {npc:12919} v {zone:1445}. Pošle tě k němu trenér rybaření v {zone:1454}; quest potřebuje dovednost 225 a level 35.",
	["Artisan {skill:356} (cap 300) comes from {npc:12919} in {zone:1445}. The fishing trainer in {zone:1455} sends you to him; the quest needs skill 225 and level 35."] = "Artisan {skill:356} (strop 300) je od {npc:12919} v {zone:1445}. Pošle tě k němu trenér rybaření v {zone:1455}; quest potřebuje dovednost 225 a level 35.",
	["Buy and read {item:16083} (Expert {skill:356})"] = "Kup a přečti {item:16083} (Expert {skill:356})",
	["Expert {skill:356}"] = "Expert {skill:356}",
	["Expert {skill:356} (cap 225) is a book, not a trainer rank: {npc:2626} sells {item:16083} (1g) on the lowest dock of {area:35}, at the south tip of {zone:1434}, to both factions. Buy it and read it; it needs skill 125 and level 20. At level 20 the safe way in is the boat from {area:392} in {zone:1413}, not the road through Stranglethorn. He also sells {item:6532} (+75 from skill 100, 2s 50c each), the lure for the rest of the way."] = "Expert {skill:356} (strop 225) je kniha, ne hodnost u trenéra: {npc:2626} prodává {item:16083} (1g) na nejnižším molu {area:35}, na jižním cípu {zone:1434}, oběma frakcím. Kup ji a přečti; potřebuje dovednost 125 a level 20. Na levelu 20 je bezpečná cesta lodí z {area:392} v {zone:1413}, ne po silnici přes Stranglethorn. Prodává i {item:6532} (+75 od dovednosti 100, po 2s 50c), návnadu na zbytek cesty.",
	["Fish along the coast of {zone:1443} ({area:598} in the north-west, or the shore west of {area:2408}) until you catch a {item:16968}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "Ryb podél pobřeží {zone:1443} ({area:598} na severozápadě nebo břeh západně od {area:2408}), dokud nechytíš {item:16968}: zhruba jeden úlovek z pěti ho tam vytáhne a nikde jinde nebere. Na dovednosti 225 tu nic neuteče.",
	["Fish along the {area:2521} in {zone:1444} (south-east of {area:2577}) until you catch a {item:16967}: about one catch in five there brings it up, and it bites nowhere else. This water loses fish below skill 300: at 225 most get away, so put {item:6532} (+75) on the pole first."] = "Ryb podél {area:2521} v {zone:1444} (jihovýchodně od {area:2577}), dokud nechytíš {item:16967}: zhruba jeden úlovek z pěti ho tam vytáhne a nikde jinde nebere. V téhle vodě ryby pod dovedností 300 utíkají: na 225 jich většina uteče, tak si nejdřív dej na prut {item:6532} (+75).",
	["Fish along the {area:300} (the east shore of {zone:1435}) until you catch a {item:16970}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "Ryb podél {area:300} (východní břeh {zone:1435}), dokud nechytíš {item:16970}: zhruba jeden úlovek z pěti ho tam vytáhne a nikde jinde nebere. Na dovednosti 225 tu nic neuteče.",
	["Fish along {zone:1434}'s {area:301} (the west shore) until you catch a {item:16969}: about one catch in five there brings it up, and it bites nowhere else. At skill 225 nothing gets away here."] = "Ryb podél {area:301} v {zone:1434} (západní břeh), dokud nechytíš {item:16969}: zhruba jeden úlovek z pěti ho tam vytáhne a nikde jinde nebere. Na dovednosti 225 tu nic neuteče.",
	["Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast {skill:356} from your spellbook, click the bobber when it splashes. Keep the fish: they are your first {skill:185} ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap. To cook what you catch: {item:6325} for the {item:6291} of lakes and rivers ({skill:185} 1, 40c: Nyoma ({zone:1438})); {item:6326} for the {item:6303} of the coast ({skill:185} 1, 40c: {npc:10118} ({zone:1438}))."] = "Ryb tady do dovednosti 50, asi 50 úlovků: pod 75 zvedne dovednost každý úlovek. Sešli {skill:356} ze spellbooku, klikni na splávek, když šplouchne. Ryby si nech: jsou to tvoje první suroviny na {skill:185}. Pod dovedností 25 tu ryby utíkají; návnada na prutu přidá na deset minut k dovednosti a rozdíl dorovná. Jak uvařit úlovek: {item:6325} na {item:6291} z jezer a řek ({skill:185} 1, 40c: Nyoma ({zone:1438})); {item:6326} na {item:6303} z pobřeží ({skill:185} 1, 40c: {npc:10118} ({zone:1438})).",
	["Fish here until skill 50, about 50 catches: below 75 every catch raises the skill. Cast {skill:356} from your spellbook, click the bobber when it splashes. Keep the fish: they are your first {skill:185} ingredients. Fish get away here below skill 25; a lure on the pole adds to your skill for ten minutes and closes the gap. To cook what you catch: {item:6325} for the {item:6291} of lakes and rivers ({skill:185} 1, 40c: {npc:3550} ({zone:1420}) or {npc:4574} ({zone:1458})); {item:6326} for the {item:6303} of the coast ({skill:185} 1, 40c: {npc:3550} ({zone:1420}))."] = "Ryb tady do dovednosti 50, asi 50 úlovků: pod 75 zvedne dovednost každý úlovek. Sešli {skill:356} ze spellbooku, klikni na splávek, když šplouchne. Ryby si nech: jsou to tvoje první suroviny na {skill:185}. Pod dovedností 25 tu ryby utíkají; návnada na prutu přidá na deset minut k dovednosti a rozdíl dorovná. Jak uvařit úlovek: {item:6325} na {item:6291} z jezer a řek ({skill:185} 1, 40c: {npc:3550} ({zone:1420}) nebo {npc:4574} ({zone:1458})); {item:6326} na {item:6303} z pobřeží ({skill:185} 1, 40c: {npc:3550} ({zone:1420})).",
