t.guides["forever/professions/herbalism"] = {
	["Any {skill:182} trainer of your faction teaches Apprentice {skill:182} at any level (10c), and so does the Junior Herbalism Trainer in each starting area; the arrow picks the nearest. Turn on {spell:2383} (spellbook, General tab) so herbs show on the minimap. Forever's starting areas also have {object:656160} and {object:656161} (skill 1). The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) offers {item:247841} as a reward: reading it gives 2 skill, up to 15. Trade goods vendors sell the {item:277113}, a four-slot bag for herbs (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:182}: hand it in to the herbalism trainer it names once you reach skill 20, for the {spell:1229705} recipe."] = "Apprentice {skill:182} naučí na jakémkoli levelu (10c) kterýkoli trenér {skill:182} tvé frakce i Junior Herbalism Trainer v každé startovní oblasti; šipka vybere nejbližšího. Zapni {spell:2383} (spellbook, karta General), ať se bylinky ukazují na minimapě. Startovní oblasti Foreveru mají i {object:656160} a {object:656161} (dovednost 1). Quest první hodiny každé startovní oblasti (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) nabízí jako odměnu {item:247841}: přečtení dá 2 dovednosti, až do 15. Obchodníci se surovinami prodávají {item:277113}, čtyřmístný vak na bylinky (25c). Pokud sis sedl k táboráku své startovní oblasti kvůli The Great Outdoors, tamní průvodce kempováním nabízí i Camping 101: {skill:182}: odevzdej ho trenérovi bylinkářství, kterého jmenuje, až budeš mít dovednost 20, za recept {spell:1229705}.",
	["Artisan {skill:182}"] = "Artisan {skill:182}",
	["Artisan {skill:182} raises the cap to 300; it needs skill 200 and no character level, and costs 5g: train it as soon as you reach 200. The arrow picks the nearest {skill:182} trainer of your faction."] = "Artisan {skill:182} zvedne strop na 300; potřebuje dovednost 200, žádný level postavy a stojí 5g: vytrénuj ho, jakmile dosáhneš 200. Šipka vybere nejbližšího trenéra {skill:182} tvé frakce.",
	["Expert {skill:182}"] = "Expert {skill:182}",
	["Expert {skill:182} raises the cap to 225; it needs skill 125 and no character level, and costs 50s: train it as soon as you reach 125. The arrow picks the nearest {skill:182} trainer of your faction."] = "Expert {skill:182} zvedne strop na 225; potřebuje dovednost 125 a žádný level postavy a stojí 50s: vytrénuj ho, jakmile dosáhneš 125. Šipka vybere nejbližšího trenéra {skill:182} tvé frakce.",
	["Journeyman {skill:182}"] = "Journeyman {skill:182}",
	["Learn {skill:182}"] = "Nauč se {skill:182}",
}
