t.guides["forever/professions/mining"] = {
	["Any {skill:186} trainer of your faction teaches Apprentice {skill:186} at any level (10c), and so does the Junior Mining Trainer in each starting area; the arrow picks the nearest. Buy a {item:2901} from a trade goods or general vendor: keep it in your bags, you cannot mine without it. Turn on {spell:2580} (spellbook, General tab) so veins show on the minimap. Forever's starting areas also have Poor Copper Veins ({item:2770} and {item:2835}, from skill 1). The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) offers {item:247840} as a reward: reading it gives 2 skill, up to 15. Trade goods vendors and the junior trainers sell the {item:277115}, a four-slot bag for ore and stone (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:186}: hand it in to the mining trainer it names once you reach skill 20, for the {spell:1230161} recipe."] = "Apprentice {skill:186} naučí na jakémkoli levelu (10c) kterýkoli trenér {skill:186} tvé frakce i Junior Mining Trainer v každé startovní oblasti; šipka vybere nejbližšího. Kup {item:2901} u obchodníka se surovinami nebo smíšeným zbožím: nech si ho v taškách, bez něj těžit nejde. Zapni {spell:2580} (spellbook, karta General), ať se žíly ukazují na minimapě. Startovní oblasti Foreveru mají i Poor Copper Veins ({item:2770} a {item:2835}, od dovednosti 1). Quest první hodiny každé startovní oblasti (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) nabízí jako odměnu {item:247840}: přečtení dá 2 dovednosti, až do 15. Obchodníci se surovinami a junior trenéři prodávají {item:277115}, čtyřmístný vak na rudu a kámen (25c). Pokud sis sedl k táboráku své startovní oblasti kvůli The Great Outdoors, tamní průvodce kempováním nabízí i Camping 101: {skill:186}: odevzdej ho trenérovi hornictví, kterého jmenuje, až budeš mít dovednost 20, za recept {spell:1230161}.",
	["Artisan {skill:186}"] = "Artisan {skill:186}",
	["Artisan {skill:186} raises the cap to 300; it needs skill 200 and no character level, and costs 5g: train it as soon as you reach 200. The arrow picks the nearest {skill:186} trainer of your faction."] = "Artisan {skill:186} zvedne strop na 300; potřebuje dovednost 200, žádný level postavy a stojí 5g: vytrénuj ho, jakmile dosáhneš 200. Šipka vybere nejbližšího trenéra {skill:186} tvé frakce.",
	["At 65 a {skill:186} trainer teaches {spell:2659} (2s; grey at 115) and {spell:3304} (50c; grey at 75): smelting at a forge raises {skill:186} too, so smelt what you mine."] = "Na 65 naučí trenér {skill:186} {spell:2659} (2s; šedé na 115) a {spell:3304} (50c; šedé na 75): tavení u výhně taky zvedá {skill:186}, tak taví, co natěžíš.",
	["Copper"] = "Měď",
	["Copper & Poor Copper: {zone:1411} (1-50)"] = "Měď a Poor Copper: {zone:1411} (1–50)",
	["Copper & Poor Copper: {zone:1411} (50-65) cont."] = "Měď a Poor Copper: {zone:1411} (50–65), pokračování",
	["Copper & Poor Copper: {zone:1420} (1-50)"] = "Měď a Poor Copper: {zone:1420} (1–50)",
	["Copper & Poor Copper: {zone:1420} (50-65) cont."] = "Měď a Poor Copper: {zone:1420} (50–65), pokračování",
	["Copper & Poor Copper: {zone:1426} (1-50)"] = "Měď a Poor Copper: {zone:1426} (1–50)",
	["Copper & Poor Copper: {zone:1426} (50-65) cont."] = "Měď a Poor Copper: {zone:1426} (50–65), pokračování",
	["Copper & Tin: {zone:1413} (65-125)"] = "Měď a cín: {zone:1413} (65–125)",
	["Copper, Poor Copper"] = "Měď, Poor Copper",
	["Copper, Tin"] = "Měď, cín",
	["Copper: {zone:1412} (1-50)"] = "Měď: {zone:1412} (1–50)",
	["Copper: {zone:1412} (50-65) cont."] = "Měď: {zone:1412} (50–65), pokračování",
	["Copper: {zone:1429} (1-50)"] = "Měď: {zone:1429} (1–50)",
	["Copper: {zone:1429} (50-65) cont."] = "Měď: {zone:1429} (50–65), pokračování",
	["Copper: {zone:2521} (1-50)"] = "Měď: {zone:2521} (1–50)",
	["Copper: {zone:2521} (50-65) cont."] = "Měď: {zone:2521} (50–65), pokračování",
	["Expert {skill:186}"] = "Expert {skill:186}",
	["Expert {skill:186} raises the cap to 225; it needs skill 125 and no character level, and costs 50s: train it as soon as you reach 125. The arrow picks the nearest {skill:186} trainer of your faction. Learn {spell:3307} (5s; orange to 130, grey at 140) on the same visit: smelting at a forge raises {skill:186} too, so smelt what you mine."] = "Expert {skill:186} zvedne strop na 225; potřebuje dovednost 125 a žádný level postavy a stojí 50s: vytrénuj ho, jakmile dosáhneš 125. Šipka vybere nejbližšího trenéra {skill:186} tvé frakce. Při stejné návštěvě se nauč {spell:3307} (5s; oranžový do 130, šedý na 140): tavení u výhně zvedá {skill:186} taky, takže přetavuj, co vytěžíš.",
	["Journeyman {skill:186}"] = "Journeyman {skill:186}",
	["Learn {skill:186}"] = "Nauč se {skill:186}",
}
t.guides["forever/professions/skinning"] = {
	["Any {skill:393} trainer of your faction teaches Apprentice {skill:393} at any level (10c), and so does the Junior Skinning Trainer in each starting area; the arrow picks the nearest. Buy a {item:7005} from a trade goods or general vendor: keep it in your bags, you cannot skin without it. The first-hour quest of each starting area (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) offers {item:247846} as a reward: reading it gives 2 skill, up to 15. Trade goods vendors and the junior trainers sell the {item:277114}, a four-slot bag for leather and hides (25c). If you sat at your starting area's campfire for The Great Outdoors, the camping guide there also offers Camping 101: {skill:393}: hand it in to the skinning trainer it names once you reach skill 20, for the {spell:1229517} recipe."] = "Apprentice {skill:393} naučí na jakémkoli levelu (10c) kterýkoli trenér {skill:393} tvé frakce i Junior Skinning Trainer v každé startovní oblasti; šipka vybere nejbližšího. Kup {item:7005} u obchodníka se surovinami nebo smíšeným zbožím: nech si ho v taškách, bez něj stahovat nejde. Quest první hodiny každé startovní oblasti (Rascally Rodents, Coldridge Valley Mail Delivery, The Woodland Protector, Galgar's {item:11584}, A Humble Task, Marla's Last Wish) nabízí jako odměnu {item:247846}: přečtení dá 2 dovednosti, až do 15. Obchodníci se surovinami a junior trenéři prodávají {item:277114}, čtyřmístný vak na kůže (25c). Pokud sis sedl k táboráku své startovní oblasti kvůli The Great Outdoors, tamní průvodce kempováním nabízí i Camping 101: {skill:393}: odevzdej ho trenérovi stahování, kterého jmenuje, až budeš mít dovednost 20, za recept {spell:1229517}.",
