t.guides["forever/professions/tailoring"] = {
	["124 {item:14227} for {item:13867}: it drops from {npc:11739} (level 57-59) at the marked spot."] = "124 {item:14227} pro {item:13867}: dropuje z {npc:11739} (level 57–59) na označeném místě.",
	["124 {item:14227} for {item:13867}: it drops from {npc:1824} (level 54-55) at the marked spot."] = "124 {item:14227} pro {item:13867}: dropuje z {npc:1824} (level 54–55) na označeném místě.",
	["144 {item:2589} for {spell:2387} and {item:7026}: humanoids of level 5-20 drop it. Keep what you loot as you level, or take it from your bank."] = "144 {item:2589} pro {spell:2387} a {item:7026}: dropují ho humanoidi levelu 5–20. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["204 {item:4306} for {spell:3871}: humanoids of level 25-45 drop it. Keep what you loot as you level, or take it from your bank."] = "204 {item:4306} pro {spell:3871}: dropují ho humanoidi levelu 25–45. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["264 {item:4306} for {item:7053}: humanoids of level 25-45 drop it. Keep what you loot as you level, or take it from your bank."] = "264 {item:4306} pro {item:7053}: dropují ho humanoidi levelu 25–45. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["3195 {item:14047} for {item:13856}, {item:13863} and {item:13867}: humanoids of level 45-60 drop it. Keep what you loot as you level, or take it from your bank."] = "3195 {item:14047} pro {item:13856}, {item:13863} a {item:13867}: dropují ho humanoidi levelu 45–60. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["420 {item:8170} for {item:13863} and {item:13867}: {skill:393}: beasts of level 48-60. Skin {npc:6369}, {npc:8760}, {npc:6380}, {npc:6379}, {npc:6378} and {npc:6377} here (level 48-60); the {skill:393} guide routes this."] = "420 {item:8170} pro {item:13863} a {item:13867}: {skill:393}: zvířata levelu 48–60. Stahuj {npc:6369}, {npc:8760}, {npc:6380}, {npc:6379}, {npc:6378} a {npc:6377} tady (level 48–60); trasu vede návod na {skill:393}.",
	["420 {item:8170} for {item:13863} and {item:13867}: {skill:393}: beasts of level 48-60. Skin {npc:8598}, Plaguehound and {npc:8596} here (level 48-60); the {skill:393} guide routes this."] = "420 {item:8170} pro {item:13863} a {item:13867}: {skill:393}: zvířata levelu 48–60. Stahuj {npc:8598}, Plaguehound a {npc:8596} tady (level 48–60); trasu vede návod na {skill:393}.",
	["567 {item:2592} for {spell:2402} and {spell:3866}: humanoids of level 15-30 drop it. Keep what you loot as you level, or take it from your bank."] = "567 {item:2592} pro {spell:2402} a {spell:3866}: dropují ho humanoidi levelu 15–30. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["900 {item:4338} for {item:9998} and {item:10024}: humanoids of level 35-50 drop it. Keep what you loot as you level, or take it from your bank."] = "900 {item:4338} pro {item:9998} a {item:10024}: dropují ho humanoidi levelu 35–50. Nech si, co nalootuješ při levelování, nebo si ho vezmi z banky.",
	["Apprentice {skill:197} lets you craft up to 75 for 10c, at any character level. Any {skill:197} trainer of your faction teaches it; the arrow picks the nearest. Keep every {item:2589} you loot: humanoids of level 5-20 drop it. 1-75 takes about 50c of recipes and 7s 20c of vendor goods, plus 144 {item:2589} to gather or buy."] = "Apprentice {skill:197} ti dovolí vyrábět až do 75 za 10c, na jakémkoli levelu postavy. Naučí ho kterýkoli trenér {skill:197} tvé frakce; šipka vybere nejbližšího. Nech si každý {item:2589}, který nalootuješ: dropují ho humanoidi levelu 5–20. 1–75 stojí asi 50c za recepty a 7s 20c za zboží od obchodníků, plus 144 {item:2589} k nasbírání nebo koupi.",
	["Artisan raises the cap from 225 to 300; it needs {skill:197} 200 and character level 35, so you can take it on any visit from 200. Only a few trainers teach it: Alliance {npc:11052} ({zone:1445}); Horde {npc:2399} ({zone:1424}). The arrow picks the nearest of your faction. Learn now: {spell:18401} (from 205) and {spell:18402} (from 210). 225-300 takes about 1g 60s of recipes and 58g of vendor goods, plus 420 {item:8170}, 3195 {item:14047} and 124 {item:14227} to gather or buy."] = "Artisan zvedne strop z 225 na 300; potřebuje {skill:197} 200 a level postavy 35, takže ho můžeš vzít při jakékoli návštěvě od 200. Učí ho jen pár trenérů: Aliance {npc:11052} ({zone:1445}); Horda {npc:2399} ({zone:1424}). Šipka vybere nejbližšího z tvé frakce. Nauč se teď: {spell:18401} (od 205) a {spell:18402} (od 210). 225–300 stojí asi 1g 60s za recepty a 58g za zboží od obchodníků, plus 420 {item:8170}, 3195 {item:14047} a 124 {item:14227} k nasbírání nebo koupi.",
	["Artisan {skill:197}"] = "Artisan {skill:197}",
	["Back to a {skill:197} trainer: {spell:3839} (from 100, 5s) and {spell:3871} (from 135)."] = "Zpět k trenérovi {skill:197}: {spell:3839} (od 100, 5s) a {spell:3871} (od 135).",
	["Back to a {skill:197} trainer: {spell:3866} (from 85, 2s 50c)."] = "Zpět k trenérovi {skill:197}: {spell:3866} (od 85, 2s 50c).",
	["Back to a {skill:197} trainer: {spell:8776} (from 15, 50c)."] = "Zpět k trenérovi {skill:197}: {spell:8776} (od 15, 50c).",
	["Buy the whole bracket's share in one go: 108 {item:2321} (1g 8s), 34 {item:2324} (8s 50c) and 98 {item:2604} (49s); about 1g 65s 50c in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1347}, {npc:1286} and {npc:5565}; {zone:1454}: {npc:3364}, Felika and {npc:5817})."] = "Kup podíl celého pásma najednou: 108 {item:2321} (1g 8s), 34 {item:2324} (8s 50c) a 98 {item:2604} (49s); celkem asi 1g 65s 50c. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1347}, {npc:1286} a {npc:5565}; {zone:1454}: {npc:3364}, Felika a {npc:5817}).",
	["Buy the whole bracket's share in one go: 116 {item:14341} (58g); about 58g in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1347}, {npc:1286} and {npc:5565}; {zone:1454}: {npc:3364}, Felika and {npc:5817})."] = "Kup podíl celého pásma najednou: 116 {item:14341} (58g); celkem asi 58g. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1347}, {npc:1286} a {npc:5565}; {zone:1454}: {npc:3364}, Felika a {npc:5817}).",
	["Buy the whole bracket's share in one go: 44 {item:2321} (44s), 90 {item:4291} (4g 50s), 44 {item:6260} (22s) and 80 {item:8343} (16g); about 21g 16s in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1347}, {npc:1286} and {npc:5565}; {zone:1454}: {npc:3364}, Felika and {npc:5817})."] = "Kup podíl celého pásma najednou: 44 {item:2321} (44s), 90 {item:4291} (4g 50s), 44 {item:6260} (22s) a 80 {item:8343} (16g); celkem asi 21g 16s. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1347}, {npc:1286} a {npc:5565}; {zone:1454}: {npc:3364}, Felika a {npc:5817}).",
	["Buy the whole bracket's share in one go: 72 {item:2320} (7s 20c); about 7s 20c in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1347}, {npc:1286} and {npc:5565}; {zone:1454}: {npc:3364}, Felika and {npc:5817})."] = "Kup podíl celého pásma najednou: 72 {item:2320} (7s 20c); celkem asi 7s 20c. Šipka vybere nejbližšího prodejce tvé frakce ({zone:1453}: {npc:1347}, {npc:1286} a {npc:5565}; {zone:1454}: {npc:3364}, Felika a {npc:5817}).",
	["Expert raises the cap from 150 to 225; it needs {skill:197} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:1346} ({zone:1453}); Horde {npc:4576} ({zone:1458}). The arrow picks the nearest of your faction. Learn now: {spell:3865} (from 140). 150-225 takes about 15s of recipes and 21g 16s of vendor goods, plus 264 {item:4306} and 900 {item:4338} to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach {item:9998} (from 170), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 2. {item:10024} (from 190) takes a second trip, to other trainers (below)."] = "Expert zvedne strop ze 150 na 225; potřebuje {skill:197} 125 a level postavy 20, takže ho můžeš vzít při jakékoli návštěvě od 125. Učí ho jen pár trenérů: Aliance {npc:1346} ({zone:1453}); Horda {npc:4576} ({zone:1458}). Šipka vybere nejbližšího z tvé frakce. Nauč se teď: {spell:3865} (od 140). 150–225 stojí asi 15s za recepty a 21g 16s za zboží od obchodníků, plus 264 {item:4306} a 900 {item:4338} k nasbírání nebo koupi. Přijď se vším v taškách (kroky výše, zbytek z aukce): tihle trenéři učí i {item:9998} (od 170) a výroba nepotřebuje stanici, takže vyráběj přímo tady a každý recept se nauč, jakmile dosáhneš jeho dovednosti. Jedna cesta místo 2. {item:10024} (od 190) znamená druhou cestu, k jiným trenérům (níže).",
	["Expert {skill:197}"] = "Expert {skill:197}",
	["Journeyman {skill:197}"] = "Journeyman {skill:197}",
	["Learn {skill:197}"] = "Nauč se {skill:197}",
	["Still at the Expert trainer: {spell:12048} (from 170)."] = "Pořád u trenéra Expert: {spell:12048} (od 170).",
	["What 150-225 takes that the Auction House sells: 264 {item:4306} and 900 {item:4338}. The counts drop by what your bags, bank and mail hold."] = "Co 150–225 potřebuje a aukce prodává: 264 {item:4306} a 900 {item:4338}. Počty se sníží o to, co máš v taškách, bance a poště.",
	["What 75-150 takes that the Auction House sells: 567 {item:2592} and 204 {item:4306}. The counts drop by what your bags, bank and mail hold."] = "Co 75–150 potřebuje a aukce prodává: 567 {item:2592} a 204 {item:4306}. Počty se sníží o to, co máš v taškách, bance a poště.",
