t.guides["forever/reputation/arathi-basin"] = {
	["Arathi Basin Reputation"] = "Reputace Arathi Basin",
	["Assault the Blacksmith banner"] = "Zaútoč na prapor Blacksmith",
	["Assault the Farm banner"] = "Zaútoč na prapor Farm",
	["Assault the Mine banner"] = "Zaútoč na prapor Mine",
	["Assault the Stables banner"] = "Zaútoč na prapor Stables",
	["Assault the {area:3422} banner"] = "Zaútoč na prapor {area:3422}",
	["Assaulting a base means clicking its banner until it turns: you need not hold it. Four marks in all: one for {npc:14984}, three for the Brigadier General. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 {zone:1461} marks: hand in or spend them before you reach that."] = "Útok na základnu znamená klikat na její prapor, dokud se neotočí: držet ji nemusíš. Celkem čtyři marky: jeden pro {npc:14984}, tři pro Brigadier General. PvP výbava ve Foreveru stojí kromě honoru i Marks of Honor: než je odevzdáš, rozmysli si, co chceš. Marků {zone:1461} uneseš nejvýš 30: odevzdej nebo utrať je dřív.",
	["Assaulting a base means clicking its banner until it turns: you need not hold it. Four marks in all: one for {npc:15022}, three for the Warbringer. Forever's PvP gear also costs Marks of Honor along with honor: decide what you want before you hand them in. You can carry at most 30 {zone:1461} marks: hand in or spend them before you reach that."] = "Útok na základnu znamená klikat na její prapor, dokud se neotočí: držet ji nemusíš. Celkem čtyři marky: jeden pro {npc:15022}, tři pro Warbringera. PvP výbava ve Foreveru stojí kromě honoru i Marks of Honor: než je odevzdáš, rozmysli si, co chceš. Marků {zone:1461} uneseš nejvýš 30: odevzdej nebo utrať je dřív.",
	["At Exalted, {npc:14983} asks your team to hold all five bases at the same time. It pays 200 reputation and the {item:20132}, the only way to get it."] = "Na Exalted chce {npc:14983}, aby tvůj tým držel všech pět základen najednou. Platí 200 reputace a {item:20132}, jediný způsob, jak ho získat.",
	["At Exalted, {npc:15021} asks your team to hold all five bases at the same time. It pays 200 reputation and the {item:20131}, the only way to get it."] = "Na Exalted chce {npc:15021}, aby tvůj tým držel všech pět základen najednou. Platí 200 reputace a {item:20131}, jediný způsob, jak ho získat.",
	["At level 60 and Friendly, {npc:14983} asks your team to hold four bases at the same time: 200 reputation, once. It opens {quest:8115} for Exalted."] = "Na levelu 60 a Friendly chce {npc:14983}, aby tvůj tým držel čtyři základny najednou: 200 reputace, jednou. Otevře {quest:8115} pro Exalted.",
	["At level 60 and Friendly, {npc:15021} asks your team to hold four bases at the same time: 200 reputation, once. It opens {quest:8122} for Exalted."] = "Na levelu 60 a Friendly chce {npc:15021}, aby tvůj tým držel čtyři základny najednou: 200 reputace, jednou. Otevře {quest:8122} pro Exalted.",
	["Back to {area:320}"] = "Zpět do {area:320}",
	["Back to {area:321}"] = "Zpět do {area:321}",
	["Every 200 resources your team gathers pays it; Exalted gives a Legacy Point, epic shoulders and the tabard."] = "Každých 200 surovin, které tvůj tým nasbírá, ho zaplatí; Exalted dá Legacy Point, epická ramena a tabard.",
	["Exalted gives the Legacy Point \"Master of Arathi Basin\" and opens the epics: the level 60 Defiler's shoulders in every armor type (12g75s to 20g), {item:20068} (13g18s), {item:20069} (50g46s) and Mindfang (42g83s), both from level 55."] = "Exalted dá Legacy Point „Master of Arathi Basin“ a otevře epiky: ramena Defiler's levelu 60 ve všech typech zbroje (12g75s až 20g), {item:20068} (13g18s), {item:20069} (50g46s) a Mindfang (42g83s), oboje od levelu 55.",
	["Exalted gives the Legacy Point \"Master of Arathi Basin\" and opens the epics: the level 60 Highlander's shoulders in every armor type (12g33s to 18g50s), {item:20073} (12g14s), {item:20069} (55g10s) and Sageclaw (44g24s), both from level 55."] = "Exalted dá Legacy Point „Master of Arathi Basin“ a otevře epiky: ramena Highlander's levelu 60 ve všech typech zbroje (12g33s až 18g50s), {item:20073} (12g14s), {item:20069} (55g10s) a Sageclaw (44g24s), oboje od levelu 55.",
