t.guides["forever/reputation/argent-dawn"] = {
	["Argent Dawn Reputation"] = "Reputace Argent Dawn",
	["Argent Dawn Valor Tokens"] = "Argent Dawn Valor Tokens",
	["Argent Dawn Valor Tokens, from the stone turn-ins"] = "Argent Dawn Valor Tokens za odevzdané kameny",
	["At Exalted, {npc:11536} takes 25 Argent Dawn Valor Tokens for the {quest:5517} (150 reputation): +5 to every resistance, on your shoulders. After it, the quartermasters sell more for 40 gold each."] = "Na Exalted vezme {npc:11536} 25 Argent Dawn Valor Tokens za {quest:5517} (150 reputace): +5 ke každé odolnosti, na ramena. Potom quartermasteři prodávají další po 40 zlatých.",
	["At Revered, {npc:11536} takes 10 Argent Dawn Valor Tokens for {quest:5513} (100 reputation). After it, any {faction:529} quartermaster sells the five shoulder enchants for 10 gold each: Flame, Frost, Arcane, Nature and {item:18173}, +5 to that resistance. Revered also opens the {item:13810} and its juice (60 silver) and the Revered recipes."] = "Na Revered vezme {npc:11536} 10 Argent Dawn Valor Tokens za {quest:5513} (100 reputace). Potom kterýkoli quartermaster {faction:529} prodává pět očarování ramen po 10 zlatých: Flame, Frost, Arcane, Nature a {item:18173}, +5 k té odolnosti. Revered otevře i {item:13810} a jeho šťávu (60 stříbrných) a recepty Revered.",
	["Back at {area:2268}"] = "Zpět v {area:2268}",
	["Dark Adepts and Shadowmages at {area:2272}"] = "Dark Adepts a Shadowmages u {area:2272}",
	["Ectoplasmic Resonators: the ghosts around the cauldron"] = "Ectoplasmic Resonators: duchové kolem kotle",
	["Every Scourge kill in the Plaguelands gives 5 reputation (named ones 15), from the level 50 ghouls and skeletons up; at level 60 pick the level 53 and up ones, since in Classic grey mobs give only about a fifth. Neutral to Friendly is 2,800: about 560 kills, fewer with the Plaguelands quests on the way. The densest Scourge stand around the four Scourge Cauldrons: {area:199} west of Andorhal (skeletons, 50-53), {area:200} north of Andorhal (zombies and ghouls, 52-55), the {area:202} in the south (ghouls, 54-55) and {area:201} in the east (ghosts, 56-57). Keep every Scourgestone and every quest you can save: turn-ins never stop counting, kills do. {quest:5510} drop from about four in ten of these Scourge, Invader's from about a third of the level 56 and up ones. If you die, take the Commission off and put it back on: it can lose its effect. Paladins (Human and Dwarf): {npc:10838} at {area:3197} asks 20 {quest:5510} once for Dispelling Evil, 100 reputation instead of 25. The Legacy perk Diplomat adds up to 10% to every gain."] = "Každé zabití Scourge v Plaguelands dá 5 reputace (pojmenovaní 15), od ghúlů a kostlivců levelu 50 výš; na levelu 60 vybírej ty od levelu 53, protože v Classicu dávají šedí mobové jen asi pětinu. Z Neutral na Friendly je to 2 800: asi 560 zabití, méně s questy Plaguelands po cestě. Nejhustěji stojí Scourge kolem čtyř Scourge Cauldrons: {area:199} západně od Andorhalu (kostlivci, 50–53), {area:200} severně od Andorhalu (zombie a ghúlové, 52–55), {area:202} na jihu (ghúlové, 54–55) a {area:201} na východě (duchové, 56–57). Nech si každý Scourgestone a každý quest, který jde odložit: odevzdání se nikdy nepřestanou počítat, zabití ano. {quest:5510} padají zhruba ze čtyř z deseti těchto Scourge, Invader's zhruba z třetiny těch od levelu 56. Když zemřeš, Commission sundej a znovu nasaď: může ztratit účinek. Paladinové (Člověk a Trpaslík): {npc:10838} v {area:3197} jednou chce 20 {quest:5510} za Dispelling Evil, 100 reputace místo 25. Legacy perk Diplomat přidá ke každému zisku až 10 %.",
	["{item:19446}, 3 gold"] = "{item:19446}, 3 zlata",
	["{item:19447}, 6 gold"] = "{item:19447}, 6 zlata",
	["{quest:5401} (Alliance)"] = "{quest:5401} (Aliance)",
	["{quest:5405} (Horde)"] = "{quest:5405} (Horda)",
}
t.guides["forever/reputation/bloodsail-buccaneers"] = {
	["\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of {area:35}. {area:35} players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while {area:35} is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with {area:35}."] = "\"Pretty Boy\" Duncan, pirát Bloodsail, stojí na pláži severně od {area:35}. Hráči z {area:35} ho zabíjejí kvůli questu: když tam není, počkej na něj. Od levelu 55 pro tebe má quest, dokud je {area:35} pod Neutral; je hotový, jakmile jsi Friendly s Bloodsail a Hated s {area:35}.",
	["At Neutral the Bloodsail crew stop attacking you. {npc:2546} is aboard the {area:1757}, the pirate ship anchored south of {area:35}, on its middle deck. Swim out; take the quest and hand it in on the spot for the {item:22746}: the {item:22742}, Sash, Pants and Boots."] = "Na Neutral na tebe posádka Bloodsail přestane útočit. {npc:2546} je na palubě {area:1757}, pirátské lodi kotvící jižně od {area:35}, na prostřední palubě. Doplav tam; vezmi quest a na místě ho odevzdej za {item:22746}: {item:22742}, Sash, Pants a Boots.",
	["Back to Firallon for the {item:12185} (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less {area:35}. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the {zone:1418}, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached."] = "Zpět k Firallonovi pro {item:12185} (v Classicu jeho použití přivolá papouška na rameno): o 200 víc Bloodsail a o 1 000 méně {area:35}. Bruiseři platí 25 jen do konce Honored a Jazzrik, osamělý goblin v {zone:1418}, 5 do konce Revered; žádný quest už nezbývá, takže Exalted dosáhnout nejde.",
	["Before you start"] = "Než začneš",
	["Bloodsail Buccaneers Reputation"] = "Reputace Bloodsail Buccaneers",
	["Bloodsail standing goes up only by killing the people of {area:35}, and every kill costs you {area:35} 125 and the other goblin towns ({area:976}, {area:392}, {area:2255}, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and {area:976}'s and {area:2255}'s auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. {area:35}'s guards are not your enemies yet: tick At War for {area:35} in your reputation panel, then attack."] = "Reputace u Bloodsail roste jen zabíjením lidí z {area:35} a každé zabití tě stojí 125 u {area:35} a asi 62 u každého dalšího goblinského města ({area:976}, {area:392}, {area:2255} a ve Foreveru nejspíš Powderfuse). Po Bruiserech, které tento návod chce, jsou všechna goblinská města Hated: jejich stráže na tebe útočí a přijdeš o jejich letové mistry, hostince, obchodníky a aukce v {area:976} a {area:2255}. Návrat trvá déle než cesta sem (poslední krok). Přileť, nastav si domov jinde a goblinská města si vyřiď předem. Oblek a klobouk potřebují jen Friendly; dál už Bloodsail nemá co dát. Stráže {area:35} ještě nejsou tvoji nepřátelé: v panelu reputace zaškrtni u {area:35} At War a pak útoč.",
	["Booty Bay Bruisers to Neutral"] = "Booty Bay Bruisers na Neutral",
	["Bruisers to Friendly"] = "Bruiseři na Friendly",
	["Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside {area:392}, {area:35}, {area:976} and {area:2255}, so the climb back is the Cartel's own: {npc:14637} in {zone:1444} serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give {area:35} 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did."] = "Každé goblinské město je teď Hated. Data questů Foreveru berou reputaci měst ze čtyř goblinských smiřovacích questů mimo {area:392}, {area:35}, {area:976} a {area:2255}, takže cesta zpět je jen přes Cartel: {npc:14637} v {zone:1444} obslouží každého a jeho questy Zapped Giants platí 25 všem městům naráz; piráti Bloodsail dají {area:35} po 5 až do konce Neutral (a stojí 25 u Bloodsail); piráti Southsea a Venture Co. ve Stranglethornu dají městům po 5. Podrobnosti má návod Steamwheedle Cartel. Počítej s tím, že to potrvá déle než válka.",
	["The {item:10030}"] = "{item:10030}",
	["{npc:2546}: the {item:22746}"] = "{npc:2546}: {item:22746}",
}
t.guides["forever/reputation/brood-of-nozdormu"] = {
	["10 (and 100 Cenarion Circle)"] = "10 (a 100 Cenarion Circle)",
	["100 (and 100 Cenarion Circle)"] = "100 (a 100 Cenarion Circle)",
	["200 (and 200 Cenarion Circle)"] = "200 (a 200 Cenarion Circle)",
	["A raid event: follow {npc:11832} toward {area:2361} and keep him alive against Eranikus and his nightmare adds until Tyrande arrives and redeems Eranikus. Do not kill Eranikus."] = "Raidová událost: doprovoď {npc:11832} k {area:2361} a udrž ho naživu proti Eranikovi a jeho nočním můrám, dokud nedorazí Tyrande a Eranika nevykoupí. Eranika nezabíjej.",
	["After The Path, Baristolth takes 200 more fragments for {quest:8302}: 200 reputation, again and again, but only until Neutral. From Hated 500 that is 208 turn-ins, 41,600 fragments, 20,000 to 30,000 elite kills: the only way without the Temple, and a very long one. With the {area:16076} open (a 40-player raid) it is far quicker: every Temple trash mob gives 100 until 2,999 of 3,000 Neutral, about 9,500 a full clear, so four to five clears reach Neutral. Save every {item:21230} and {item:21229} you loot until the trash stops counting: they pay the same later."] = "Po The Path bere Baristolth dalších 200 úlomků za {quest:8302}: 200 reputace, znovu a znovu, ale jen do Neutral. Z Hated 500 je to 208 odevzdání, 41 600 úlomků, 20 000 až 30 000 zabitých elit: jediná cesta bez Templu a velmi dlouhá. S otevřeným {area:16076} (raid pro 40 hráčů) je to mnohem rychlejší: každý trash mob v Templu dá 100 až do 2 999 z 3 000 Neutral, asi 9 500 za celý clear, takže na Neutral stačí čtyři až pět clearů. Šetři každý {item:21230} a {item:21229}, který nalootuješ, dokud trash přestane počítat: později platí stejně.",
	["At Exalted, {npc:15192} gives the last ring of your path: The Protector of Kalimdor, The Qiraji Conqueror or The Grand Invoker. Bring the Revered ring; 100 reputation."] = "Na Exalted dá {npc:15192} poslední prsten tvé cesty: The Protector of Kalimdor, The Qiraji Conqueror nebo The Grand Invoker. Přines prsten z Revered; 100 reputace.",
	["At Friendly, {npc:15192} upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation."] = "Na Friendly vylepší {npc:15192} prsten cesty, kterou sis vybral: The Path of the Protector, Conqueror nebo Invoker. Přines prsten, který nosíš; 100 reputace.",
	["At Honored, {npc:15192} upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation."] = "Na Honored vylepší {npc:15192} prsten cesty, kterou sis vybral: The Path of the Protector, Conqueror nebo Invoker. Přines prsten, který nosíš; 100 reputace.",
	["At Revered, {npc:15192} upgrades the ring of the path you chose: The Path of the Protector, Conqueror or Invoker. Bring the ring you wear; 100 reputation."] = "Na Revered vylepší {npc:15192} prsten cesty, kterou sis vybral: The Path of the Protector, Conqueror nebo Invoker. Přines prsten, který nosíš; 100 reputace.",
	["Back to Baristolth"] = "Zpět k Baristolthovi",
	["Back to {npc:11811}"] = "Zpět do {npc:11811}",
	["Baristolth in {area:3425}"] = "Baristolth v {area:3425}",
	["Brood of Nozdormu Reputation"] = "Reputace Brood of Nozdormu",
	["The {area:1121}"] = "{area:1121}",
	["The {npc:15624}"] = "{npc:15624}",
	["The {object:180633}"] = "{object:180633}",
}
t.guides["forever/reputation/cenarion-circle"] = {
	["10 texts: 100"] = "10 textů: 100",
	["3 crests and a {item:14344}: the Medallion of Station"] = "3 erby a {item:14344}: Medallion of Station",
	["3 signets and 5 Large Brilliant Shards: the Ring of Lordship"] = "3 pečetní prsteny a 5 Large Brilliant Shards: Ring of Lordship",
	["3 {quest:8363}: 100, Honored"] = "3 {quest:8363}: 100, Honored",
	["3 {quest:8364}: 150, Revered"] = "3 {quest:8364}: 150, Revered",
	["A 20-player raid behind the {area:2737} in the far south-west of {zone:1451}. A full clear is about 1,600 Cenarion reputation: the trash 3 each until 20,999 of 21,000 Revered, Kurinnaxx, Moam, Buru and Ayamiss 150 each and Ossirian 300, to Exalted. Ossirian's head starts {quest:8791} (200 here and 200 {npc:15185}). Their drops buy the ring (Honored), cloak (Revered) and weapon (Exalted) quests of {npc:15498}, {npc:15500} and {npc:15499} in the Hold, 100 reputation each. {npc:16091} in the Hold pays 100 once for {quest:9023}: {item:22217} from here and Venoxis's from {area:19}. {npc:15471} sells {item:22219} (Revered, 5g) and {item:22191} (Exalted, 8g) inside."] = "Raid pro 20 hráčů za {area:2737} na dalekém jihozápadě {zone:1451}. Celý clear dá asi 1 600 reputace Cenarion: trash po 3 až do 20 999 z 21 000 Revered, Kurinnaxx, Moam, Buru a Ayamiss po 150 a Ossirian 300, až do Exalted. Ossirianova hlava začíná {quest:8791} (200 tady a 200 {npc:15185}). Jejich dropy kupují questy na prsten (Honored), plášť (Revered) a zbraň (Exalted) od {npc:15498}, {npc:15500} a {npc:15499} v Hold, po 100 reputace. {npc:16091} v Hold jednou zaplatí 100 za {quest:9023}: {item:22217} odsud a Venoxisův z {area:19}. {npc:15471} uvnitř prodává {item:22219} (Revered, 5g) a {item:22191} (Exalted, 8g).",
	["Allegiance: one Combat, Logistics and Tactical badge, 200"] = "Věrnost: po jednom odznaku Combat, Logistics a Tactical, 200",
	["Around {area:3425}"] = "Okolí {area:3425}",
	["Back at the Hold"] = "Zpět v Hold",
	["Back to Ortell"] = "Zpět k Ortellovi",
	["Back to {area:3425}"] = "Zpět do {area:3425}",
	["Back to {area:3425} with news"] = "Zpět do {area:3425} se zprávami",
	["Bronzebeard's Encampment"] = "Bronzebeard's Encampment",
	["Cenarion Circle Reputation"] = "Reputace Cenarion Circle",
	["Cultists until the top of Friendly, texts saved"] = "Kultisté až do konce Friendly, texty schované",
	["Do the {zone:1422} and {area:2100} quests while you level; at 60 they may pay a fraction."] = "Questy {zone:1422} a {area:2100} dělej při levelování; na 60 můžou platit jen zlomek.",
	["Each Keeper is a level 60, not elite, alone at a camp edge, and always drops its chapter: Mayna in the far west camp, Havunth in the camp south-west of the Hold, Exeter in the far south-west camp beside the Twilight Lord."] = "Každý Keeper má level 60, není elitní, stojí sám na okraji tábora a vždy dropne svou kapitolu: Mayna v táboře na dalekém západě, Havunth v táboře jihozápadně od Hold, Exeter v táboře na dalekém jihozápadě vedle Twilight Lorda.",
	["The {area:3100}"] = "{area:3100}",
	["{item:20452}, from the {object:180503}"] = "{item:20452}, od {object:180503}",
	["{npc:11939} in {area:2361}"] = "{npc:11939} v {area:2361}",
	["{npc:15171} and {npc:15170}"] = "{npc:15171} a {npc:15170}",
	["{npc:15270}, Friendly"] = "{npc:15270}, Friendly",
	["{npc:15270}, Revered"] = "{npc:15270}, Revered",
	["{quest:8308}, a rare drop"] = "{quest:8308}, vzácný drop",
	["{quest:8319} to Revered"] = "{quest:8319} na Revered",
}
t.guides["forever/reputation/centaur-clans"] = {
	["12 recipes for {quest:93224} at the clan quartermasters, no standing needed"] = "12 receptů pro {quest:93224} u quartermasterů klanů, bez potřebné reputace",
	["At Honored and level 35, after {quest:92743}, {npc:5398} sends you to {npc:253136} at the south end of {area:604}, the northern mouth of the {quest:92841}. The valley steps follow Forever's quest data: nobody who records their play has done these quests yet, so a spot or the order may be off. Every valley quest asks you to stay Honored with the Magram, and each costs the Gelkis five times what it pays. Honored to Revered is 12,000; the valley pays 11,125 of it, {quest:92811} the rest."] = "Na Honored a levelu 35, po {quest:92743}, tě {npc:5398} pošle k {npc:253136} na jižní konec {area:604}, severní ústí {quest:92841}. Kroky v údolí sledují data questů Foreveru: nikdo, kdo nahrává svoje hraní, tyhle questy ještě nedělal, takže místo nebo pořadí může být mimo. Každý quest v údolí chce, abys zůstal Honored s Magram, a každý stojí Gelkis pětkrát tolik, kolik platí. Z Honored na Revered je to 12 000; údolí z toho zaplatí 11 125, {quest:92811} zbytek.",
	["At Honored and level 35, {npc:5397} sends you east to {npc:253177}, a Gelkis scout at the western mouth of the {quest:93034}, where the south of {zone:1443} runs into {zone:2652}. The valley steps follow Forever's quest data: nobody who records their play has done these quests yet, so a spot or the order may be off. Every valley quest asks you to stay Honored with the Gelkis, and each costs the Magram five times what it pays. Honored to Revered is 12,000; the valley pays 10,625 of it, {quest:92811} the rest."] = "Na Honored a levelu 35 tě {npc:5397} pošle na východ k {npc:253177}, zvědovi Gelkis u západního ústí {quest:93034}, kde jih {zone:1443} přechází do {zone:2652}. Kroky v údolí sledují data questů Foreveru: nikdo, kdo nahrává svoje hraní, tyhle questy ještě nedělal, takže místo nebo pořadí může být mimo. Každý quest v údolí chce, abys zůstal Honored s Gelkis, a každý stojí Magram pětkrát tolik, kolik platí. Z Honored na Revered je to 12 000; údolí z toho zaplatí 10 625, {quest:92811} zbytek.",
	["Back to {npc:5397}, then east to the {zone:1435}: {quest:1373} (level 37) waits by a black cauldron in {area:76}, north-east of {area:75}."] = "Zpět k {npc:5397}, pak na východ do {zone:1435}: {quest:1373} (level 37) čeká u černého kotle v {area:76}, severovýchodně od {area:75}.",
	["Both quartermasters sell the same 12 recipes for {quest:93224}, no standing needed: {item:273613} and - Lesser Healing Power; Greater Spellblasting and {item:250941}; {item:250538} and {item:250606} plans; {item:252462}, {item:253973}, {item:10011} and {item:274490} patterns; the {item:269900} and {item:269902} schematics. Keep the totems you need for them before you hand the rest in."] = "Oba quartermasteři prodávají stejných 12 receptů pro {quest:93224}, bez potřebné reputace: {item:273613} a - Lesser Healing Power; Greater Spellblasting a {item:250941}; plány {item:250538} a {item:250606}; vzory {item:252462}, {item:253973}, {item:10011} a {item:274490}; schémata {item:269900} a {item:269902}. Než odevzdáš zbytek, nech si totemy, které na ně potřebuješ.",
	["Gelkis: {area:604}"] = "Gelkis: {area:604}",
	["Gelkis: {npc:253177}"] = "Gelkis: {npc:253177}",
	["Gelkis: {npc:5601}"] = "Gelkis: {npc:5601}",
	["Gelkis: {quest:1373}"] = "Gelkis: {quest:1373}",
	["Gelkis: {quest:93041}"] = "Gelkis: {quest:93041}",
