t.guides["forever/reputation/darkspear-islands"] = {
	["Darkspear Islands Marks of Honor: play games"] = "Marks of Honor z Darkspear Islands: hraj zápasy",
	["Darkspear Islands Reputation"] = "Reputace Darkspear Islands",
	["Exalted gives the Legacy Point \"Master of Darkspear Islands\" and opens the epics: gloves in plate, mail, leather and cloth for levels 50 and 60 ({item:271940}, Gloves, Handguards and Handwraps, 3g94s to 15g16s) and level 60 shoulders in every armor type ({item:271955}, Shoulders, Spaulders, Mantle, Epaulets, Shoulderpads and Shoulderguards, 9g44s to 16g86s). The {item:276504} comes from a short questline that Exalted opens here."] = "Exalted dá Legacy Point „Master of Darkspear Islands“ a otevře epiky: rukavice v plátu, mailu, kůži a látce pro levely 50 a 60 ({item:271940}, Gloves, Handguards a Handwraps, 3g94s až 15g16s) a ramena levelu 60 ve všech typech zbroje ({item:271955}, Shoulders, Spaulders, Mantle, Epaulets, Shoulderpads a Shoulderguards, 9g44s až 16g86s). {item:276504} pochází z krátké série questů, kterou tady Exalted otevře.",
	["Exalted gives the Legacy Point \"Master of Darkspear Islands\" and opens the epics: gloves in plate, mail, leather and cloth for levels 50 and 60 ({item:272095}, Gloves, Handguards and Handwraps, 3g94s to 15g16s) and level 60 shoulders in every armor type ({item:272105}, Shoulders, Spaulders, Mantle, Epaulets, Shoulderpads and Shoulderguards, 9g44s to 16g86s). The {item:276502} comes from a short questline that Exalted opens here."] = "Exalted dá Legacy Point „Master of Darkspear Islands“ a otevře epiky: rukavice v plátu, mailu, kůži a látce pro levely 50 a 60 ({item:272095}, Gloves, Handguards a Handwraps, 3g94s až 15g16s) a ramena levelu 60 ve všech typech zbroje ({item:272105}, Shoulders, Spaulders, Mantle, Epaulets, Shoulderpads a Shoulderguards, 9g44s až 16g86s). {item:276502} pochází z krátké série questů, kterou tady Exalted otevře.",
