t.guides["forever/reputation/darkspear-trolls"] = {
	["A {npc:3118} may drop a {item:277661}: use it to start {quest:97281}. Once you hand that in, {npc:3293} offers {quest:97282}."] = "{npc:3118} může dropnout {item:277661}: použij ho na začátek {quest:97281}. Až ho odevzdáš, {npc:3293} nabídne {quest:97282}.",
	["Blackrock Mountain, with a group"] = "Blackrock Mountain, se skupinou",
	["Boars, weapons and peons"] = "Kanci, zbraně a peoni",
	["Darkspear Trolls Reputation"] = "Reputace Darkspear Trolls",
	["Darkspear reputation comes from quests and cloth. {npc:14727}, the Darkspear cloth quartermaster, stands in {zone:1454}'s {object:172961}. She takes four one-time donations of 60 cloth (150 each) and then {quest:7837}, 20 {item:14047} for 50, as often as you like. Every point you earn with the {faction:530} also gives a quarter as much to {zone:1454}, {zone:1456} and the {zone:1458}. While you level, do the Darkspear quests within 5 levels of them: {zone:1411} at 5 to 12, {area:414} in {zone:1440} at 19 to 27, {object:3202} in Stranglethorn at 34 to 46. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the Darkspear merchants sell to you for 10% less (the Classic rule), the raptor vendor included; at Exalted other races can buy the raptors: 20 gold for a level 40 raptor, 200 gold for a swift raptor at level 60, once you have mount training. The {faction:530} have no tabard or other reward."] = "Reputace Darkspear se získává z questů a látky. {npc:14727}, quartermasterka látky Darkspear, stojí v {object:172961} v {zone:1454}. Vezme čtyři jednorázové dary 60 látky (po 150) a pak {quest:7837}, 20 {item:14047} za 50, kolikrát chceš. Každý bod, který získáš u {faction:530}, dá navíc čtvrtinu i {zone:1454}, {zone:1456} a {zone:1458}. Při levelování dělej questy Darkspear do 5 levelů od nich: {zone:1411} na 5 až 12, {area:414} v {zone:1440} na 19 až 27, {object:3202} ve Stranglethornu na 34 až 46. Legacy perk Diplomat přidá až 10 %. Odměny: na Honored ti obchodníci Darkspear prodávají o 10 % levněji (pravidlo Classicu), včetně prodejce raptorů; na Exalted si raptory můžou koupit i jiné rasy: 20 zlatých za raptora na levelu 40, 200 zlatých za rychlého raptora na levelu 60, jakmile máš výcvik jízdy. {faction:530} nemají tabard ani jinou odměnu.",
	["Exalted with the {faction:530}"] = "Exalted u {faction:530}",
	["The {area:368}"] = "{area:368}",
	["{area:362} (optional hub)"] = "{area:362} (nepovinný uzel)",
	["{area:362}: hand in"] = "{area:362}: odevzdej",
	["{area:363} (optional hub)"] = "{area:363} (nepovinný uzel)",
	["{area:364}: hand in"] = "{area:364}: odevzdej",
	["{area:367} (optional hub)"] = "{area:367} (nepovinný uzel)",
