t.guides["forever/reputation/darnassus"] = {
	["About 3,700 {faction:69} reputation from low-level quests in {zone:1438} and {zone:1439}"] = "Asi 3 700 reputace u {faction:69} z nízkolevelových questů v {zone:1438} a {zone:1439}",
	["Capture a {npc:2164}"] = "Chyť {npc:2164}",
	["Cloth, {item:11040} and the {zone:1438} and {zone:1439} hubs: the quests pay most while you level."] = "Látka, {item:11040} a centra v {zone:1438} a {zone:1439}: questy platí nejvíc, dokud levelueš.",
	["Darnassus Reputation"] = "Reputace Darnassus",
	["Dig {quest:3764} from the dirt mounds all over the crater; most of the crater's beasts and the Gorishi silithids drop it too, about one kill in three. Take far more than 20: every pouch use takes 2, about 18 for each 10 {item:11040}."] = "Vykopej {quest:3764} z hromad hlíny po celém kráteru; dropuje ho i většina zvířat kráteru a silithidi Gorishi, zhruba jedno zabití ze tří. Vezmi mnohem víc než 20: každé použití váčku bere 2, asi 18 na každých 10 {item:11040}.",
	["Every 10 {item:11040}: 50 reputation at {npc:4217}. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 {quest:3764} and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the {item:14047}. {npc:7879} at {area:1116} in {zone:1444} takes {item:11040} at the same rate, 25 for 5, after his own quest."] = "Každých 10 {item:11040}: 50 reputace u {npc:4217}. Váček si nech a semínka kupuj průběžně. Je to pomalé: asi 9 pouzder, 90 minut čekání na váček, 18 {quest:3764} a 9 balíčků semínek na každé odevzdání, něco přes 30 reputace za hodinu, tak to dělej souběžně s {item:14047}. {npc:7879} v {area:1116} v {zone:1444} bere {item:11040} ve stejném poměru, 25 za 5, po svém vlastním questu.",
	["Exalted with {faction:69}: in Classic, other races may buy the nightsabers"] = "Exalted u {faction:69}: v Classicu si nightsabery mohou koupit i jiné rasy",
	["{area:188}: last hand-in"] = "{area:188}: poslední odevzdání",
	["{item:8050}, from {quest:2459}"] = "{item:8050}, od {quest:2459}",
	["{quest:7801} to Exalted"] = "{quest:7801} na Exalted",
	["{quest:7801} to Honored"] = "{quest:7801} na Honored",
	["{quest:7801} to Revered"] = "{quest:7801} na Revered",
}
