t.guides["forever/reputation/kirin-tor"] = {
	["Alliance Skyborne start Friendly with the {faction:2740}, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so {npc:32287} sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}, past the Sky Enclave. Buy the ones for your profession."] = "Skyborne Aliance začínají Friendly s {faction:2740} a jejich příchozí questy The Magical City of Dalaran a Exploring the Alliance dají každý dalších 100, takže {npc:32287} ti prodá recepty Azure hned (po 10g, potřebují dovednost 175). Stojí nahoře v budově s prapory {faction:2740} v {area:279}, za Sky Enclave. Kup si ty pro svoji profesi.",
	["Back to Modera's image"] = "Zpět k Moderinu obrazu",
	["Back to {npc:264265}"] = "Zpět do {npc:264265}",
