t.guides["forever/reputation/merchants-favor"] = {
	["A {item:7371} for the writ"] = "{item:7371} za výnos",
	["A {item:7371} for the writ again"] = "Znovu {item:7371} za výnos",
	["After the {quest:98247}, Friendly is 1000 more: 14 Journeyman writs, 8 Expert or 5 Artisan. Expert and Artisan customers are mostly not in Evertally's data yet: follow the mark the quest puts on your map. Journeyman envelopes drop from mobs of about level 11 to 31; Expert and Artisan ones from higher mobs."] = "Po {quest:98247} je Friendly o 1000 dál: 14 výnosů Journeyman, 8 Expert nebo 5 Artisan. Zákazníci Expert a Artisan většinou ještě nejsou v datech Evertally: sleduj značku, kterou quest dá na mapu. Obálky Journeyman padají z mobů zhruba levelu 11 až 31; Expert a Artisan z vyšších mobů.",
	["All five stand at the {area:2240} on the {area:439}, south-east of {area:484}: {npc:4720}, the chicken \"Plucky\" Johnson, {npc:4706}, the {npc:4496} and {npc:6548}. Customers show no quest mark: right-click them anyway."] = "Všech pět stojí u {area:2240} na {area:439}, jihovýchodně od {area:484}: {npc:4720}, kuře \"Plucky\" Johnson, {npc:4706}, {npc:4496} a {npc:6548}. Zákazníci nemají značku questu: klikni na ně pravým i tak.",
	["All four stand around {area:431}: {npc:257315} about 850 yards south-west of it, {npc:257322} to the south, the {npc:257316} about 350 yards south-east and {npc:257317} about 650 yards north-east. Customers show no quest mark: right-click them anyway."] = "Všichni čtyři stojí kolem {area:431}: {npc:257315} asi 850 yardů jihozápadně, {npc:257322} na jihu, {npc:257316} asi 350 yardů jihovýchodně a {npc:257317} asi 650 yardů severovýchodně. Zákazníci nemají značku questu: klikni na ně pravým i tak.",
	["Craftsman's Writs are the camp's reputation: 75 for a Journeyman writ, 125 for an Expert, 200 for an Artisan. Each asks for one crafted item, the one its title names. Make it or buy it on the Auction House; you need not know the profession. Each writ can be done once a day, and any number of different ones. Take the quest only of writs whose item you have or will buy on the way (right-click the writ), keep the writ in your bags, then tick this: the next steps lead to each customer you hold a writ for."] = "Craftsman's Writs jsou reputace tábora: 75 za výnos Journeyman, 125 za Expert, 200 za Artisan. Každý chce jeden vyrobený předmět, ten, který jmenuje název. Vyrob ho nebo kup v aukci; profesi znát nemusíš. Každý výnos jde udělat jednou denně a různých kolik chceš. Quest vezmi jen u výnosů, jejichž předmět máš nebo cestou koupíš (pravé tlačítko na výnos), výnos si nech v taškách a pak tohle odškrtni: další kroky vedou ke každému zákazníkovi, pro kterého máš výnos.",
	["Exalted"] = "Exalted",
	["Exalted opens the camp's tabard (200 Favor) at {npc:256389} or {npc:256384}, and the {item:262766} (6,000 Favor; the mount needs level 60 and Journeyman mount training) at {npc:256736} in {area:1002} or Okamache at the Crossroads camp. The {npc:10636} guide under Collectibles leads you there."] = "Exalted otevře tabard tábora (200 Favor) u {npc:256389} nebo {npc:256384} a {item:262766} (6 000 Favor; mount potřebuje level 60 a výcvik jízdy Journeyman) u {npc:256736} v {area:1002} nebo u Okamache v táboře Crossroads. Dovede tě tam návod {npc:10636} v sekci Sběratelské.",
	["{area:1002}: the {quest:98247}"] = "{area:1002}: {quest:98247}",
	["{item:10048}, 75 reputation"] = "{item:10048}, 75 reputace",
