	["500 reputation"] = "500 reputace",
	["Back to {area:16638}"] = "Zpět do {area:16638}",
	["Back to {npc:254151} inside the den. Ten ears for 1000 reputation and a green piece: leather gloves, cloth pants or mail boots. {npc:254151} then takes ears five at a time, for 1000 each, as often as you like, up to level 18; in Classic the pay drops from level 19 and is 200 from level 22. The Legacy perk Diplomat adds up to 10% to every gain."] = "Zpět k {npc:254151} do doupěte. Deset uší za 1000 reputace a zelený kus: kožené rukavice, látkové kalhoty nebo kroužkové boty. {npc:254151} pak bere uši po pěti, po 1000, kolikrát chceš, až do levelu 18; v Classicu odměna od levelu 19 klesá a od 22 je 200. Legacy perk Diplomat přidá ke každému zisku až 10 %.",
	["Ears at the {area:16629}"] = "Uši u {area:16629}",
	["Exalted opens the {item:280363}, green cloth shoulders for level 15, for 8s 16c."] = "Exalted otevře {item:280363}, zelená látková ramena pro level 15, za 8s 16c.",
	["The {item:280363}"] = "{item:280363}",
