t.guides["forever/reputation/ravenholdt"] = {
	["At level 50 your class trainer has another letter for you, and {npc:6768} a short chain: 360 reputation in all. The {quest:8234} drops from Timbermaw Shamans in northern {zone:1447} (about 1 in 27, or pick their pockets); the {quest:8235} from Forest Oozes in {zone:1447} (4 in 5). {quest:8236} comes from Morphaz, an elite drake deep in the {area:1477}: a five-player dungeon, group up."] = "Na levelu 50 pro tebe má trenér tvého povolání další dopis a {npc:6768} krátký řetěz: celkem 360 reputace. {quest:8234} padá z Timbermaw Shamans v severním {zone:1447} (zhruba 1 z 27, nebo jim vybírej kapsy); {quest:8235} z Forest Oozes v {zone:1447} (4 z 5). {quest:8236} je od Morphaze, elitního draka hluboko v {area:1477}: dungeon pro pět hráčů, sežeň skupinu.",
	["Back to {npc:13085}"] = "Zpět do {npc:13085}",
	["Everyone, not only rogues: in Classic every Syndicate human gave {faction:349} 5 reputation up to the end of Honored (11,999 of 12,000) and not one point more, so 0 to there is 4,200 kills (3,600 after a rogue's quests and emblems). This step ticks at Honored; keep killing until the bar stops moving, then go on to the junkboxes. The highest Syndicate are in the north-west of the {zone:1416}, Syndicate Assassins and Enforcers (level 38-40), with Syndicate Sentries (36-37) nearer the middle. At 60 all Syndicate are grey, and in Classic grey kills gave about a fifth: farm them before 48 if you can. Legacy Diplomat adds up to 10%."] = "Všichni, nejen rogue: v Classicu dal každý člověk Syndicate {faction:349} 5 reputace až do konce Honored (11 999 z 12 000) a ani bod víc, takže z 0 tam je to 4 200 zabití (3 600 po questech a emblémech rogue). Tento krok se odškrtne na Honored; zabíjej, dokud se lišta nepřestane hýbat, pak pokračuj na junkboxy. Nejvyšší Syndicate jsou na severozápadě {zone:1416}, Syndicate Assassins a Enforcers (level 38–40), se Syndicate Sentries (36–37) blíž ke středu. Na 60 jsou všichni Syndicate šedí a v Classicu dávala šedá zabití asi pětinu: farmi je před 48, pokud můžeš. Legacy Diplomat přidá až 10 %.",
	["{quest:6701} to Friendly"] = "{quest:6701} na Friendly",
}
t.guides["forever/reputation/steamwheedle-cartel"] = {
	["100 to every town"] = "100 u každého města",
	["25 to every town"] = "25 u každého města",
	["Back to {npc:10267}"] = "Zpět do {npc:10267}",
	["Back to {npc:14637}"] = "Zpět do {npc:14637}",
	["Black Broodlings in the north-east"] = "Black Broodlings na severovýchodě",
	["Dire Maul North: {npc:14338}"] = "Dire Maul North: {npc:14338}",
	["Every goblin town at once: {npc:14637}'s zapped giants and {npc:14338}'s shackles, then five new quartermasters and their hats."] = "Všechna goblinská města naráz: zapnutí obři {npc:14637} a okovy {npc:14338}, pak pět nových quartermasterů a jejich klobouky.",
	["Every town to Exalted"] = "Všechna města na Exalted",
	["Every town to Friendly"] = "Všechna města na Friendly",
	["Every town to Honored"] = "Všechna města na Honored",
	["Every town to Revered"] = "Všechna města na Revered",
	["Five goblin towns share one reputation family, the Steamwheedle Cartel: {faction:470}, {faction:21}, {faction:369}, {faction:577} and Forever's new {faction:2827} in the {zone:2548}. Everyone starts each at Neutral (500 into it). A gain with one town gives the others half as much; a quest for the Cartel itself, like {npc:14637}'s, pays every town in full. Losses spread the same way: a {npc:4624} or any goblin of the towns costs 125 (half that with the other towns), and Bloodsail Buccaneers reputation is earned only that way. {npc:14637} camps on the road through central {zone:1444} and works for anyone, even players the goblins hate. His first two quests are level 48 and open his repeatables (level 55); Forever pays all of them in full at any level."] = "Pět goblinních měst sdílí jednu reputační rodinu, Steamwheedle Cartel: {faction:470}, {faction:21}, {faction:369}, {faction:577} a nový {faction:2827} Foreveru v {zone:2548}. U každého začíná každý na Neutral (500 do něj). Zisk u jednoho města dá ostatním polovinu; quest pro samotný Cartel, třeba od {npc:14637}, zaplatí každému městu celou částku. Ztráty se šíří stejně: {npc:4624} nebo kterýkoli goblin z měst stojí 125 (u ostatních měst polovinu) a reputace Bloodsail Buccaneers se získává jen takhle. {npc:14637} táboří u cesty středem {zone:1444} a pracuje pro kohokoli, i pro hráče, které goblini nenávidí. Jeho první dva questy jsou levelu 48 a otevírají jeho opakovatelné questy (level 55); Forever je všechny platí v plné výši na jakémkoli levelu.",
	["{item:274021}, Revered"] = "{item:274021}, Revered",
