t.guides["forever/reputation/wintersaber-trainers"] = {
	["At Honored Rivern Frostwind adds {quest:5981}: 4 Frostmaul Giants and 4 Frostmaul Preservers, elite giants in {area:2249} in the south-east of {zone:1452}; the path down into the gorge starts at its north-west end. Take it on a trip south with a friend or two, or when {area:2244} is crowded; the {npc:7446} by the gorge drop {item:12622} most often. Honored to Exalted is 33,000: 660 turn-ins."] = "Na Honored přidá Rivern Frostwind {quest:5981}: 4 Frostmaul Giants a 4 Frostmaul Preservers, elitní obry v {area:2249} na jihovýchodě {zone:1452}; cesta dolů do soutěsky začíná na jejím severozápadním konci. Vezmi to na výlet na jih s kamarádem nebo dvěma, nebo když je {area:2244} přeplněné; {npc:7446} u soutěsky dropují {item:12622} nejčastěji. Z Honored na Exalted je to 33 000: 660 odevzdání.",
	["Back to {npc:10618}"] = "Zpět do {npc:10618}",
}
t.guides["forever/reputation/zandalar-tribe"] = {
	["25 and a token"] = "25 a žeton",
	["At Exalted your necklace takes its last upgrade, Rin'wosho sells {item:20013} (5g), and Rin'wosho trades 15 Zandalar Honor Tokens for one Signet of the Zandalar, the shoulder enchant: Might (attack power), Mojo (spell damage) or Serenity (healing)."] = "Na Exalted dostane tvůj náhrdelník poslední vylepšení, Rin'wosho prodává {item:20013} (5g) a Rin'wosho vymění 15 Zandalar Honor Tokens za jeden Signet of the Zandalar, očarování ramen: Might (attack power), Mojo (spell damage) nebo Serenity (léčení).",
	["At Friendly your class's trainer on the isle gives a necklace for free (100 reputation); the same NPC upgrades it at Honored, Revered and Exalted (100 each) with no raid item needed. Friendly also opens Rin'wosho's first recipes ({item:19766}, {item:19687}, {item:19778}, {item:19695}, {item:20001}, {item:20012}, 5g each; {item:20757}, 4g) and the Paragons of Power bracers (150 for the Primal Hakkari bracer token of your class)."] = "Na Friendly dá trenér tvého povolání na ostrově zdarma náhrdelník (100 reputace); stejné NPC ho vylepší na Honored, Revered a Exalted (po 100) bez potřeby raidového předmětu. Friendly otevře i první recepty Rin'wosho ({item:19766}, {item:19687}, {item:19778}, {item:19695}, {item:20001}, {item:20012}, po 5g; {item:20757}, 4g) a náramky Paragons of Power (150 za token Primal Hakkari bracer tvého povolání).",
	["Destroy one bijou at the {object:180367}, the stone altar on the west side of {area:3357} (right-click the bijou there), then tell {npc:15070}: 150 reputation and an extra {item:19858}, once. From then on every bijou you destroy at the altar pays 75 reputation and a token, and every set of three coins {npc:15070} takes pays 25 and a token. They never stop counting."] = "Znič jeden bijou u {object:180367}, kamenného oltáře na západní straně {area:3357} (pravé tlačítko na bijou tam), pak to řekni {npc:15070}: 150 reputace a {item:19858} navíc, jednou. Odteď každý bijou zničený u oltáře dá 75 reputace a žeton a každá sada tří mincí, kterou {npc:15070} vezme, dá 25 a žeton. Nikdy se nepřestanou počítat.",
	["Exalted: the {quest:8246}"] = "Exalted: {quest:8246}",
